import type { BankQuestion } from "@/lib/bank";

/** Clocks, Calendars and Cubes (Reasoning): 227 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"reason-clock-calendar-1","question":"What is the angle between the hands of a clock at 4:20?","options":["20°","0°","5°","10°"],"answer":3,"explanation":"Angle = |30H − 5.5M| = |120 − 110| = 10°. The hour hand has moved 10° past the 4 while the minute hand points at the 4.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 4:20 बजे घड़ी की सुइयों के बीच कितना कोण होता है?","optionsHi":["20°","0°","5°","10°"],"explanationHi":"कोण = |30H − 5.5M| = |120 − 110| = 10°। घंटे की सुई 4 से 10° आगे बढ़ चुकी है, जबकि मिनट की सुई 4 पर है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-2","question":"If 1 January 2021 was a Friday, what day of the week was 1 January 2022?","options":["Thursday","Sunday","Friday","Saturday"],"answer":3,"explanation":"2021 is not a leap year: 365 days = 52 weeks + 1 odd day, so the day moves one place to Saturday.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि 1 जनवरी 2021 को शुक्रवार था, तो 1 जनवरी 2022 को सप्ताह का कौन-सा दिन था?","optionsHi":["गुरुवार","रविवार","शुक्रवार","शनिवार"],"explanationHi":"2021 लीप वर्ष नहीं है: 365 दिन = 52 सप्ताह + 1 विषम दिन, इसलिए दिन एक स्थान आगे खिसककर शनिवार हो जाता है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-3","question":"A cube painted on all faces is cut into 27 identical smaller cubes. How many small cubes have three faces painted?","options":["6","12","8","1"],"answer":2,"explanation":"Only the corner cubes have three painted faces, and a cube always has 8 corners.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए एक घन को 27 एक जैसे छोटे घनों में काटा जाता है। कितने छोटे घनों के तीन फलक रंगे होंगे?","optionsHi":["6","12","8","1"],"explanationHi":"केवल कोने वाले घनों के तीन फलक रंगे होते हैं, और एक घन में हमेशा 8 कोने होते हैं।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-4","question":"How many times do the hour and minute hands of a clock coincide in a day (24 hours)?","options":["24","22","23","44"],"answer":1,"explanation":"They coincide 11 times every 12 hours (the 11–1 o’clock meeting is the single one at 12), so 22 times in a day.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक दिन (24 घंटे) में घड़ी की घंटे और मिनट की सुइयाँ कितनी बार एक-दूसरे पर संपाती होती हैं?","optionsHi":["24","22","23","44"],"explanationHi":"वे प्रत्येक 12 घंटे में 11 बार संपाती होती हैं (11 और 1 बजे के बीच का मिलन 12 बजे का एकमात्र मिलन है), इसलिए एक दिन में 22 बार।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-5","question":"What is the angle between the hands of a clock at 7:30?","options":["30°","45°","52.5°","60°"],"answer":1,"explanation":"Angle = |30H − 5.5M| = |210 − 165| = 45°. 60° ignores that the hour hand has moved halfway from 7 towards 8 (15°), and 30° or 52.5° are slips in that correction.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 7:30 बजे सुइयों के बीच कितना कोण होता है?","optionsHi":["30°","45°","52.5°","60°"],"explanationHi":"कोण = |30H − 5.5M| = |210 − 165| = 45°। 60° में यह छूट गया है कि घंटे की सुई 7 से 8 की ओर आधी दूरी (15°) चल चुकी है, और 30° या 52.5° इस सुधार में हुई चूकें हैं।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-6","question":"How many odd days are there in 100 years?","options":["3","4","6","5"],"answer":3,"explanation":"100 years have 24 leap years and 76 ordinary years: 24 × 2 + 76 = 124 odd days, and 124 = 17 weeks + 5, so 5 odd days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"100 वर्षों में कितने विषम दिन होते हैं?","optionsHi":["3","4","6","5"],"explanationHi":"100 वर्षों में 24 लीप वर्ष और 76 सामान्य वर्ष होते हैं: 24 × 2 + 76 = 124 विषम दिन, और 124 = 17 सप्ताह + 5, इसलिए 5 विषम दिन।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-7","question":"15 August 1947 was a Friday. What day of the week was 15 August 1948?","options":["Sunday","Monday","Friday","Saturday"],"answer":0,"explanation":"The year in between contains 29 February 1948, so it has 366 days = 2 odd days: Friday + 2 = Sunday.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"15 अगस्त 1947 को शुक्रवार था। 15 अगस्त 1948 को सप्ताह का कौन-सा दिन था?","optionsHi":["रविवार","सोमवार","शुक्रवार","शनिवार"],"explanationHi":"बीच के वर्ष में 29 फरवरी 1948 आती है, इसलिए उसमें 366 दिन = 2 विषम दिन हैं: शुक्रवार + 2 = रविवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-8","question":"A 4 × 4 × 4 cube painted on all faces is cut into 64 unit cubes. How many unit cubes have exactly two faces painted?","options":["36","12","8","24"],"answer":3,"explanation":"Two-face cubes lie on the edges, excluding corners: 12 edges × (4 − 2) = 24.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए 4 × 4 × 4 के घन को 64 इकाई घनों में काटा जाता है। कितने इकाई घनों के ठीक दो फलक रंगे होंगे?","optionsHi":["36","12","8","24"],"explanationHi":"दो फलक वाले घन कोनों को छोड़कर किनारों (कोरों) पर होते हैं: 12 किनारे × (4 − 2) = 24।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-9","question":"A clock shows 3:40. What time does its mirror image show?","options":["9:20","8:20","7:20","8:40"],"answer":1,"explanation":"For a mirror image subtract from 11:60: 11:60 − 3:40 = 8:20.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी में 3:40 बजे हैं। उसके दर्पण प्रतिबिंब में कितने बजे दिखेंगे?","optionsHi":["9:20","8:20","7:20","8:40"],"explanationHi":"दर्पण प्रतिबिंब के लिए 11:60 में से घटाएँ: 11:60 − 3:40 = 8:20।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-10","question":"A clock gains 5 minutes every hour. It is set right at 6 a.m. What time will it show at 6 p.m. the same day?","options":["7:05 p.m.","6:30 p.m.","7:00 p.m.","6:55 p.m."],"answer":2,"explanation":"In 12 hours it gains 12 × 5 = 60 minutes, so it shows 7:00 p.m.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी प्रति घंटे 5 मिनट तेज चलती है। इसे सुबह 6 बजे सही मिलाया जाता है। उसी दिन शाम 6 बजे यह कितने बजे दिखाएगी?","optionsHi":["शाम 7:05 बजे","शाम 6:30 बजे","शाम 7:00 बजे","शाम 6:55 बजे"],"explanationHi":"12 घंटे में यह 12 × 5 = 60 मिनट तेज हो जाती है, इसलिए यह शाम 7:00 बजे दिखाएगी।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-11","question":"What is the smaller angle between the hands of a clock at 9:15?","options":["165°","187.5°","172.5°","180°"],"answer":2,"explanation":"|30 × 9 − 5.5 × 15| = |270 − 82.5| = 187.5°, which is reflex; the smaller angle is 360 − 187.5 = 172.5°.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 9:15 बजे सुइयों के बीच छोटा कोण कितना होता है?","optionsHi":["165°","187.5°","172.5°","180°"],"explanationHi":"|30 × 9 − 5.5 × 15| = |270 − 82.5| = 187.5°, जो प्रतिवर्ती कोण है; छोटा कोण 360 − 187.5 = 172.5° है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-12","question":"If 7 March of a year is a Monday, what day of the week is 7 April of the same year?","options":["Wednesday","Tuesday","Thursday","Friday"],"answer":2,"explanation":"March has 31 days = 4 weeks + 3 odd days, so 7 April is Monday + 3 = Thursday.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि किसी वर्ष 7 मार्च को सोमवार है, तो उसी वर्ष 7 अप्रैल को सप्ताह का कौन-सा दिन होगा?","optionsHi":["बुधवार","मंगलवार","गुरुवार","शुक्रवार"],"explanationHi":"मार्च में 31 दिन = 4 सप्ताह + 3 विषम दिन होते हैं, इसलिए 7 अप्रैल को सोमवार + 3 = गुरुवार होगा।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-13","question":"At what time between 4 and 5 o’clock do the hands of a clock coincide?","options":["20 minutes past 4","21 9/11 minutes past 4","22 2/11 minutes past 4","21 3/11 minutes past 4"],"answer":1,"explanation":"The hands coincide when 5.5M = 30H, so M = 120/5.5 = 240/11 = 21 9/11 minutes past 4.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"4 और 5 बजे के बीच किस समय घड़ी की सुइयाँ संपाती होती हैं?","optionsHi":["20 मिनट (4 बजे के बाद)","21 9/11 मिनट (4 बजे के बाद)","22 2/11 मिनट (4 बजे के बाद)","21 3/11 मिनट (4 बजे के बाद)"],"explanationHi":"सुइयाँ तब संपाती होती हैं जब 5.5M = 30H, इसलिए M = 120/5.5 = 240/11 = 21 9/11 मिनट (4 बजे के बाद)।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-14","question":"At what time between 2 and 3 o’clock are the hands of a clock at right angles for the first time?","options":["25 5/11 minutes past 2","30 minutes past 2","10 10/11 minutes past 2","27 3/11 minutes past 2"],"answer":3,"explanation":"|60 − 5.5M| = 90 gives 5.5M = 150 (5.5M = −30 is impossible), so M = 300/11 = 27 3/11. That is the only right angle between 2 and 3 because at 2:00 the minute hand is 60° behind.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2 और 3 बजे के बीच किस समय घड़ी की सुइयाँ पहली बार समकोण पर होती हैं?","optionsHi":["25 5/11 मिनट (2 बजे के बाद)","30 मिनट (2 बजे के बाद)","10 10/11 मिनट (2 बजे के बाद)","27 3/11 मिनट (2 बजे के बाद)"],"explanationHi":"|60 − 5.5M| = 90 से 5.5M = 150 मिलता है (5.5M = −30 असंभव है), इसलिए M = 300/11 = 27 3/11। 2 और 3 बजे के बीच यही एकमात्र समकोण है क्योंकि 2:00 बजे मिनट की सुई 60° पीछे होती है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-15","question":"What day of the week was 26 January 1950?","options":["Thursday","Tuesday","Friday","Wednesday"],"answer":0,"explanation":"Odd days up to 1949: 1600 years → 0, 300 years → 1, 49 years (12 leap + 37 ordinary) → 61 → 5; total 6. Add 26 days of January → 5; 6 + 5 = 11 → 4 odd days → Thursday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"26 जनवरी 1950 को सप्ताह का कौन-सा दिन था?","optionsHi":["गुरुवार","मंगलवार","शुक्रवार","बुधवार"],"explanationHi":"1949 तक के विषम दिन: 1600 वर्ष → 0, 300 वर्ष → 1, 49 वर्ष (12 लीप + 37 सामान्य) → 61 → 5; कुल 6। जनवरी के 26 दिन जोड़ें → 5; 6 + 5 = 11 → 4 विषम दिन → गुरुवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-16","question":"A 5 × 5 × 5 cube painted on all faces is cut into 125 unit cubes. How many unit cubes have exactly one face painted?","options":["48","27","36","54"],"answer":3,"explanation":"Each face has a (5 − 2)² = 9 inner block of single-painted cubes: 6 × 9 = 54. 27 is the count with no paint.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए 5 × 5 × 5 के घन को 125 इकाई घनों में काटा जाता है। कितने इकाई घनों का ठीक एक फलक रंगा होगा?","optionsHi":["48","27","36","54"],"explanationHi":"प्रत्येक फलक पर एक फलक रंगे घनों का (5 − 2)² = 9 का भीतरी खंड होता है: 6 × 9 = 54। 27 बिना रंग वाले घनों की संख्या है।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-17","question":"A watch loses 2 minutes every hour. It is set right at 8 a.m. What is the correct time when the watch shows 2:46 p.m. the same day?","options":["3:14 p.m.","3:00 p.m.","3:02 p.m.","2:58 p.m."],"answer":1,"explanation":"The watch runs 58 minutes per real hour. It shows 6 h 46 min = 406 minutes elapsed, so real time = 406 × 60/58 = 420 minutes = 7 hours: 3:00 p.m.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी प्रति घंटे 2 मिनट धीमी चलती है। इसे सुबह 8 बजे सही मिलाया जाता है। उसी दिन जब घड़ी में अपराह्न 2:46 बजे हों, तो सही समय क्या होगा?","optionsHi":["अपराह्न 3:14 बजे","अपराह्न 3:00 बजे","अपराह्न 3:02 बजे","अपराह्न 2:58 बजे"],"explanationHi":"घड़ी प्रति वास्तविक घंटे 58 मिनट चलती है। वह 6 घंटे 46 मिनट = 406 मिनट बीते दिखाती है, इसलिए वास्तविक समय = 406 × 60/58 = 420 मिनट = 7 घंटे: अपराह्न 3:00 बजे।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-18","question":"The calendar of the year 2021 will repeat next in which year?","options":["2026","2030","2032","2027"],"answer":3,"explanation":"Odd days: 2021 (1), 2022 (1), 2023 (1), 2024 (2), 2025 (1), 2026 (1) = 7 ≡ 0, so 2027 also starts on a Friday and, like 2021, is not a leap year.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"वर्ष 2021 का कैलेंडर अगली बार किस वर्ष दोहराया जाएगा?","optionsHi":["2026","2030","2032","2027"],"explanationHi":"विषम दिन: 2021 (1), 2022 (1), 2023 (1), 2024 (2), 2025 (1), 2026 (1) = 7 ≡ 0, इसलिए 2027 भी शुक्रवार से शुरू होता है और 2021 की तरह लीप वर्ष नहीं है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-19","question":"The mirror image of a clock shows 2:25. What is the actual time?","options":["9:25","10:35","9:35","8:35"],"answer":2,"explanation":"For a mirror image, actual time = 11:60 − mirror time = 11:60 − 2:25 = 9:35. 9:25 subtracts only the hours, and 10:35 uses 12:60 instead of 11:60.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी के दर्पण प्रतिबिंब में 2:25 बजे दिख रहे हैं। वास्तविक समय क्या है?","optionsHi":["9:25","10:35","9:35","8:35"],"explanationHi":"दर्पण प्रतिबिंब के लिए वास्तविक समय = 11:60 − प्रतिबिंब का समय = 11:60 − 2:25 = 9:35। 9:25 में केवल घंटे घटाए गए हैं, और 10:35 में 11:60 के बजाय 12:60 लिया गया है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-20","question":"How many times in a day (24 hours) are the hands of a clock at right angles?","options":["22","48","44","24"],"answer":2,"explanation":"They are at right angles twice in every hour except near 3 and 9, where the two occurrences are shared: 22 times in 12 hours, 44 in a day.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक दिन (24 घंटे) में घड़ी की सुइयाँ कितनी बार समकोण पर होती हैं?","optionsHi":["22","48","44","24"],"explanationHi":"वे हर घंटे में दो बार समकोण पर होती हैं, सिवाय 3 और 9 के आसपास के, जहाँ दोनों घटनाएँ साझा हो जाती हैं: 12 घंटे में 22 बार, एक दिन में 44 बार।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-21","question":"If 1 January 2023 was a Sunday, what day of the week was 1 March 2024?","options":["Wednesday","Saturday","Friday","Thursday"],"answer":2,"explanation":"1 January 2024 is Sunday + 1 = Monday. From 1 January to 1 March 2024 is 31 + 29 = 60 days (2024 is a leap year) = 4 odd days, so Monday + 4 = Friday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि 1 जनवरी 2023 को रविवार था, तो 1 मार्च 2024 को सप्ताह का कौन-सा दिन था?","optionsHi":["बुधवार","शनिवार","शुक्रवार","गुरुवार"],"explanationHi":"1 जनवरी 2024 को रविवार + 1 = सोमवार है। 1 जनवरी से 1 मार्च 2024 तक 31 + 29 = 60 दिन हैं (2024 लीप वर्ष है) = 4 विषम दिन, इसलिए सोमवार + 4 = शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-22","question":"A cube is painted red on two opposite faces, blue on two other opposite faces and green on the remaining two. It is cut into 64 identical smaller cubes. How many small cubes have both red and blue paint but no green?","options":["16","4","8","12"],"answer":2,"explanation":"Red and blue faces meet along 4 edges, each 4 cubes long; the 2 end cubes of each edge are corners that also touch green, leaving 2 per edge: 4 × 2 = 8.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घन के दो सम्मुख फलक लाल, दो अन्य सम्मुख फलक नीले और शेष दो फलक हरे रंगे गए हैं। इसे 64 एक जैसे छोटे घनों में काटा जाता है। कितने छोटे घनों पर लाल और नीला दोनों रंग हैं, लेकिन हरा नहीं?","optionsHi":["16","4","8","12"],"explanationHi":"लाल और नीले फलक 4 किनारों पर मिलते हैं, प्रत्येक की लंबाई 4 घन है; प्रत्येक किनारे के 2 सिरे वाले घन कोने हैं जो हरे फलक को भी छूते हैं, इसलिए प्रत्येक किनारे पर 2 बचते हैं: 4 × 2 = 8।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-23","question":"What is the smaller angle between the hands of a clock at 10:25?","options":["157.5°","197.5°","162.5°","167.5°"],"answer":2,"explanation":"|30 × 10 − 5.5 × 25| = |300 − 137.5| = 162.5°, which is less than 180°.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 10:25 बजे सुइयों के बीच छोटा कोण कितना होता है?","optionsHi":["157.5°","197.5°","162.5°","167.5°"],"explanationHi":"|30 × 10 − 5.5 × 25| = |300 − 137.5| = 162.5°, जो 180° से कम है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-24","question":"If the day before yesterday was Thursday, what day will it be 61 days after tomorrow?","options":["Thursday","Wednesday","Friday","Saturday"],"answer":2,"explanation":"Today is Saturday, so tomorrow is Sunday. 61 = 8 weeks + 5 days, so Sunday + 5 = Friday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि परसों गुरुवार था, तो कल के 61 दिन बाद कौन-सा दिन होगा?","optionsHi":["गुरुवार","बुधवार","शुक्रवार","शनिवार"],"explanationHi":"आज शनिवार है, इसलिए कल रविवार है। 61 = 8 सप्ताह + 5 दिन, इसलिए रविवार + 5 = शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-25","question":"Between 5 and 6 o’clock, at what time are the hands of a clock exactly opposite each other?","options":["54 6/11 minutes past 5","49 1/11 minutes past 5","27 3/11 minutes past 5","At no time strictly between 5 and 6; it happens at 6:00"],"answer":3,"explanation":"Opposite means 5.5M − 150 = 180, so M = 60, which is 6:00 itself (the other branch gives a negative M). 27 3/11 is when they coincide, so they are never opposite strictly inside the hour.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"5 और 6 बजे के बीच किस समय घड़ी की सुइयाँ ठीक एक-दूसरे के विपरीत होती हैं?","optionsHi":["54 6/11 मिनट (5 बजे के बाद)","49 1/11 मिनट (5 बजे के बाद)","27 3/11 मिनट (5 बजे के बाद)","5 और 6 के बीच (दोनों सीमाओं को छोड़कर) किसी भी समय नहीं; यह 6:00 बजे होता है"],"explanationHi":"विपरीत होने का अर्थ है 5.5M − 150 = 180, इसलिए M = 60, जो स्वयं 6:00 बजे है (दूसरी शाखा से M ऋणात्मक आता है)। 27 3/11 वह समय है जब वे संपाती होती हैं, इसलिए वे इस घंटे के भीतर कभी विपरीत नहीं होतीं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-26","question":"A clock gains 15 minutes every 24 hours. It is set right at 9 a.m. on Monday. What is the true time when it shows 10 a.m. on Friday?","options":["9:15 a.m. Friday","8:59 a.m. Friday","9:45 a.m. Friday","9:00 a.m. Friday"],"answer":3,"explanation":"The clock shows 24 h 15 min for every 24 real hours (ratio 97 : 96). It shows 97 hours elapsed, so 96 real hours have passed: 9:00 a.m. Friday, when it has gained exactly 4 × 15 = 60 minutes.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी 24 घंटे में 15 मिनट तेज हो जाती है। इसे सोमवार सुबह 9 बजे सही मिलाया जाता है। जब यह शुक्रवार सुबह 10 बजे दिखाए, तो सही समय क्या होगा?","optionsHi":["शुक्रवार सुबह 9:15","शुक्रवार सुबह 8:59","शुक्रवार सुबह 9:45","शुक्रवार सुबह 9:00"],"explanationHi":"घड़ी हर 24 वास्तविक घंटों में 24 घंटे 15 मिनट दिखाती है (अनुपात 97 : 96)। वह 97 घंटे बीते दिखाती है, इसलिए 96 वास्तविक घंटे बीते हैं: शुक्रवार सुबह 9:00 बजे, जब वह ठीक 4 × 15 = 60 मिनट तेज हो चुकी होती है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-27","question":"How many times in a day (24 hours) are the hands of a clock in a straight line, either coinciding or pointing in opposite directions?","options":["44","24","22","48"],"answer":0,"explanation":"They coincide 22 times and are opposite 22 times in 24 hours, so they are in a straight line 44 times.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक दिन (24 घंटे) में घड़ी की सुइयाँ कितनी बार एक सरल रेखा में होती हैं, चाहे वे संपाती हों या विपरीत दिशाओं में हों?","optionsHi":["44","24","22","48"],"explanationHi":"24 घंटे में वे 22 बार संपाती होती हैं और 22 बार विपरीत होती हैं, इसलिए वे 44 बार एक सरल रेखा में होती हैं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-28","question":"What day of the week was 15 August 1972?","options":["Wednesday","Thursday","Monday","Tuesday"],"answer":3,"explanation":"Odd days to 1971: 1900 years → 1; 1901–1971 has 17 leap and 54 ordinary years → 88 → 4; total 5. In 1972 (leap) to 15 August: 31 + 29 + 31 + 30 + 31 + 30 + 31 + 15 = 228 days → 4 odd days. 5 + 4 = 9 → 2 → Tuesday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"15 अगस्त 1972 को सप्ताह का कौन-सा दिन था?","optionsHi":["बुधवार","गुरुवार","सोमवार","मंगलवार"],"explanationHi":"1971 तक के विषम दिन: 1900 वर्ष → 1; 1901–1971 में 17 लीप और 54 सामान्य वर्ष → 88 → 4; कुल 5। 1972 (लीप वर्ष) में 15 अगस्त तक: 31 + 29 + 31 + 30 + 31 + 30 + 31 + 15 = 228 दिन → 4 विषम दिन। 5 + 4 = 9 → 2 → मंगलवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-29","question":"A 6 × 6 × 6 cube painted on all faces is cut into 216 unit cubes. How many unit cubes have at least one face painted?","options":["160","152","144","64"],"answer":1,"explanation":"Unpainted cubes form the inner (6 − 2)³ = 64 block, so 216 − 64 = 152 have at least one painted face.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए 6 × 6 × 6 के घन को 216 इकाई घनों में काटा जाता है। कितने इकाई घनों का कम से कम एक फलक रंगा होगा?","optionsHi":["160","152","144","64"],"explanationHi":"बिना रंग वाले घन भीतरी (6 − 2)³ = 64 का खंड बनाते हैं, इसलिए 216 − 64 = 152 घनों का कम से कम एक फलक रंगा होता है।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-30","question":"A cuboid of 4 cm × 3 cm × 2 cm is painted on all faces and cut into 1 cm cubes. How many cubes have exactly two faces painted?","options":["4","16","8","12"],"answer":3,"explanation":"Edge cubes excluding corners: 4 edges of length 4 give 2 each (8), 4 edges of length 3 give 1 each (4), and the 4 edges of length 2 give 0. Total 12.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"4 cm × 3 cm × 2 cm के एक घनाभ को सभी फलकों पर रंगकर 1 cm के घनों में काटा जाता है। कितने घनों के ठीक दो फलक रंगे होंगे?","optionsHi":["4","16","8","12"],"explanationHi":"कोनों को छोड़कर किनारों वाले घन: लंबाई 4 वाले 4 किनारे प्रत्येक के 2 देते हैं (8), लंबाई 3 वाले 4 किनारे प्रत्येक का 1 देते हैं (4), और लंबाई 2 वाले 4 किनारे 0 देते हैं। कुल 12।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-31","question":"How many of these statements about clocks are correct? I. The hands coincide 11 times in 12 hours. II. The angle between the hands at 6:30 is 15°. III. The minute hand gains 55° per minute over the hour hand. IV. The hands are at right angles 44 times in a day.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II (|180 − 165| = 15°) and IV are correct. III is wrong: the minute hand moves 6° and the hour hand 0.5° per minute, so the gain is 5.5° per minute (55 minute-spaces per hour).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ियों के बारे में इनमें से कितने कथन सही हैं? I. सुइयाँ 12 घंटे में 11 बार संपाती होती हैं। II. 6:30 बजे सुइयों के बीच का कोण 15° है। III. मिनट की सुई घंटे की सुई पर प्रति मिनट 55° की बढ़त लेती है। IV. सुइयाँ एक दिन में 44 बार समकोण पर होती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II (|180 − 165| = 15°) और IV सही हैं। III गलत है: मिनट की सुई प्रति मिनट 6° और घंटे की सुई 0.5° चलती है, इसलिए बढ़त प्रति मिनट 5.5° है (प्रति घंटे 55 मिनट-खाने)।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-32","question":"If 29 February 2024 was a Thursday, what day of the week will 29 February 2028 be?","options":["Wednesday","Thursday","Tuesday","Monday"],"answer":2,"explanation":"The four years in between have 3 × 365 + 366 = 1461 days = 208 weeks + 5 days, so Thursday + 5 = Tuesday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि 29 फरवरी 2024 को गुरुवार था, तो 29 फरवरी 2028 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["बुधवार","गुरुवार","मंगलवार","सोमवार"],"explanationHi":"बीच के चार वर्षों में 3 × 365 + 366 = 1461 दिन = 208 सप्ताह + 5 दिन हैं, इसलिए गुरुवार + 5 = मंगलवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-33","question":"Which of the following years has the same calendar as 2012?","options":["2040","2018","2036","2023"],"answer":0,"explanation":"2012 is a leap year starting on Sunday. The next leap year starting on Sunday is 2040 (2016 Fri, 2020 Wed, 2024 Mon, 2028 Sat, 2032 Thu, 2036 Tue). 2023 also starts on Sunday but is not a leap year.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"निम्नलिखित में से किस वर्ष का कैलेंडर 2012 के कैलेंडर के समान है?","optionsHi":["2040","2018","2036","2023"],"explanationHi":"2012 रविवार से शुरू होने वाला लीप वर्ष है। रविवार से शुरू होने वाला अगला लीप वर्ष 2040 है (2016 शुक्र, 2020 बुध, 2024 सोम, 2028 शनि, 2032 गुरु, 2036 मंगल)। 2023 भी रविवार से शुरू होता है, लेकिन लीप वर्ष नहीं है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-34","question":"A clock is 10 minutes fast at 8 a.m. on Monday and loses 3 minutes every 4 hours uniformly. When will it show the correct time?","options":["9:40 p.m. Monday","9:00 p.m. Monday","9:20 p.m. Monday","8:20 p.m. Monday"],"answer":2,"explanation":"It must lose 10 minutes at 3 minutes per 4 hours: 10 × 4/3 = 40/3 hours = 13 h 20 min after 8 a.m., i.e. 9:20 p.m. Monday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी सोमवार सुबह 8 बजे 10 मिनट तेज है और प्रत्येक 4 घंटे में एकसमान रूप से 3 मिनट धीमी हो जाती है। यह सही समय कब दिखाएगी?","optionsHi":["सोमवार रात 9:40","सोमवार रात 9:00","सोमवार रात 9:20","सोमवार रात 8:20"],"explanationHi":"इसे 10 मिनट खोने होंगे, 4 घंटे में 3 मिनट की दर से: 10 × 4/3 = 40/3 घंटे = सुबह 8 बजे के 13 घंटे 20 मिनट बाद, यानी सोमवार रात 9:20 बजे।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-35","question":"Through what angle does the hour hand of a clock turn between 8:20 a.m. and 2:50 p.m.?","options":["205°","195°","180°","165°"],"answer":1,"explanation":"The interval is 6 h 30 min = 390 minutes, and the hour hand turns 0.5° per minute: 390 × 0.5 = 195°.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सुबह 8:20 बजे से अपराह्न 2:50 बजे के बीच घड़ी की घंटे की सुई कितने कोण से घूमती है?","optionsHi":["205°","195°","180°","165°"],"explanationHi":"अंतराल 6 घंटे 30 मिनट = 390 मिनट है, और घंटे की सुई प्रति मिनट 0.5° घूमती है: 390 × 0.5 = 195°।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-36","question":"A cube painted on all faces is cut into identical small cubes. If 96 small cubes have exactly one face painted, how many small cubes have no face painted?","options":["64","216","27","125"],"answer":0,"explanation":"6(n − 2)² = 96 gives (n − 2)² = 16, so n = 6. Unpainted cubes = (n − 2)³ = 4³ = 64.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए एक घन को एक जैसे छोटे घनों में काटा जाता है। यदि 96 छोटे घनों के ठीक एक फलक रंगे हैं, तो कितने छोटे घनों का कोई भी फलक रंगा नहीं है?","optionsHi":["64","216","27","125"],"explanationHi":"6(n − 2)² = 96 से (n − 2)² = 16, इसलिए n = 6। बिना रंग वाले घन = (n − 2)³ = 4³ = 64।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-37","question":"How many of these statements are correct? I. 2100 will be a leap year. II. A leap year has 1 odd day. III. 400 consecutive years have 0 odd days. IV. The last day of a century cannot be a Tuesday, Thursday or Saturday.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"III and IV are correct (a century ends with 5, 3, 1 or 0 cumulative odd days: Friday, Wednesday, Monday or Sunday). I is wrong because 2100 is not divisible by 400, and II is wrong because a leap year has 2 odd days.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. 2100 लीप वर्ष होगा। II. लीप वर्ष में 1 विषम दिन होता है। III. लगातार 400 वर्षों में 0 विषम दिन होते हैं। IV. किसी शताब्दी का अंतिम दिन मंगलवार, गुरुवार या शनिवार नहीं हो सकता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"III और IV सही हैं (शताब्दी के अंत में संचयी विषम दिन 5, 3, 1 या 0 होते हैं: शुक्रवार, बुधवार, सोमवार या रविवार)। I गलत है क्योंकि 2100, 400 से विभाज्य नहीं है, और II गलत है क्योंकि लीप वर्ष में 2 विषम दिन होते हैं।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-38","question":"At what time between 7 and 8 o’clock are the hands of a clock in a straight line but not together?","options":["21 9/11 minutes past 7","38 2/11 minutes past 7","54 6/11 minutes past 7","5 5/11 minutes past 7"],"answer":3,"explanation":"Opposite means |210 − 5.5M| = 180, giving 5.5M = 30 and M = 60/11 = 5 5/11. 38 2/11 minutes (210/5.5) is when they coincide, which is excluded.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"7 और 8 बजे के बीच किस समय घड़ी की सुइयाँ एक सरल रेखा में हैं, लेकिन एक साथ नहीं हैं?","optionsHi":["21 9/11 मिनट (7 बजे के बाद)","38 2/11 मिनट (7 बजे के बाद)","54 6/11 मिनट (7 बजे के बाद)","5 5/11 मिनट (7 बजे के बाद)"],"explanationHi":"विपरीत होने का अर्थ है |210 − 5.5M| = 180, जिससे 5.5M = 30 और M = 60/11 = 5 5/11। 38 2/11 मिनट (210/5.5) वह समय है जब वे संपाती होती हैं, जो अपवर्जित है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-39","question":"At how many minutes past 3 will the minute hand be 10° ahead of the hour hand?","options":["18 2/11","20","16 4/11","14 6/11"],"answer":0,"explanation":"5.5M − 90 = 10 gives M = 100/5.5 = 200/11 = 18 2/11. At 14 6/11 minutes (5.5M = 80) the minute hand is 10° behind, not ahead.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"3 बजे के कितने मिनट बाद मिनट की सुई घंटे की सुई से 10° आगे होगी?","optionsHi":["18 2/11","20","16 4/11","14 6/11"],"explanationHi":"5.5M − 90 = 10 से M = 100/5.5 = 200/11 = 18 2/11। 14 6/11 मिनट पर (5.5M = 80) मिनट की सुई 10° पीछे होती है, आगे नहीं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-40","question":"A cube painted black on all faces is cut into 125 identical small cubes. How many small cubes have paint on at most one face?","options":["98","27","54","81"],"answer":3,"explanation":"Here n = 5. No paint: 3³ = 27; exactly one face: 6 × 3² = 54. At most one face = 27 + 54 = 81.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर काले रंग से रंगे हुए एक घन को 125 एक जैसे छोटे घनों में काटा जाता है। कितने छोटे घनों के अधिकतम एक फलक पर रंग है?","optionsHi":["98","27","54","81"],"explanationHi":"यहाँ n = 5। कोई रंग नहीं: 3³ = 27; ठीक एक फलक: 6 × 3² = 54। अधिकतम एक फलक = 27 + 54 = 81।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-41","question":"What is the angle between the hands of a clock at 2:30?","options":["105°","90°","120°","95°"],"answer":0,"explanation":"Angle = |30H − 5.5M| = |60 − 165| = 105°. The hour hand is halfway between 2 and 3 while the minute hand points at 6.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 2:30 बजे सुइयों के बीच कितना कोण होता है?","optionsHi":["105°","90°","120°","95°"],"explanationHi":"कोण = |30H − 5.5M| = |60 − 165| = 105°। घंटे की सुई 2 और 3 के ठीक बीच में होती है, जबकि मिनट की सुई 6 पर होती है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-42","question":"If today is Monday, what day of the week will it be 45 days from today?","options":["Wednesday","Friday","Thursday","Tuesday"],"answer":2,"explanation":"45 = 6 × 7 + 3, so there are 3 odd days and Monday + 3 = Thursday. Wednesday counts today as day 1, an off-by-one slip.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि आज सोमवार है, तो आज से 45 दिन बाद सप्ताह का कौन-सा दिन होगा?","optionsHi":["बुधवार","शुक्रवार","गुरुवार","मंगलवार"],"explanationHi":"45 = 6 × 7 + 3, इसलिए 3 विषम दिन होते हैं और सोमवार + 3 = गुरुवार। बुधवार वाला उत्तर आज को पहला दिन गिनता है, जो एक की चूक है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-43","question":"Which of these years is a leap year?","options":["1900","2100","2200","2000"],"answer":3,"explanation":"A century year is a leap year only if it is divisible by 400. Of these, only 2000 qualifies.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कौन-सा वर्ष लीप वर्ष है?","optionsHi":["1900","2100","2200","2000"],"explanationHi":"शताब्दी वर्ष तभी लीप वर्ष होता है जब वह 400 से विभाज्य हो। इनमें से केवल 2000 इस शर्त को पूरा करता है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-44","question":"A cube painted on all faces is cut into 27 identical smaller cubes. How many small cubes have no face painted?","options":["1","0","8","6"],"answer":0,"explanation":"For n = 3, the unpainted cubes form an inner cube of side n − 2 = 1, so 1³ = 1.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए एक घन को 27 एक जैसे छोटे घनों में काटा जाता है। कितने छोटे घनों का कोई भी फलक रंगा नहीं है?","optionsHi":["1","0","8","6"],"explanationHi":"n = 3 के लिए, बिना रंग वाले घन भुजा n − 2 = 1 का एक भीतरी घन बनाते हैं, इसलिए 1³ = 1।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-45","question":"Through how many degrees does the minute hand of a clock turn in 20 minutes?","options":["60°","120°","100°","150°"],"answer":1,"explanation":"The minute hand turns 360° in 60 minutes, i.e. 6° a minute, so 20 × 6 = 120°. 60° uses 3° a minute, and 100° or 150° use 5° or 7.5° a minute.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"20 मिनट में घड़ी की मिनट की सुई कितने अंश घूमती है?","optionsHi":["60°","120°","100°","150°"],"explanationHi":"मिनट की सुई 60 मिनट में 360° घूमती है, यानी प्रति मिनट 6°, इसलिए 20 × 6 = 120°। 60° में प्रति मिनट 3° लिया गया है, और 100° या 150° में प्रति मिनट 5° या 7.5° लिया गया है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-46","question":"What is the smaller angle between the hands of a clock at 8:20?","options":["120°","140°","130°","110°"],"answer":2,"explanation":"|30 × 8 − 5.5 × 20| = |240 − 110| = 130°, which is less than 180°, so it is the smaller angle.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 8:20 बजे सुइयों के बीच छोटा कोण कितना होता है?","optionsHi":["120°","140°","130°","110°"],"explanationHi":"|30 × 8 − 5.5 × 20| = |240 − 110| = 130°, जो 180° से कम है, इसलिए यही छोटा कोण है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-47","question":"If 1 January 2024 was a Monday, what day of the week was 1 January 2025?","options":["Tuesday","Wednesday","Thursday","Monday"],"answer":1,"explanation":"2024 is a leap year with 366 days = 52 weeks + 2 days, so the day moves forward by 2: Monday + 2 = Wednesday.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि 1 जनवरी 2024 को सोमवार था, तो 1 जनवरी 2025 को सप्ताह का कौन-सा दिन था?","optionsHi":["मंगलवार","बुधवार","गुरुवार","सोमवार"],"explanationHi":"2024 लीप वर्ष है जिसमें 366 दिन = 52 सप्ताह + 2 दिन होते हैं, इसलिए दिन 2 आगे खिसकता है: सोमवार + 2 = बुधवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-48","question":"Through how many degrees does the minute hand of a clock turn between 8 a.m. and 2:30 p.m. on the same day?","options":["2160°","2340°","195°","2520°"],"answer":1,"explanation":"8 a.m. to 2:30 p.m. is 6.5 hours; the minute hand makes one full turn (360°) each hour: 6.5 × 360 = 2340°. 195° is what the hour hand turns.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उसी दिन सुबह 8 बजे से अपराह्न 2:30 बजे के बीच घड़ी की मिनट की सुई कितने अंश घूमती है?","optionsHi":["2160°","2340°","195°","2520°"],"explanationHi":"सुबह 8 बजे से अपराह्न 2:30 बजे तक 6.5 घंटे होते हैं; मिनट की सुई प्रत्येक घंटे में एक पूरा चक्कर (360°) लगाती है: 6.5 × 360 = 2340°। 195° वह है जो घंटे की सुई घूमती है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-49","question":"If the 3rd of a month is a Friday, what day of the week is the 22nd of that month?","options":["Tuesday","Thursday","Monday","Wednesday"],"answer":3,"explanation":"22 − 3 = 19 days = 2 weeks + 5 days. Friday + 5 = Wednesday.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि किसी माह की 3 तारीख को शुक्रवार है, तो उसी माह की 22 तारीख को सप्ताह का कौन-सा दिन होगा?","optionsHi":["मंगलवार","गुरुवार","सोमवार","बुधवार"],"explanationHi":"22 − 3 = 19 दिन = 2 सप्ताह + 5 दिन। शुक्रवार + 5 = बुधवार।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-50","question":"How many odd days are there in 300 years?","options":["1","3","5","0"],"answer":0,"explanation":"100 years have 5 odd days, so 300 years have 15 = 2 × 7 + 1, i.e. 1 odd day.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"300 वर्षों में कितने विषम दिन होते हैं?","optionsHi":["1","3","5","0"],"explanationHi":"100 वर्षों में 5 विषम दिन होते हैं, इसलिए 300 वर्षों में 15 = 2 × 7 + 1, यानी 1 विषम दिन होता है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-51","question":"A 4 × 4 × 4 cube painted on all faces is cut into 64 unit cubes. How many unit cubes have no face painted?","options":["16","4","8","27"],"answer":2,"explanation":"The unpainted cubes form an inner cube of side 4 − 2 = 2: 2³ = 8.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए 4 × 4 × 4 के घन को 64 इकाई घनों में काटा जाता है। कितने इकाई घनों का कोई भी फलक रंगा नहीं है?","optionsHi":["16","4","8","27"],"explanationHi":"बिना रंग वाले घन भुजा 4 − 2 = 2 का एक भीतरी घन बनाते हैं: 2³ = 8।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-52","question":"Two positions of the same die show these numbers (top, front, right): (5, 1, 3) and (5, 4, 6). Which number is opposite 5?","options":["1","2","4","6"],"answer":1,"explanation":"5 is on top in both views, so the face opposite it is the bottom face, which is hidden in both views. Besides 5 the views show 1, 3, 4 and 6, so 2 is the only number hidden in both views and must be opposite 5.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक ही पासे की दो स्थितियाँ ये संख्याएँ (ऊपर, सामने, दाएँ) दिखाती हैं: (5, 1, 3) और (5, 4, 6)। 5 के सम्मुख कौन-सी संख्या है?","optionsHi":["1","2","4","6"],"explanationHi":"दोनों दृश्यों में 5 ऊपर है, इसलिए इसका सम्मुख फलक नीचे वाला फलक है, जो दोनों दृश्यों में छिपा रहता है। 5 के अलावा दृश्यों में 1, 3, 4 और 6 दिखते हैं, इसलिए 2 ही वह एकमात्र संख्या है जो दोनों दृश्यों में छिपी है, अतः वही 5 के सम्मुख है।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-53","question":"What is the smaller angle between the hands of a clock at 12:48?","options":["84°","96°","104°","264°"],"answer":1,"explanation":"With H = 12 taken as 0: |0 − 5.5 × 48| = 264°. The smaller angle is 360 − 264 = 96°.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 12:48 बजे सुइयों के बीच छोटा कोण कितना होता है?","optionsHi":["84°","96°","104°","264°"],"explanationHi":"H = 12 को 0 मानने पर: |0 − 5.5 × 48| = 264°। छोटा कोण 360 − 264 = 96° है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-54","question":"Which month of 2023 had the same calendar as January 2023?","options":["October","April","July","December"],"answer":0,"explanation":"Odd days from January to September 2023: 3 + 0 + 3 + 2 + 3 + 2 + 3 + 3 + 2 = 21, a multiple of 7. So October began on the same day as January, and both have 31 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2023 के किस माह का कैलेंडर जनवरी 2023 के समान था?","optionsHi":["अक्टूबर","अप्रैल","जुलाई","दिसंबर"],"explanationHi":"जनवरी से सितंबर 2023 तक के विषम दिन: 3 + 0 + 3 + 2 + 3 + 2 + 3 + 3 + 2 = 21, जो 7 का गुणज है। इसलिए अक्टूबर उसी दिन से शुरू हुआ जिससे जनवरी, और दोनों में 31 दिन हैं।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-55","question":"At what time between 4 and 5 o'clock are the hands of a clock at right angles for the second time?","options":["38 2/11 minutes past 4","5 5/11 minutes past 4","32 8/11 minutes past 4","40 minutes past 4"],"answer":0,"explanation":"At 4:00 the minute hand is 120° behind. The second right angle is when it is 90° ahead: 5.5M = 120 + 90 = 210, so M = 210/5.5 = 38 2/11. (The first is at 5.5M = 30, M = 5 5/11.)","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"4 और 5 बजे के बीच किस समय घड़ी की सुइयाँ दूसरी बार समकोण पर होती हैं?","optionsHi":["38 2/11 मिनट (4 बजे के बाद)","5 5/11 मिनट (4 बजे के बाद)","32 8/11 मिनट (4 बजे के बाद)","40 मिनट (4 बजे के बाद)"],"explanationHi":"4:00 बजे मिनट की सुई 120° पीछे होती है। दूसरा समकोण तब होता है जब वह 90° आगे हो: 5.5M = 120 + 90 = 210, इसलिए M = 210/5.5 = 38 2/11। (पहला समकोण 5.5M = 30, M = 5 5/11 पर होता है।)","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-56","question":"What is the reflex angle between the hands of a clock at 11:20?","options":["140°","200°","220°","250°"],"answer":2,"explanation":"|30 × 11 − 5.5 × 20| = |330 − 110| = 220°. The smaller angle is 140°, so the reflex angle is 220°.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"घड़ी में 11:20 बजे सुइयों के बीच प्रतिवर्ती कोण कितना होता है?","optionsHi":["140°","200°","220°","250°"],"explanationHi":"|30 × 11 − 5.5 × 20| = |330 − 110| = 220°। छोटा कोण 140° है, इसलिए प्रतिवर्ती कोण 220° है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-57","question":"If 1 January 2006 was a Sunday, what day of the week was 1 January 2010?","options":["Thursday","Saturday","Friday","Monday"],"answer":2,"explanation":"Odd days for 2006, 2007, 2008 (leap) and 2009: 1 + 1 + 2 + 1 = 5. Sunday + 5 = Friday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि 1 जनवरी 2006 को रविवार था, तो 1 जनवरी 2010 को सप्ताह का कौन-सा दिन था?","optionsHi":["गुरुवार","शनिवार","शुक्रवार","सोमवार"],"explanationHi":"2006, 2007, 2008 (लीप वर्ष) और 2009 के विषम दिन: 1 + 1 + 2 + 1 = 5। रविवार + 5 = शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-58","question":"In a leap year, how many days of the week occur 53 times?","options":["One","Three","None","Two"],"answer":3,"explanation":"366 days = 52 weeks + 2 days, so the first two days of the week on which the year starts occur 53 times.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किसी लीप वर्ष में सप्ताह के कितने दिन 53 बार आते हैं?","optionsHi":["एक","तीन","कोई नहीं","दो"],"explanationHi":"366 दिन = 52 सप्ताह + 2 दिन, इसलिए जिस दिन से वर्ष शुरू होता है, सप्ताह के वे पहले दो दिन 53 बार आते हैं।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-59","question":"If 8 July 2020 was a Wednesday, what day of the week was 8 July 2015?","options":["Wednesday","Monday","Thursday","Saturday"],"answer":0,"explanation":"From 8 July 2015 to 8 July 2020 the periods cover February 2016 and February 2020, so odd days = 2 + 1 + 1 + 1 + 2 = 7 ≡ 0. The day is the same: Wednesday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि 8 जुलाई 2020 को बुधवार था, तो 8 जुलाई 2015 को सप्ताह का कौन-सा दिन था?","optionsHi":["बुधवार","सोमवार","गुरुवार","शनिवार"],"explanationHi":"8 जुलाई 2015 से 8 जुलाई 2020 तक की अवधियों में फरवरी 2016 और फरवरी 2020 आती हैं, इसलिए विषम दिन = 2 + 1 + 1 + 1 + 2 = 7 ≡ 0। दिन वही रहता है: बुधवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-60","question":"A cuboid of 5 cm × 4 cm × 3 cm is painted on all faces and cut into 1 cm cubes. How many cubes have no face painted?","options":["12","6","24","8"],"answer":1,"explanation":"The unpainted core measures (5 − 2) × (4 − 2) × (3 − 2) = 3 × 2 × 1 = 6 cubes.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"5 cm × 4 cm × 3 cm के एक घनाभ को सभी फलकों पर रंगकर 1 cm के घनों में काटा जाता है। कितने घनों का कोई भी फलक रंगा नहीं है?","optionsHi":["12","6","24","8"],"explanationHi":"बिना रंग वाला भीतरी भाग (5 − 2) × (4 − 2) × (3 − 2) = 3 × 2 × 1 = 6 घनों का है।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-61","question":"A cube is painted red on two opposite faces only and is then cut into 27 identical smaller cubes. How many small cubes have no paint at all?","options":["1","8","9","18"],"answer":2,"explanation":"Each painted face colours one layer of 9 cubes; with two opposite faces, the two outer layers (18 cubes) are painted and the middle layer of 9 is unpainted.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घन के केवल दो सम्मुख फलकों को लाल रंगा जाता है और फिर उसे 27 एक जैसे छोटे घनों में काटा जाता है। कितने छोटे घनों पर बिल्कुल भी रंग नहीं है?","optionsHi":["1","8","9","18"],"explanationHi":"प्रत्येक रंगा हुआ फलक 9 घनों की एक परत को रंगता है; दो सम्मुख फलकों के साथ दोनों बाहरी परतें (18 घन) रंगी होती हैं और बीच की 9 घनों की परत बिना रंग की रहती है।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-62","question":"A die whose opposite faces always add up to 7 rests on a table with 2 on top. What is the sum of the numbers on its four side faces?","options":["12","14","16","19"],"answer":1,"explanation":"All six faces add up to 21. Top 2 and bottom 5 together make 7, so the four sides add up to 21 − 7 = 14.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक पासा, जिसके सम्मुख फलकों का योग हमेशा 7 होता है, मेज पर इस प्रकार रखा है कि ऊपर 2 है। उसके चारों पार्श्व फलकों की संख्याओं का योग क्या है?","optionsHi":["12","14","16","19"],"explanationHi":"सभी छह फलकों का योग 21 है। ऊपर 2 और नीचे 5 मिलकर 7 बनाते हैं, इसलिए चारों पार्श्व फलकों का योग 21 − 7 = 14 है।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-63","question":"Today is Wednesday. What day of the week will it be after 2¹⁰ days?","options":["Friday","Thursday","Saturday","Monday"],"answer":0,"explanation":"2¹⁰ = 1024 = 146 × 7 + 2, so 2 odd days: Wednesday + 2 = Friday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"आज बुधवार है। 2¹⁰ दिन बाद सप्ताह का कौन-सा दिन होगा?","optionsHi":["शुक्रवार","गुरुवार","शनिवार","सोमवार"],"explanationHi":"2¹⁰ = 1024 = 146 × 7 + 2, इसलिए 2 विषम दिन: बुधवार + 2 = शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-64","question":"Kiran remembers that her mother's birthday is after the 14th but before the 18th of March. Her brother remembers it is after the 16th but before the 20th of March. On which date is the birthday, if both are right?","options":["16 March","18 March","17 March","15 March"],"answer":2,"explanation":"Kiran's range is 15–17 March and her brother's is 17–19 March. The only common date is 17 March.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किरण को याद है कि उसकी माँ का जन्मदिन मार्च की 14 तारीख के बाद लेकिन 18 तारीख से पहले है। उसके भाई को याद है कि यह मार्च की 16 तारीख के बाद लेकिन 20 तारीख से पहले है। यदि दोनों सही हैं, तो जन्मदिन किस तारीख को है?","optionsHi":["16 मार्च","18 मार्च","17 मार्च","15 मार्च"],"explanationHi":"किरण की सीमा 15–17 मार्च है और उसके भाई की 17–19 मार्च। एकमात्र उभयनिष्ठ तारीख 17 मार्च है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-65","question":"How many days are there from 15 January 2024 to 15 April 2024, counting both dates?","options":["91","90","89","92"],"answer":3,"explanation":"Counting both dates: January 15–31 is 17 days, February 2024 (leap) 29, March 31 and April 1–15 is 15, total 92. 91 counts only one end, 90 uses a 28-day February, and 89 makes both mistakes.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"15 जनवरी 2024 से 15 अप्रैल 2024 तक, दोनों तिथियों को गिनते हुए, कितने दिन होते हैं?","optionsHi":["91","90","89","92"],"explanationHi":"दोनों तिथियों को गिनने पर: 15–31 जनवरी के 17 दिन, फरवरी 2024 (लीप वर्ष) के 29, मार्च के 31 और 1–15 अप्रैल के 15, कुल 92। 91 में केवल एक सिरा गिना गया है, 90 में 28 दिन की फरवरी ली गई है, और 89 में दोनों गलतियाँ की गई हैं।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-66","question":"The minute hand gains 360° over the hour hand once every:","options":["60 minutes","65 5/11 minutes","65 minutes","64 4/11 minutes"],"answer":1,"explanation":"The minute hand gains 5.5° per minute on the hour hand, so a full 360° takes 360/5.5 = 720/11 = 65 5/11 minutes. This is the interval between successive coincidences.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"मिनट की सुई घंटे की सुई पर 360° की बढ़त कितने समय में एक बार लेती है?","optionsHi":["60 मिनट","65 5/11 मिनट","65 मिनट","64 4/11 मिनट"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है, इसलिए पूरे 360° में 360/5.5 = 720/11 = 65 5/11 मिनट लगते हैं। यह क्रमागत संपातों के बीच का अंतराल है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-67","question":"A 5 × 5 × 5 cube painted on all faces is cut into 125 unit cubes. How many unit cubes have at least two faces painted?","options":["36","44","54","8"],"answer":1,"explanation":"Exactly three faces: the 8 corners. Exactly two faces: 12 edges × (5 − 2) = 36. At least two = 36 + 8 = 44.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सभी फलकों पर रंगे हुए 5 × 5 × 5 के घन को 125 इकाई घनों में काटा जाता है। कितने इकाई घनों के कम से कम दो फलक रंगे होंगे?","optionsHi":["36","44","54","8"],"explanationHi":"ठीक तीन फलक: 8 कोने। ठीक दो फलक: 12 किनारे × (5 − 2) = 36। कम से कम दो = 36 + 8 = 44।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-68","question":"In a faulty clock, the hands coincide every 64 minutes of true time. How much does the clock gain or lose in 24 hours?","options":["Gains 32 8/11 minutes","Loses 32 8/11 minutes","Gains 16 4/11 minutes","Loses 10 10/11 minutes"],"answer":0,"explanation":"In a correct clock the hands coincide every 65 5/11 minutes. Here they coincide after only 64 true minutes, so the clock runs fast: in 64 minutes it gains 65 5/11 − 64 = 16/11 minutes. In 1440 minutes it gains (1440/64) × 16/11 = 360/11 = 32 8/11 minutes.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक दोषपूर्ण घड़ी में सुइयाँ सही समय के प्रत्येक 64 मिनट पर संपाती होती हैं। 24 घंटे में यह घड़ी कितना तेज या धीमा चलती है?","optionsHi":["32 8/11 मिनट तेज","32 8/11 मिनट धीमी","16 4/11 मिनट तेज","10 10/11 मिनट धीमी"],"explanationHi":"सही घड़ी में सुइयाँ प्रत्येक 65 5/11 मिनट पर संपाती होती हैं। यहाँ वे केवल 64 सही मिनट बाद संपाती हैं, इसलिए घड़ी तेज चलती है: 64 मिनट में यह 65 5/11 − 64 = 16/11 मिनट तेज हो जाती है। 1440 मिनट में यह (1440/64) × 16/11 = 360/11 = 32 8/11 मिनट तेज हो जाती है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-69","question":"The last day of a century can NOT be a:","options":["Sunday","Friday","Monday","Thursday"],"answer":3,"explanation":"100 years have 5 odd days (Friday), 200 years 10 ≡ 3 (Wednesday), 300 years 15 ≡ 1 (Monday), and 400 years 5 × 4 + 1 = 21 ≡ 0 (Sunday), since the 400th year is a leap year. So the last day of a century can only be Friday, Wednesday, Monday or Sunday, never Tuesday, Thursday or Saturday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किसी शताब्दी का अंतिम दिन निम्नलिखित में से कौन-सा नहीं हो सकता?","optionsHi":["रविवार","शुक्रवार","सोमवार","गुरुवार"],"explanationHi":"100 वर्षों में 5 विषम दिन (शुक्रवार), 200 वर्षों में 10 ≡ 3 (बुधवार), 300 वर्षों में 15 ≡ 1 (सोमवार), और 400 वर्षों में 5 × 4 + 1 = 21 ≡ 0 (रविवार) होते हैं, क्योंकि 400वाँ वर्ष लीप वर्ष है। इसलिए शताब्दी का अंतिम दिन केवल शुक्रवार, बुधवार, सोमवार या रविवार हो सकता है, कभी मंगलवार, गुरुवार या शनिवार नहीं।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-70","question":"The calendar of the year 2019 will be repeated in which year?","options":["2025","2030","2029","2047"],"answer":1,"explanation":"A year 3 years after a leap year repeats after 11 years. Check odd days for 2019–2029: eight ordinary years (1 each) and three leap years 2020, 2024, 2028 (2 each) = 8 + 6 = 14 ≡ 0, and 2030 is not a leap year, so 2030.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"वर्ष 2019 का कैलेंडर किस वर्ष दोहराया जाएगा?","optionsHi":["2025","2030","2029","2047"],"explanationHi":"लीप वर्ष के 3 वर्ष बाद का वर्ष 11 वर्ष बाद दोहराया जाता है। 2019–2029 के विषम दिन जाँचें: आठ सामान्य वर्ष (प्रत्येक के 1) और तीन लीप वर्ष 2020, 2024, 2028 (प्रत्येक के 2) = 8 + 6 = 14 ≡ 0, और 2030 लीप वर्ष नहीं है, इसलिए 2030।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-71","question":"How many minutes after 6 o'clock will the hands of a clock first make an angle of 110°?","options":["10 10/11","12 8/11","20","14 6/11"],"answer":1,"explanation":"At 6:00 the hands are 180° apart. The minute hand closes the gap at 5.5° per minute: 180 − 5.5M = 110, so M = 70/5.5 = 12 8/11 minutes.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"6 बजे के कितने मिनट बाद घड़ी की सुइयाँ पहली बार 110° का कोण बनाएँगी?","optionsHi":["10 10/11","12 8/11","20","14 6/11"],"explanationHi":"6:00 बजे सुइयाँ 180° की दूरी पर होती हैं। मिनट की सुई प्रति मिनट 5.5° की दर से यह अंतर घटाती है: 180 − 5.5M = 110, इसलिए M = 70/5.5 = 12 8/11 मिनट।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-72","question":"In a month of 30 days, the third Sunday falls on the 17th. On what day of the week does the 1st of the next month fall?","options":["Monday","Saturday","Sunday","Friday"],"answer":2,"explanation":"The Sundays of the month are the 3rd, 10th, 17th and 24th, so the 30th is a Saturday. The next day, the 1st of the next month, is a Sunday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"30 दिन के एक माह में तीसरा रविवार 17 तारीख को पड़ता है। अगले माह की 1 तारीख को सप्ताह का कौन-सा दिन होगा?","optionsHi":["सोमवार","शनिवार","रविवार","शुक्रवार"],"explanationHi":"माह के रविवार 3, 10, 17 और 24 तारीख को हैं, इसलिए 30 तारीख को शनिवार है। अगला दिन, यानी अगले माह की 1 तारीख, रविवार है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-73","question":"If 1 March of a leap year is a Tuesday, what day of the week was 1 January of that year?","options":["Saturday","Thursday","Sunday","Friday"],"answer":3,"explanation":"From 1 January to 1 March of a leap year: 31 + 29 = 60 days = 8 weeks + 4 days. Going back 4 days from Tuesday gives Friday. (In an ordinary year it would be 3 days back, Saturday, which is the trap.)","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि किसी लीप वर्ष की 1 मार्च को मंगलवार है, तो उस वर्ष की 1 जनवरी को सप्ताह का कौन-सा दिन था?","optionsHi":["शनिवार","गुरुवार","रविवार","शुक्रवार"],"explanationHi":"लीप वर्ष में 1 जनवरी से 1 मार्च तक: 31 + 29 = 60 दिन = 8 सप्ताह + 4 दिन। मंगलवार से 4 दिन पीछे जाने पर शुक्रवार मिलता है। (सामान्य वर्ष में यह 3 दिन पीछे, यानी शनिवार होता, जो जाल है।)","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-74","question":"A clock is set right at 5 a.m. It loses 16 minutes every 24 hours, uniformly. What is the true time when the clock shows 10 p.m. on the 4th day?","options":["10 p.m. on the 4th day","11 p.m. on the 4th day","11:16 p.m. on the 4th day","9 p.m. on the 4th day"],"answer":1,"explanation":"From 5 a.m. on day 1 to 10 p.m. on day 4 the clock shows 89 hours. The clock shows 23 h 44 min (1424 min) for every 24 true hours (1440 min). True time = 89 × 1440/1424 = 90 hours after 5 a.m. on day 1, which is 11 p.m. on day 4.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी को सुबह 5 बजे सही मिलाया जाता है। यह एकसमान रूप से प्रत्येक 24 घंटे में 16 मिनट धीमी हो जाती है। जब घड़ी 4वें दिन रात 10 बजे दिखाए, तो सही समय क्या होगा?","optionsHi":["रात 10 बजे, 4वें दिन","रात 11 बजे, 4वें दिन","रात 11:16 बजे, 4वें दिन","रात 9 बजे, 4वें दिन"],"explanationHi":"दिन 1 की सुबह 5 बजे से दिन 4 की रात 10 बजे तक घड़ी 89 घंटे दिखाती है। घड़ी प्रत्येक 24 सही घंटों (1440 मिनट) के लिए 23 घंटे 44 मिनट (1424 मिनट) दिखाती है। सही समय = 89 × 1440/1424 = दिन 1 की सुबह 5 बजे के 90 घंटे बाद, जो दिन 4 की रात 11 बजे है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-75","question":"A cuboid of 6 cm × 4 cm × 2 cm is painted on all faces and cut into 1 cm cubes. How many cubes have exactly one face painted?","options":["24","8","16","0"],"answer":2,"explanation":"With a thickness of only 2 cm, every cube touches a 6 × 4 face, so no cube is unpainted. One-face cubes lie only in the interior of the two 6 × 4 faces: (6 − 2) × (4 − 2) = 8 each, so 16. The 6 × 2 and 4 × 2 faces have no interior cubes.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"6 cm × 4 cm × 2 cm के एक घनाभ को सभी फलकों पर रंगकर 1 cm के घनों में काटा जाता है। कितने घनों का ठीक एक फलक रंगा होगा?","optionsHi":["24","8","16","0"],"explanationHi":"केवल 2 cm की मोटाई होने के कारण प्रत्येक घन किसी 6 × 4 फलक को छूता है, इसलिए कोई घन बिना रंग का नहीं है। एक फलक वाले घन केवल दोनों 6 × 4 फलकों के भीतरी भाग में होते हैं: प्रत्येक में (6 − 2) × (4 − 2) = 8, इसलिए 16। 6 × 2 और 4 × 2 वाले फलकों में कोई भीतरी घन नहीं होता।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-76","question":"A watch that gains time uniformly is 2 minutes slow at noon on a Monday and 4 minutes 48 seconds fast at 2 p.m. on the following Monday. When did it show the correct time?","options":["2 p.m. on Wednesday","Noon on Wednesday","2 p.m. on Tuesday","10 a.m. on Thursday"],"answer":0,"explanation":"From noon Monday to 2 p.m. the next Monday is 170 hours, in which the watch gains 2 + 4.8 = 6.8 minutes. It is correct once it has gained 2 minutes: 170 × 2/6.8 = 50 hours after Monday noon, i.e. 2 p.m. on Wednesday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"समय में एकसमान रूप से बढ़त लेने वाली एक घड़ी सोमवार को मध्याह्न में 2 मिनट धीमी है और अगले सोमवार को अपराह्न 2 बजे 4 मिनट 48 सेकंड तेज है। इसने सही समय कब दिखाया?","optionsHi":["बुधवार अपराह्न 2 बजे","बुधवार को मध्याह्न","मंगलवार अपराह्न 2 बजे","गुरुवार प्रातः 10 बजे"],"explanationHi":"सोमवार मध्याह्न से अगले सोमवार अपराह्न 2 बजे तक 170 घंटे होते हैं, जिनमें घड़ी 2 + 4.8 = 6.8 मिनट की बढ़त लेती है। यह तब सही होती है जब वह 2 मिनट की बढ़त ले ले: 170 × 2/6.8 = सोमवार मध्याह्न के 50 घंटे बाद, यानी बुधवार अपराह्न 2 बजे।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-77","question":"How many months in any 400 consecutive years have a 29th day?","options":["4800","4497","4400","4703"],"answer":1,"explanation":"400 years have 4800 months. Every month except February always has a 29th day (4400 months); February has one only in leap years, and 400 consecutive years contain 97 leap years. Total = 4400 + 97 = 4497.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किन्हीं भी लगातार 400 वर्षों में कितने माहों में 29वाँ दिन होता है?","optionsHi":["4800","4497","4400","4703"],"explanationHi":"400 वर्षों में 4800 माह होते हैं। फरवरी को छोड़कर हर माह में 29वाँ दिन हमेशा होता है (4400 माह); फरवरी में यह केवल लीप वर्षों में होता है, और लगातार 400 वर्षों में 97 लीप वर्ष होते हैं। कुल = 4400 + 97 = 4497।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-78","question":"What day of the week will 1 January 2100 be?","options":["Saturday","Thursday","Friday","Sunday"],"answer":2,"explanation":"1 January 2000 was a Saturday. From 1 Jan 2000 to 1 Jan 2100 there are 100 years with 25 leap years (2000, 2004, …, 2096; 2100 itself is not counted), so 100 + 25 = 125 odd days ≡ 6. Saturday + 6 = Friday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1 जनवरी 2100 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["शनिवार","गुरुवार","शुक्रवार","रविवार"],"explanationHi":"1 जनवरी 2000 को शनिवार था। 1 जनवरी 2000 से 1 जनवरी 2100 तक 100 वर्ष हैं जिनमें 25 लीप वर्ष हैं (2000, 2004, …, 2096; 2100 को स्वयं गिना नहीं जाता), इसलिए 100 + 25 = 125 विषम दिन ≡ 6। शनिवार + 6 = शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-79","question":"At what time between 5:30 and 6:00 are the hands of a clock at right angles?","options":["43 7/11 minutes past 5","10 10/11 minutes past 5","45 minutes past 5","43 3/11 minutes past 5"],"answer":0,"explanation":"Minute hand at 6M, hour hand at 150 + 0.5M. With the minute hand 90° ahead: 5.5M = 240, M = 43 7/11. The other right angle, 5.5M = 60 (M = 10 10/11), falls before 5:30.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"5:30 और 6:00 के बीच किस समय घड़ी की सुइयाँ समकोण पर होती हैं?","optionsHi":["43 7/11 मिनट (5 बजे के बाद)","10 10/11 मिनट (5 बजे के बाद)","45 मिनट (5 बजे के बाद)","43 3/11 मिनट (5 बजे के बाद)"],"explanationHi":"मिनट की सुई 6M पर और घंटे की सुई 150 + 0.5M पर होती है। मिनट की सुई 90° आगे होने पर: 5.5M = 240, M = 43 7/11। दूसरा समकोण, 5.5M = 60 (M = 10 10/11), 5:30 से पहले पड़ता है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-80","question":"Ravi was born on 29 February 2000, a Tuesday. On what day of the week did his next birthday on 29 February fall?","options":["Thursday","Saturday","Monday","Sunday"],"answer":3,"explanation":"The next 29 February is in 2004. From 29 Feb 2000 to 29 Feb 2004 = 365 × 4 + 1 = 1461 days (one extra leap day, in 2004) = 208 weeks + 5 days. Tuesday + 5 = Sunday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"रवि का जन्म 29 फरवरी 2000 को हुआ था, जो मंगलवार था। 29 फरवरी को उसका अगला जन्मदिन सप्ताह के किस दिन पड़ा?","optionsHi":["गुरुवार","शनिवार","सोमवार","रविवार"],"explanationHi":"अगली 29 फरवरी 2004 में है। 29 फरवरी 2000 से 29 फरवरी 2004 तक = 365 × 4 + 1 = 1461 दिन (2004 में एक अतिरिक्त लीप दिन) = 208 सप्ताह + 5 दिन। मंगलवार + 5 = रविवार।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-81","question":"How many of these statements are correct? I. A century year is a leap year only if it is divisible by 400. II. In February of a leap year, exactly two days of the week occur five times. III. Two consecutive years can never have the same calendar. IV. In a leap year, 1 January and 1 October fall on the same day of the week.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are true: the century rule needs divisibility by 400, and one year shifts the calendar by 1 or 2 days. II is false: 29 days = 4 weeks + 1 day, so only one day occurs five times. IV is false: January–September of a leap year has 274 days = 39 weeks + 1 day.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. शताब्दी वर्ष तभी लीप वर्ष होता है जब वह 400 से विभाज्य हो। II. लीप वर्ष की फरवरी में सप्ताह के ठीक दो दिन पाँच बार आते हैं। III. लगातार दो वर्षों का कैलेंडर कभी एक जैसा नहीं हो सकता। IV. लीप वर्ष में 1 जनवरी और 1 अक्टूबर सप्ताह के एक ही दिन पड़ते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं: शताब्दी नियम में 400 से विभाज्यता चाहिए, और एक वर्ष कैलेंडर को 1 या 2 दिन खिसकाता है। II गलत है: 29 दिन = 4 सप्ताह + 1 दिन, इसलिए केवल एक दिन पाँच बार आता है। IV गलत है: लीप वर्ष में जनवरी–सितंबर के 274 दिन = 39 सप्ताह + 1 दिन होते हैं।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-82","question":"What is the minimum number of straight cuts needed to divide a cube into 64 identical smaller cubes, and if the big cube was painted on all faces, how many small cubes have no paint?","options":["9 cuts; 8 cubes","12 cuts; 8 cubes","9 cuts; 27 cubes","6 cuts; 16 cubes"],"answer":0,"explanation":"Three cuts parallel to each pair of faces split each edge into 4: 3 + 3 + 3 = 9 cuts give 4 × 4 × 4 = 64 cubes. The unpainted core is (4 − 2)³ = 8.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घन को 64 एक जैसे छोटे घनों में बाँटने के लिए न्यूनतम कितने सीधे कट चाहिए, और यदि बड़े घन के सभी फलक रंगे थे, तो कितने छोटे घनों पर कोई रंग नहीं है?","optionsHi":["9 कट; 8 घन","12 कट; 8 घन","9 कट; 27 घन","6 कट; 16 घन"],"explanationHi":"फलकों के प्रत्येक जोड़े के समानांतर तीन कट प्रत्येक किनारे को 4 भागों में बाँट देते हैं: 3 + 3 + 3 = 9 कट से 4 × 4 × 4 = 64 घन मिलते हैं। बिना रंग वाला भीतरी भाग (4 − 2)³ = 8 है।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-83","question":"A cube has two adjacent faces painted red and the other four faces painted green. It is cut into 64 identical smaller cubes. How many small cubes have both red and green paint?","options":["16","18","20","14"],"answer":1,"explanation":"Each red face has 16 cubes. Of these, only the 6 cubes in the three rows nearest the red–red edge and away from the top and bottom faces escape green paint, so 10 per red face also carry green. The 4 cubes on the shared red–red edge belong to both faces, and 2 of them (top and bottom ends) carry green, so they are counted twice: 10 + 10 − 2 = 18.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घन के दो आसन्न फलक लाल और अन्य चार फलक हरे रंगे गए हैं। इसे 64 एक जैसे छोटे घनों में काटा जाता है। कितने छोटे घनों पर लाल और हरा दोनों रंग हैं?","optionsHi":["16","18","20","14"],"explanationHi":"प्रत्येक लाल फलक पर 16 घन होते हैं। इनमें से केवल 6 घन, जो लाल–लाल किनारे के निकट की तीन पंक्तियों में हैं और ऊपर तथा नीचे के फलकों से दूर हैं, हरे रंग से बचते हैं, इसलिए प्रत्येक लाल फलक पर 10 घनों पर हरा रंग भी है। साझा लाल–लाल किनारे के 4 घन दोनों फलकों से संबंधित हैं, और उनमें से 2 (ऊपर और नीचे के सिरे) पर हरा रंग है, इसलिए वे दो बार गिने गए: 10 + 10 − 2 = 18।","subtopic":"cubes-dice"},
  {"id":"reason-clock-calendar-84","question":"What is the smaller angle between the hands of a clock at 25 minutes 30 seconds past 7?","options":["70 1/4°","72 3/4°","68 1/2°","69 3/4°"],"answer":3,"explanation":"M = 25.5. Hour hand = 210 + 0.5 × 25.5 = 222.75°; minute hand = 6 × 25.5 = 153°. Difference = 69.75° = 69 3/4°.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"7 बजकर 25 मिनट 30 सेकंड पर घड़ी की सुइयों के बीच छोटा कोण कितना होता है?","optionsHi":["70 1/4°","72 3/4°","68 1/2°","69 3/4°"],"explanationHi":"M = 25.5। घंटे की सुई = 210 + 0.5 × 25.5 = 222.75°; मिनट की सुई = 6 × 25.5 = 153°। अंतर = 69.75° = 69 3/4°।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-85","question":"A clock strikes once at 1 o'clock, twice at 2 o'clock and so on up to 12 times at 12 o'clock, and also strikes once at every half hour. How many times does it strike in a full day of 24 hours?","options":["156","180","168","192"],"answer":1,"explanation":"In 12 hours: hour strikes 1 + 2 + … + 12 = 78, plus 12 half-hour strikes = 90. In 24 hours: 2 × 90 = 180.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी 1 बजे एक बार, 2 बजे दो बार और इसी प्रकार 12 बजे 12 बार बजती है, और हर आधे घंटे पर भी एक बार बजती है। 24 घंटे के पूरे दिन में यह कितनी बार बजती है?","optionsHi":["156","180","168","192"],"explanationHi":"12 घंटे में: घंटे के प्रहार 1 + 2 + … + 12 = 78, साथ में आधे घंटे के 12 प्रहार = 90। 24 घंटे में: 2 × 90 = 180।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-86","question":"Mahatma Gandhi was born on 2 October 1869. On which day of the week did that date fall?","options":["Saturday","Monday","Sunday","Friday"],"answer":0,"explanation":"Count odd days up to 1868: 1600 years give 0, 200 years give 3, and the remaining 68 years (17 leap) give 68 + 17 = 85 → 1. From 1 January to 2 October 1869 there are 275 days → 2. Total = 3 + 1 + 2 = 6 → 6 odd day(s), so it was a Saturday (0 = Sunday).","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"महात्मा गांधी का जन्म 2 अक्टूबर 1869 को हुआ था। वह तारीख सप्ताह के किस दिन पड़ी थी?","optionsHi":["शनिवार","सोमवार","रविवार","शुक्रवार"],"explanationHi":"1868 तक के विषम दिन गिनें: 1600 वर्ष से 0, 200 वर्ष से 3, और शेष 68 वर्ष (17 लीप) से 68 + 17 = 85 → 1। 1 जनवरी से 2 अक्टूबर 1869 तक 275 दिन हैं → 2। कुल = 3 + 1 + 2 = 6 → 6 विषम दिन, इसलिए वह शनिवार था (0 = रविवार)।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-87","question":"The Constitution of India was adopted on 26 November 1949. On which day of the week did that date fall?","options":["Sunday","Saturday","Friday","Monday"],"answer":1,"explanation":"Count odd days up to 1948: 1600 years give 0, 300 years give 1, and the remaining 48 years (12 leap) give 48 + 12 = 60 → 4. From 1 January to 26 November 1949 there are 330 days → 1. Total = 1 + 4 + 1 = 6 → 6 odd day(s), so it was a Saturday (0 = Sunday).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारत का संविधान 26 नवंबर 1949 को अंगीकृत किया गया था। वह तारीख सप्ताह के किस दिन पड़ी थी?","optionsHi":["रविवार","शनिवार","शुक्रवार","सोमवार"],"explanationHi":"1948 तक के विषम दिन गिनें: 1600 वर्ष से 0, 300 वर्ष से 1, और शेष 48 वर्ष (12 लीप) से 48 + 12 = 60 → 4। 1 जनवरी से 26 नवंबर 1949 तक 330 दिन हैं → 1। कुल = 1 + 4 + 1 = 6 → 6 विषम दिन, इसलिए वह शनिवार था (0 = रविवार)।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-88","question":"Swami Vivekananda was born on 12 January 1863. On which day of the week did that date fall?","options":["Wednesday","Sunday","Monday","Tuesday"],"answer":2,"explanation":"Count odd days up to 1862: 1600 years give 0, 200 years give 3, and the remaining 62 years (15 leap) give 62 + 15 = 77 → 0. From 1 January to 12 January 1863 there are 12 days → 5. Total = 3 + 0 + 5 = 8 → 1 odd day(s), so it was a Monday (0 = Sunday).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"स्वामी विवेकानंद का जन्म 12 जनवरी 1863 को हुआ था। वह तारीख सप्ताह के किस दिन पड़ी थी?","optionsHi":["बुधवार","रविवार","सोमवार","मंगलवार"],"explanationHi":"1862 तक के विषम दिन गिनें: 1600 वर्ष से 0, 200 वर्ष से 3, और शेष 62 वर्ष (15 लीप) से 62 + 15 = 77 → 0। 1 जनवरी से 12 जनवरी 1863 तक 12 दिन हैं → 5। कुल = 3 + 0 + 5 = 8 → 1 विषम दिन, इसलिए वह सोमवार था (0 = रविवार)।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-89","question":"India conducted nuclear tests at Pokhran on 11 May 1998. On which day of the week did that date fall?","options":["Sunday","Tuesday","Wednesday","Monday"],"answer":3,"explanation":"Count odd days up to 1997: 1600 years give 0, 300 years give 1, and the remaining 97 years (24 leap) give 97 + 24 = 121 → 2. From 1 January to 11 May 1998 there are 131 days → 5. Total = 1 + 2 + 5 = 8 → 1 odd day(s), so it was a Monday (0 = Sunday).","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारत ने 11 मई 1998 को पोखरण में परमाणु परीक्षण किए। वह तारीख सप्ताह के किस दिन पड़ी थी?","optionsHi":["रविवार","मंगलवार","बुधवार","सोमवार"],"explanationHi":"1997 तक के विषम दिन गिनें: 1600 वर्ष से 0, 300 वर्ष से 1, और शेष 97 वर्ष (24 लीप) से 97 + 24 = 121 → 2। 1 जनवरी से 11 मई 1998 तक 131 दिन हैं → 5। कुल = 1 + 2 + 5 = 8 → 1 विषम दिन, इसलिए वह सोमवार था (0 = रविवार)।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-90","question":"The Battle of Plassey was fought on 23 June 1757. On which day of the week did that date fall?","options":["Thursday","Saturday","Friday","Wednesday"],"answer":0,"explanation":"Count odd days up to 1756: 1600 years give 0, 100 years give 5, and the remaining 56 years (14 leap) give 56 + 14 = 70 → 0. From 1 January to 23 June 1757 there are 174 days → 6. Total = 5 + 0 + 6 = 11 → 4 odd day(s), so it was a Thursday (0 = Sunday).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"प्लासी का युद्ध 23 जून 1757 को लड़ा गया था। वह तारीख सप्ताह के किस दिन पड़ी थी?","optionsHi":["गुरुवार","शनिवार","शुक्रवार","बुधवार"],"explanationHi":"1756 तक के विषम दिन गिनें: 1600 वर्ष से 0, 100 वर्ष से 5, और शेष 56 वर्ष (14 लीप) से 56 + 14 = 70 → 0। 1 जनवरी से 23 जून 1757 तक 174 दिन हैं → 6। कुल = 5 + 0 + 6 = 11 → 4 विषम दिन, इसलिए वह गुरुवार था (0 = रविवार)।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-91","question":"Given that 28 February 2023 falls on a Tuesday, on which day of the week does 28 February 2025 fall?","options":["Sunday","Friday","Thursday","Saturday"],"answer":1,"explanation":"From 28 February 2023 to 28 February 2025 there are 731 days. 731 = 104 weeks + 3 day(s), so move 3 day(s) forward from Tuesday: Friday.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यह दिया गया है कि 28 फरवरी 2023 को मंगलवार है। 28 फरवरी 2025 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["रविवार","शुक्रवार","गुरुवार","शनिवार"],"explanationHi":"28 फरवरी 2023 से 28 फरवरी 2025 तक 731 दिन हैं। 731 = 104 सप्ताह + 3 दिन, इसलिए मंगलवार से 3 दिन आगे बढ़ें: शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-92","question":"Given that 1 March 2023 falls on a Wednesday, on which day of the week does 1 March 2024 fall?","options":["Saturday","Thursday","Friday","Sunday"],"answer":2,"explanation":"From 1 March 2023 to 1 March 2024 there are 366 days. 366 = 52 weeks + 2 day(s), so move 2 day(s) forward from Wednesday: Friday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यह दिया गया है कि 1 मार्च 2023 को बुधवार है। 1 मार्च 2024 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["शनिवार","गुरुवार","शुक्रवार","रविवार"],"explanationHi":"1 मार्च 2023 से 1 मार्च 2024 तक 366 दिन हैं। 366 = 52 सप्ताह + 2 दिन, इसलिए बुधवार से 2 दिन आगे बढ़ें: शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-93","question":"Given that 25 December 2019 falls on a Wednesday, on which day of the week does 25 December 2023 fall?","options":["Wednesday","Tuesday","Sunday","Monday"],"answer":3,"explanation":"From 25 December 2019 to 25 December 2023 there are 1461 days. 1461 = 208 weeks + 5 day(s), so move 5 day(s) forward from Wednesday: Monday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यह दिया गया है कि 25 दिसंबर 2019 को बुधवार है। 25 दिसंबर 2023 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["बुधवार","मंगलवार","रविवार","सोमवार"],"explanationHi":"25 दिसंबर 2019 से 25 दिसंबर 2023 तक 1461 दिन हैं। 1461 = 208 सप्ताह + 5 दिन, इसलिए बुधवार से 5 दिन आगे बढ़ें: सोमवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-94","question":"Given that 18 June 2027 falls on a Friday, on which day of the week does 18 June 2021 fall?","options":["Friday","Sunday","Thursday","Saturday"],"answer":0,"explanation":"Counting back from 18 June 2027 to 18 June 2021 there are 2191 days. 2191 = 313 weeks + 0 day(s), so move 0 day(s) back from Friday: Friday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यह दिया गया है कि 18 जून 2027 को शुक्रवार है। 18 जून 2021 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["शुक्रवार","रविवार","गुरुवार","शनिवार"],"explanationHi":"18 जून 2027 से पीछे 18 जून 2021 तक 2191 दिन हैं। 2191 = 313 सप्ताह + 0 दिन, इसलिए शुक्रवार से 0 दिन पीछे जाएँ: शुक्रवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-95","question":"Given that 4 July 2096 falls on a Wednesday, on which day of the week does 4 July 2104 fall?","options":["Saturday","Friday","Thursday","Sunday"],"answer":1,"explanation":"From 4 July 2096 to 4 July 2104 there are 2921 days. 2921 = 417 weeks + 2 day(s), so move 2 day(s) forward from Wednesday: Friday. Note that 2100 is a century year not divisible by 400, so it is NOT a leap year.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यह दिया गया है कि 4 जुलाई 2096 को बुधवार है। 4 जुलाई 2104 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["शनिवार","शुक्रवार","गुरुवार","रविवार"],"explanationHi":"4 जुलाई 2096 से 4 जुलाई 2104 तक 2921 दिन हैं। 2921 = 417 सप्ताह + 2 दिन, इसलिए बुधवार से 2 दिन आगे बढ़ें: शुक्रवार। ध्यान दें कि 2100 शताब्दी वर्ष है जो 400 से विभाज्य नहीं है, इसलिए वह लीप वर्ष नहीं है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-96","question":"Given that 12 October 2030 falls on a Saturday, on which day of the week does 26 January 2031 fall?","options":["Monday","Saturday","Sunday","Tuesday"],"answer":2,"explanation":"From 12 October 2030 to 26 January 2031 there are 106 days. 106 = 15 weeks + 1 day(s), so move 1 day(s) forward from Saturday: Sunday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यह दिया गया है कि 12 अक्टूबर 2030 को शनिवार है। 26 जनवरी 2031 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["सोमवार","शनिवार","रविवार","मंगलवार"],"explanationHi":"12 अक्टूबर 2030 से 26 जनवरी 2031 तक 106 दिन हैं। 106 = 15 सप्ताह + 1 दिन, इसलिए शनिवार से 1 दिन आगे बढ़ें: रविवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-97","question":"The calendar of the year 2026 will next be repeated in which year?","options":["2032","2037","2054","2031"],"answer":1,"explanation":"The next year must start on the same weekday and have the same number of days (2026 is not a leap year). Adding odd days from 2026 (1 for an ordinary year, 2 for a leap year), the running total first becomes a multiple of 7 at the start of 2037, and 2037 is not a leap year.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"वर्ष 2026 का कैलेंडर अगली बार किस वर्ष दोहराया जाएगा?","optionsHi":["2032","2037","2054","2031"],"explanationHi":"अगला वर्ष सप्ताह के उसी दिन से शुरू होना चाहिए और उसमें दिनों की संख्या भी वही होनी चाहिए (2026 लीप वर्ष नहीं है)। 2026 से विषम दिन जोड़ने पर (सामान्य वर्ष के 1, लीप वर्ष के 2), चलता हुआ योग पहली बार 2037 की शुरुआत पर 7 का गुणज बनता है, और 2037 लीप वर्ष नहीं है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-98","question":"The calendar of the year 2028 will next be repeated in which year?","options":["2039","2033","2056","2034"],"answer":2,"explanation":"2028 is a leap year, so the matching year must also be a leap year starting on the same weekday. Adding odd days year by year (2 for a leap year, 1 otherwise), the total first becomes a multiple of 7 at a leap year in 2056.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"वर्ष 2028 का कैलेंडर अगली बार किस वर्ष दोहराया जाएगा?","optionsHi":["2039","2033","2056","2034"],"explanationHi":"2028 लीप वर्ष है, इसलिए मेल खाने वाला वर्ष भी सप्ताह के उसी दिन से शुरू होने वाला लीप वर्ष होना चाहिए। वर्ष-दर-वर्ष विषम दिन जोड़ने पर (लीप वर्ष के 2, अन्यथा 1), योग पहली बार 2056 के लीप वर्ष में 7 का गुणज बनता है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-99","question":"The calendar of the year 2096 will next be repeated in which year?","options":["2108","2124","2102","2107"],"answer":0,"explanation":"2096 is a leap year, so the matching year must also be a leap year starting on the same weekday. Adding odd days year by year (2 for a leap year, 1 otherwise), the total first becomes a multiple of 7 at a leap year in 2108 (2100 is not a leap year, which breaks the usual 28-year rule).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"वर्ष 2096 का कैलेंडर अगली बार किस वर्ष दोहराया जाएगा?","optionsHi":["2108","2124","2102","2107"],"explanationHi":"2096 लीप वर्ष है, इसलिए मेल खाने वाला वर्ष भी सप्ताह के उसी दिन से शुरू होने वाला लीप वर्ष होना चाहिए। वर्ष-दर-वर्ष विषम दिन जोड़ने पर (लीप वर्ष के 2, अन्यथा 1), योग पहली बार 2108 के लीप वर्ष में 7 का गुणज बनता है (2100 लीप वर्ष नहीं है, जो सामान्य 28 वर्ष के नियम को तोड़ता है)।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-100","question":"Which month of 2024 has exactly the same calendar (same starting day and same number of days) as January 2024?","options":["October","November","April","July"],"answer":3,"explanation":"January 2024 begins on a Monday and has 31 days. Months that start on the same weekday are those separated by a multiple of 7 days (2024 is a leap year, so February has 29 days); of these only July also has 31 days. April starts on the same day but differs in length.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2024 के किस माह का कैलेंडर जनवरी 2024 के बिल्कुल समान है (शुरुआती दिन और दिनों की संख्या दोनों समान)?","optionsHi":["अक्टूबर","नवंबर","अप्रैल","जुलाई"],"explanationHi":"जनवरी 2024 सोमवार से शुरू होती है और उसमें 31 दिन हैं। एक ही दिन से शुरू होने वाले माह वे हैं जिनके बीच 7 दिनों का गुणज दूरी हो (2024 लीप वर्ष है, इसलिए फरवरी में 29 दिन हैं); इनमें से केवल जुलाई में भी 31 दिन हैं। अप्रैल उसी दिन से शुरू होता है, लेकिन उसकी लंबाई भिन्न है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-101","question":"Which month of 2026 has exactly the same calendar (same starting day and same number of days) as October 2026?","options":["May","April","July","January"],"answer":3,"explanation":"October 2026 begins on a Thursday and has 31 days. Months that start on the same weekday are those separated by a multiple of 7 days; of these only January also has 31 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2026 के किस माह का कैलेंडर अक्टूबर 2026 के बिल्कुल समान है (शुरुआती दिन और दिनों की संख्या दोनों समान)?","optionsHi":["मई","अप्रैल","जुलाई","जनवरी"],"explanationHi":"अक्टूबर 2026 गुरुवार से शुरू होता है और उसमें 31 दिन हैं। एक ही दिन से शुरू होने वाले माह वे हैं जिनके बीच 7 दिनों का गुणज दूरी हो; इनमें से केवल जनवरी में भी 31 दिन हैं।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-102","question":"Which month of 2028 has exactly the same calendar (same starting day and same number of days) as July 2028?","options":["January","May","October","April"],"answer":0,"explanation":"July 2028 begins on a Saturday and has 31 days. Months that start on the same weekday are those separated by a multiple of 7 days (2028 is a leap year, so February has 29 days); of these only January also has 31 days. April starts on the same day but differs in length.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2028 के किस माह का कैलेंडर जुलाई 2028 के बिल्कुल समान है (शुरुआती दिन और दिनों की संख्या दोनों समान)?","optionsHi":["जनवरी","मई","अक्टूबर","अप्रैल"],"explanationHi":"जुलाई 2028 शनिवार से शुरू होता है और उसमें 31 दिन हैं। एक ही दिन से शुरू होने वाले माह वे हैं जिनके बीच 7 दिनों का गुणज दूरी हो (2028 लीप वर्ष है, इसलिए फरवरी में 29 दिन हैं); इनमें से केवल जनवरी में भी 31 दिन हैं। अप्रैल उसी दिन से शुरू होता है, लेकिन उसकी लंबाई भिन्न है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-103","question":"1 January 2028 will be a Saturday. Which day(s) of the week occur 53 times in 2028?","options":["Only Saturday","Saturday and Sunday","Friday and Saturday","Sunday and Monday"],"answer":1,"explanation":"2028 is a leap year, so it has 366 days = 52 weeks + 2 day(s). The extra day(s) are the first two days of the year: Saturday and Sunday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1 जनवरी 2028 को शनिवार होगा। 2028 में सप्ताह का कौन-सा दिन (या कौन-से दिन) 53 बार आएगा (या आएँगे)?","optionsHi":["केवल शनिवार","शनिवार और रविवार","शुक्रवार और शनिवार","रविवार और सोमवार"],"explanationHi":"2028 लीप वर्ष है, इसलिए उसमें 366 दिन = 52 सप्ताह + 2 दिन हैं। अतिरिक्त दिन वर्ष के पहले दो दिन होते हैं: शनिवार और रविवार।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-104","question":"1 January 2027 will be a Friday. Which day(s) of the week occur 53 times in 2027?","options":["Saturday","Friday and Saturday","Friday","Thursday"],"answer":2,"explanation":"2027 is not a leap year, so it has 365 days = 52 weeks + 1 day(s). The extra day(s) are the first day of the year: Friday.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1 जनवरी 2027 को शुक्रवार होगा। 2027 में सप्ताह का कौन-सा दिन (या कौन-से दिन) 53 बार आएगा (या आएँगे)?","optionsHi":["शनिवार","शुक्रवार और शनिवार","शुक्रवार","गुरुवार"],"explanationHi":"2027 लीप वर्ष नहीं है, इसलिए उसमें 365 दिन = 52 सप्ताह + 1 दिन हैं। अतिरिक्त दिन वर्ष का पहला दिन होता है: शुक्रवार।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-105","question":"1 January 2100 will be a Friday. Which day(s) of the week occur 53 times in 2100?","options":["Saturday","Thursday","Friday and Saturday","Friday"],"answer":3,"explanation":"2100 is not a leap year (a century year must be divisible by 400), so it has 365 days = 52 weeks + 1 day(s). The extra day(s) are the first day of the year: Friday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1 जनवरी 2100 को शुक्रवार होगा। 2100 में सप्ताह का कौन-सा दिन (या कौन-से दिन) 53 बार आएगा (या आएँगे)?","optionsHi":["शनिवार","गुरुवार","शुक्रवार और शनिवार","शुक्रवार"],"explanationHi":"2100 लीप वर्ष नहीं है (शताब्दी वर्ष 400 से विभाज्य होना चाहिए), इसलिए उसमें 365 दिन = 52 सप्ताह + 1 दिन हैं। अतिरिक्त दिन वर्ष का पहला दिन होता है: शुक्रवार।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-106","question":"In a month of 31 days, the first Tuesday falls on the 4th. How many Saturdays are there in that month?","options":["6","5","3","4"],"answer":1,"explanation":"If the 4th is a Tuesday, the 1st is a Saturday. A 31-day month has 4 weeks + 3 days, so the days Saturday, Sunday and Monday occur five times. Saturday occurs 5 times.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"31 दिन के एक माह में पहला मंगलवार 4 तारीख को पड़ता है। उस माह में कितने शनिवार हैं?","optionsHi":["6","5","3","4"],"explanationHi":"यदि 4 तारीख को मंगलवार है, तो 1 तारीख को शनिवार है। 31 दिन के माह में 4 सप्ताह + 3 दिन होते हैं, इसलिए शनिवार, रविवार और सोमवार पाँच-पाँच बार आते हैं। शनिवार 5 बार आता है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-107","question":"A month of 30 days has exactly five Fridays and exactly five Saturdays. On which day of the week does the 18th of that month fall?","options":["Monday","Tuesday","Wednesday","Sunday"],"answer":0,"explanation":"A 30-day month is 4 weeks + 2 days, so the two days that occur five times are the first two days of the month. Hence the 1st is a Friday and the 2nd a Saturday. The 18th is 17 days after the 1st: 17 = 2 weeks + 3 days, so Friday + 3 = Monday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"30 दिन के एक माह में ठीक पाँच शुक्रवार और ठीक पाँच शनिवार हैं। उस माह की 18 तारीख को सप्ताह का कौन-सा दिन पड़ता है?","optionsHi":["सोमवार","मंगलवार","बुधवार","रविवार"],"explanationHi":"30 दिन का माह 4 सप्ताह + 2 दिन का होता है, इसलिए जो दो दिन पाँच बार आते हैं वे माह के पहले दो दिन हैं। अतः 1 तारीख को शुक्रवार और 2 तारीख को शनिवार है। 18 तारीख, 1 तारीख के 17 दिन बाद है: 17 = 2 सप्ताह + 3 दिन, इसलिए शुक्रवार + 3 = सोमवार।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-108","question":"The last Sunday of a 31-day month falls on the 26th. On which day of the week does the 1st of the next month fall?","options":["Monday","Sunday","Saturday","Friday"],"answer":2,"explanation":"The 26th is a Sunday, so the 31st is Friday (5 days later) and the 1st of the next month is Saturday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"31 दिन के एक माह का अंतिम रविवार 26 तारीख को पड़ता है। अगले माह की 1 तारीख को सप्ताह का कौन-सा दिन होगा?","optionsHi":["सोमवार","रविवार","शनिवार","शुक्रवार"],"explanationHi":"26 तारीख को रविवार है, इसलिए 31 तारीख को शुक्रवार (5 दिन बाद) है और अगले माह की 1 तारीख को शनिवार है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-109","question":"An office is closed on the second and fourth Saturdays of every month. In a month whose 1st is a Wednesday, what is the sum of the dates of these two closed Saturdays?","options":["36","38","43","50"],"answer":0,"explanation":"If the 1st is Wednesday, the Saturdays fall on 4, 11, 18, 25. The second and fourth are 11 and 25, sum = 36.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक कार्यालय प्रत्येक माह के दूसरे और चौथे शनिवार को बंद रहता है। जिस माह की 1 तारीख को बुधवार है, उसमें इन दोनों बंद शनिवारों की तारीखों का योग क्या है?","optionsHi":["36","38","43","50"],"explanationHi":"यदि 1 तारीख को बुधवार है, तो शनिवार 4, 11, 18, 25 तारीख को पड़ते हैं। दूसरा और चौथा 11 और 25 हैं, योग = 36।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-110","question":"Today is the 17th of the month and it is a Thursday. On which day of the week was the 1st of this month?","options":["Thursday","Wednesday","Monday","Tuesday"],"answer":3,"explanation":"The 1st is 16 days before the 17th. 16 = 2 weeks + 2 days, so go back 2 days from Thursday: Tuesday.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"आज माह की 17 तारीख है और गुरुवार है। इस माह की 1 तारीख को सप्ताह का कौन-सा दिन था?","optionsHi":["गुरुवार","बुधवार","सोमवार","मंगलवार"],"explanationHi":"1 तारीख, 17 तारीख से 16 दिन पहले है। 16 = 2 सप्ताह + 2 दिन, इसलिए गुरुवार से 2 दिन पीछे जाएँ: मंगलवार।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-111","question":"How many odd days are there in 500 years (counted from the start of year 1)?","options":["3","2","5","4"],"answer":2,"explanation":"100 years give 5 odd days, 200 give 3, 300 give 1 and 400 give 0. 500 = 1 × 400 + 100, so the odd days = 5 → 5.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"500 वर्षों में कितने विषम दिन होते हैं (वर्ष 1 की शुरुआत से गिनने पर)?","optionsHi":["3","2","5","4"],"explanationHi":"100 वर्षों से 5 विषम दिन, 200 से 3, 300 से 1 और 400 से 0 मिलते हैं। 500 = 1 × 400 + 100, इसलिए विषम दिन = 5 → 5।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-112","question":"How many odd days are there in 250 years (counted from the start of year 1)?","options":["4","2","3","5"],"answer":1,"explanation":"250 = 200 + 50 years. 200 years give 3 odd days. The next 50 years (201–250) contain 12 leap years, giving 50 + 12 = 62 odd days → 6. Total = 3 + 6 → 2 odd days.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"250 वर्षों में कितने विषम दिन होते हैं (वर्ष 1 की शुरुआत से गिनने पर)?","optionsHi":["4","2","3","5"],"explanationHi":"250 = 200 + 50 वर्ष। 200 वर्षों से 3 विषम दिन मिलते हैं। अगले 50 वर्षों (201–250) में 12 लीप वर्ष हैं, जिससे 50 + 12 = 62 विषम दिन → 6। कुल = 3 + 6 → 2 विषम दिन।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-113","question":"20 December 2027 will be a Monday. What day of the week will 5 March 2028 be?","options":["Tuesday","Monday","Saturday","Sunday"],"answer":3,"explanation":"Days after 20 December 2027: 11 (rest of December) + 31 (January) + 29 (February 2028, a leap year) + 5 (March) = 76. 76 = 10 weeks + 6 days, so Monday + 6 = Sunday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"20 दिसंबर 2027 को सोमवार होगा। 5 मार्च 2028 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["मंगलवार","सोमवार","शनिवार","रविवार"],"explanationHi":"20 दिसंबर 2027 के बाद के दिन: 11 (दिसंबर के शेष) + 31 (जनवरी) + 29 (फरवरी 2028, लीप वर्ष) + 5 (मार्च) = 76। 76 = 10 सप्ताह + 6 दिन, इसलिए सोमवार + 6 = रविवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-114","question":"If 31 December 2099 is a Thursday, what day of the week will 1 March 2100 be?","options":["Monday","Tuesday","Wednesday","Sunday"],"answer":0,"explanation":"2100 is not a leap year (century years must be divisible by 400), so February 2100 has 28 days. Days after 31 Dec 2099: 31 + 28 + 1 = 60 = 8 weeks + 4 day(s). Thursday + 4 = Monday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि 31 दिसंबर 2099 को गुरुवार है, तो 1 मार्च 2100 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["सोमवार","मंगलवार","बुधवार","रविवार"],"explanationHi":"2100 लीप वर्ष नहीं है (शताब्दी वर्ष 400 से विभाज्य होने चाहिए), इसलिए फरवरी 2100 में 28 दिन हैं। 31 दिसंबर 2099 के बाद के दिन: 31 + 28 + 1 = 60 = 8 सप्ताह + 4 दिन। गुरुवार + 4 = सोमवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-115","question":"If three days after the day before yesterday is a Saturday, what day of the week will it be 100 days after today?","options":["Saturday","Sunday","Tuesday","Monday"],"answer":1,"explanation":"Three days after the day before yesterday is tomorrow, so tomorrow is Saturday and today is Friday. 100 = 14 weeks + 2 days, so 100 days after Friday is Sunday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"यदि परसों के तीन दिन बाद शनिवार है, तो आज से 100 दिन बाद सप्ताह का कौन-सा दिन होगा?","optionsHi":["शनिवार","रविवार","मंगलवार","सोमवार"],"explanationHi":"परसों के तीन दिन बाद कल होता है, इसलिए कल शनिवार है और आज शुक्रवार है। 100 = 14 सप्ताह + 2 दिन, इसलिए शुक्रवार के 100 दिन बाद रविवार है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-116","question":"Aditi was born on 29 February 2008, a Friday. On which day of the week did her fourth actual birthday (the fourth 29 February after her birth) fall?","options":["Saturday","Wednesday","Thursday","Friday"],"answer":2,"explanation":"Her actual birthdays fall on 29 February 2012, 2016, 2020 and 2024. Each 4-year gap has 3 × 365 + 366 = 1461 days = 5 odd days, so the weekday moves 5 forward each time: Friday → Wednesday → Monday → Saturday → Thursday. The fourth is Thursday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अदिति का जन्म 29 फरवरी 2008 को हुआ था, जो शुक्रवार था। उसका चौथा वास्तविक जन्मदिन (जन्म के बाद की चौथी 29 फरवरी) सप्ताह के किस दिन पड़ा?","optionsHi":["शनिवार","बुधवार","गुरुवार","शुक्रवार"],"explanationHi":"उसके वास्तविक जन्मदिन 29 फरवरी 2012, 2016, 2020 और 2024 को पड़ते हैं। प्रत्येक 4 वर्ष के अंतराल में 3 × 365 + 366 = 1461 दिन = 5 विषम दिन होते हैं, इसलिए दिन हर बार 5 आगे खिसकता है: शुक्रवार → बुधवार → सोमवार → शनिवार → गुरुवार। चौथा जन्मदिन गुरुवार को है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-117","question":"How many days are there from 26 January 2028 to 15 August 2028, counting both dates?","options":["173","201","202","203"],"answer":3,"explanation":"January 26–31: 6, February (2028 is a leap year): 29, March 31, April 30, May 31, June 30, July 31, August 1–15: 15. Total = 203.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"26 जनवरी 2028 से 15 अगस्त 2028 तक, दोनों तिथियों को गिनते हुए, कितने दिन होते हैं?","optionsHi":["173","201","202","203"],"explanationHi":"26–31 जनवरी: 6, फरवरी (2028 लीप वर्ष है): 29, मार्च 31, अप्रैल 30, मई 31, जून 30, जुलाई 31, 1–15 अगस्त: 15। कुल = 203।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-118","question":"Which of the following years has the same calendar as 2001?","options":["2007","2008","2005","2012"],"answer":0,"explanation":"2001 is an ordinary year. Odd days added: 2001 (1), 2002 (1), 2003 (1), 2004 (2), 2005 (1), 2006 (1) = 7, i.e. 0 mod 7, so 2007 starts on the same day as 2001 and is also an ordinary year.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"निम्नलिखित में से किस वर्ष का कैलेंडर 2001 के समान है?","optionsHi":["2007","2008","2005","2012"],"explanationHi":"2001 सामान्य वर्ष है। जोड़े गए विषम दिन: 2001 (1), 2002 (1), 2003 (1), 2004 (2), 2005 (1), 2006 (1) = 7, यानी 7 से भाग देने पर 0, इसलिए 2007 उसी दिन से शुरू होता है जिससे 2001, और वह भी सामान्य वर्ष है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-119","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 5:20?","options":["320°","40°","70°","30°"],"answer":1,"explanation":"Angle = |30H − 5.5M| = |30 × 5 − 5.5 × 20| = |150 − 110| = 40°. (The hour hand moves 0.5° per minute, so it is not exactly on the hour mark.)","difficulty":"easy","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 5:20 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["320°","40°","70°","30°"],"explanationHi":"कोण = |30H − 5.5M| = |30 × 5 − 5.5 × 20| = |150 − 110| = 40°। (घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए वह ठीक घंटे के चिह्न पर नहीं होती।)","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-120","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 1:50?","options":["245°","270°","115°","145°"],"answer":2,"explanation":"Angle = |30H − 5.5M| = |30 × 1 − 5.5 × 50| = |30 − 275| = 245°; the smaller angle is 360° − 245° = 115°. (The hour hand moves 0.5° per minute, so it is not exactly on the hour mark.)","difficulty":"easy","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 1:50 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["245°","270°","115°","145°"],"explanationHi":"कोण = |30H − 5.5M| = |30 × 1 − 5.5 × 50| = |30 − 275| = 245°; छोटा कोण 360° − 245° = 115° है। (घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए वह ठीक घंटे के चिह्न पर नहीं होती।)","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-121","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 11:35?","options":["167.5°","120°","222.5°","137.5°"],"answer":3,"explanation":"Angle = |30H − 5.5M| = |30 × 11 − 5.5 × 35| = |330 − 192.5| = 137.5°. (The hour hand moves 0.5° per minute, so it is not exactly on the hour mark.)","difficulty":"moderate","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 11:35 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["167.5°","120°","222.5°","137.5°"],"explanationHi":"कोण = |30H − 5.5M| = |30 × 11 − 5.5 × 35| = |330 − 192.5| = 137.5°। (घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए वह ठीक घंटे के चिह्न पर नहीं होती।)","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-122","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 8:44?","options":["2°","24°","358°","32°"],"answer":0,"explanation":"Angle = |30H − 5.5M| = |30 × 8 − 5.5 × 44| = |240 − 242| = 2°. (The hour hand moves 0.5° per minute, so it is not exactly on the hour mark.)","difficulty":"moderate","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 8:44 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["2°","24°","358°","32°"],"explanationHi":"कोण = |30H − 5.5M| = |30 × 8 − 5.5 × 44| = |240 − 242| = 2°। (घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए वह ठीक घंटे के चिह्न पर नहीं होती।)","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-123","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 3:57?","options":["166.5°","136.5°","252°","223.5°"],"answer":1,"explanation":"Angle = |30H − 5.5M| = |30 × 3 − 5.5 × 57| = |90 − 313.5| = 223.5°; the smaller angle is 360° − 223.5° = 136.5°. (The hour hand moves 0.5° per minute, so it is not exactly on the hour mark.)","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 3:57 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["166.5°","136.5°","252°","223.5°"],"explanationHi":"कोण = |30H − 5.5M| = |30 × 3 − 5.5 × 57| = |90 − 313.5| = 223.5°; छोटा कोण 360° − 223.5° = 136.5° है। (घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए वह ठीक घंटे के चिह्न पर नहीं होती।)","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-124","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 12:33?","options":["181.5°","198°","178.5°","208.5°"],"answer":2,"explanation":"Angle = |30H − 5.5M| = |30 × 0 − 5.5 × 33| = |0 − 181.5| = 181.5°; the smaller angle is 360° − 181.5° = 178.5°. (The hour hand moves 0.5° per minute, so it is not exactly on the hour mark.)","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 12:33 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["181.5°","198°","178.5°","208.5°"],"explanationHi":"कोण = |30H − 5.5M| = |30 × 0 − 5.5 × 33| = |0 − 181.5| = 181.5°; छोटा कोण 360° − 181.5° = 178.5° है। (घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए वह ठीक घंटे के चिह्न पर नहीं होती।)","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-125","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 6:49?","options":["270.5°","114°","119.5°","89.5°"],"answer":3,"explanation":"Angle = |30H − 5.5M| = |30 × 6 − 5.5 × 49| = |180 − 269.5| = 89.5°. (The hour hand moves 0.5° per minute, so it is not exactly on the hour mark.)","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 6:49 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["270.5°","114°","119.5°","89.5°"],"explanationHi":"कोण = |30H − 5.5M| = |30 × 6 − 5.5 × 49| = |180 − 269.5| = 89.5°। (घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए वह ठीक घंटे के चिह्न पर नहीं होती।)","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-126","question":"At what time between 2 and 3 o'clock do the hour and minute hands coincide?","options":["10 10/11 minutes past 2","8 10/11 minutes past 2","10 minutes past 2","11 10/11 minutes past 2"],"answer":0,"explanation":"The minute hand gains 5.5° per minute on the hour hand. At 2:00 the minute hand is 60° behind. We need 5.5M − 60 = 0, i.e. M = (120) ÷ 11. So the time is 10 10/11 minutes past 2.","difficulty":"moderate","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"2 और 3 बजे के बीच किस समय घंटे और मिनट की सुइयाँ संपाती होती हैं?","optionsHi":["10 10/11 मिनट (2 बजे के बाद)","8 10/11 मिनट (2 बजे के बाद)","10 मिनट (2 बजे के बाद)","11 10/11 मिनट (2 बजे के बाद)"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है। 2:00 बजे मिनट की सुई 60° पीछे होती है। हमें 5.5M − 60 = 0 चाहिए, यानी M = (120) ÷ 11। इसलिए समय 10 10/11 मिनट (2 बजे के बाद) है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-127","question":"At what time between 7 and 8 o'clock do the hour and minute hands coincide?","options":["38 minutes past 7","38 2/11 minutes past 7","36 2/11 minutes past 7","39 2/11 minutes past 7"],"answer":1,"explanation":"The minute hand gains 5.5° per minute on the hour hand. At 7:00 the minute hand is 210° behind. We need 5.5M − 210 = 0, i.e. M = (420) ÷ 11. So the time is 38 2/11 minutes past 7.","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"7 और 8 बजे के बीच किस समय घंटे और मिनट की सुइयाँ संपाती होती हैं?","optionsHi":["38 मिनट (7 बजे के बाद)","38 2/11 मिनट (7 बजे के बाद)","36 2/11 मिनट (7 बजे के बाद)","39 2/11 मिनट (7 बजे के बाद)"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है। 7:00 बजे मिनट की सुई 210° पीछे होती है। हमें 5.5M − 210 = 0 चाहिए, यानी M = (420) ÷ 11। इसलिए समय 38 2/11 मिनट (7 बजे के बाद) है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-128","question":"At what time between 1 and 2 o'clock do the hands point in exactly opposite directions?","options":["38 minutes past 1","36 2/11 minutes past 1","38 2/11 minutes past 1","39 2/11 minutes past 1"],"answer":2,"explanation":"The minute hand gains 5.5° per minute on the hour hand. At 1:00 the minute hand is 30° behind. We need 5.5M − 30 = ±180, i.e. M = (60 ± 360) ÷ 11 (taking values between 0 and 60). So the time is 38 2/11 minutes past 1.","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"1 और 2 बजे के बीच किस समय सुइयाँ ठीक विपरीत दिशाओं में होती हैं?","optionsHi":["38 मिनट (1 बजे के बाद)","36 2/11 मिनट (1 बजे के बाद)","38 2/11 मिनट (1 बजे के बाद)","39 2/11 मिनट (1 बजे के बाद)"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है। 1:00 बजे मिनट की सुई 30° पीछे होती है। हमें 5.5M − 30 = ±180 चाहिए, यानी M = (60 ± 360) ÷ 11 (0 और 60 के बीच के मान लेने पर)। इसलिए समय 38 2/11 मिनट (1 बजे के बाद) है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-129","question":"At what time between 10 and 11 o'clock do the hands point in exactly opposite directions?","options":["22 9/11 minutes past 10","21 minutes past 10","19 9/11 minutes past 10","21 9/11 minutes past 10"],"answer":3,"explanation":"The minute hand gains 5.5° per minute on the hour hand. At 10:00 the minute hand is 300° behind. We need 5.5M − 300 = ±180, i.e. M = (600 ± 360) ÷ 11 (taking values between 0 and 60). So the time is 21 9/11 minutes past 10.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"10 और 11 बजे के बीच किस समय सुइयाँ ठीक विपरीत दिशाओं में होती हैं?","optionsHi":["22 9/11 मिनट (10 बजे के बाद)","21 मिनट (10 बजे के बाद)","19 9/11 मिनट (10 बजे के बाद)","21 9/11 मिनट (10 बजे के बाद)"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है। 10:00 बजे मिनट की सुई 300° पीछे होती है। हमें 5.5M − 300 = ±180 चाहिए, यानी M = (600 ± 360) ÷ 11 (0 और 60 के बीच के मान लेने पर)। इसलिए समय 21 9/11 मिनट (10 बजे के बाद) है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-130","question":"At what time between 6 and 7 o'clock are the hands at right angles for the first time?","options":["16 4/11 minutes past 6","49 1/11 minutes past 6","17 4/11 minutes past 6","14 4/11 minutes past 6"],"answer":0,"explanation":"The minute hand gains 5.5° per minute on the hour hand. At 6:00 the minute hand is 180° behind. We need 5.5M − 180 = ±90, i.e. M = (360 ± 180) ÷ 11 (taking values between 0 and 60). This gives 16 4/11 and 49 1/11 minutes, so the first occurrence is 16 4/11 minutes past 6.","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"6 और 7 बजे के बीच किस समय सुइयाँ पहली बार समकोण पर होती हैं?","optionsHi":["16 4/11 मिनट (6 बजे के बाद)","49 1/11 मिनट (6 बजे के बाद)","17 4/11 मिनट (6 बजे के बाद)","14 4/11 मिनट (6 बजे के बाद)"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है। 6:00 बजे मिनट की सुई 180° पीछे होती है। हमें 5.5M − 180 = ±90 चाहिए, यानी M = (360 ± 180) ÷ 11 (0 और 60 के बीच के मान लेने पर)। इससे 16 4/11 और 49 1/11 मिनट मिलते हैं, इसलिए पहली बार 16 4/11 मिनट (6 बजे के बाद) होता है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-131","question":"At what time between 7 and 8 o'clock are the hands at right angles for the second time?","options":["55 6/11 minutes past 7","54 6/11 minutes past 7","52 6/11 minutes past 7","21 9/11 minutes past 7"],"answer":1,"explanation":"The minute hand gains 5.5° per minute on the hour hand. At 7:00 the minute hand is 210° behind. We need 5.5M − 210 = ±90, i.e. M = (420 ± 180) ÷ 11 (taking values between 0 and 60). This gives 21 9/11 and 54 6/11 minutes, so the second occurrence is 54 6/11 minutes past 7.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"7 और 8 बजे के बीच किस समय सुइयाँ दूसरी बार समकोण पर होती हैं?","optionsHi":["55 6/11 मिनट (7 बजे के बाद)","54 6/11 मिनट (7 बजे के बाद)","52 6/11 मिनट (7 बजे के बाद)","21 9/11 मिनट (7 बजे के बाद)"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है। 7:00 बजे मिनट की सुई 210° पीछे होती है। हमें 5.5M − 210 = ±90 चाहिए, यानी M = (420 ± 180) ÷ 11 (0 और 60 के बीच के मान लेने पर)। इससे 21 9/11 और 54 6/11 मिनट मिलते हैं, इसलिए दूसरी बार 54 6/11 मिनट (7 बजे के बाद) होता है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-132","question":"At what time between 3 and 4 o'clock are the hands 60° apart for the first time?","options":["3 5/11 minutes past 3","27 3/11 minutes past 3","5 5/11 minutes past 3","6 5/11 minutes past 3"],"answer":2,"explanation":"The minute hand gains 5.5° per minute on the hour hand. At 3:00 the minute hand is 90° behind. We need 5.5M − 90 = ±60, i.e. M = (180 ± 120) ÷ 11 (taking values between 0 and 60). This gives 5 5/11 and 27 3/11 minutes, so the first occurrence is 5 5/11 minutes past 3.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"3 और 4 बजे के बीच किस समय सुइयाँ पहली बार 60° की दूरी पर होती हैं?","optionsHi":["3 5/11 मिनट (3 बजे के बाद)","27 3/11 मिनट (3 बजे के बाद)","5 5/11 मिनट (3 बजे के बाद)","6 5/11 मिनट (3 बजे के बाद)"],"explanationHi":"मिनट की सुई घंटे की सुई पर प्रति मिनट 5.5° की बढ़त लेती है। 3:00 बजे मिनट की सुई 90° पीछे होती है। हमें 5.5M − 90 = ±60 चाहिए, यानी M = (180 ± 120) ÷ 11 (0 और 60 के बीच के मान लेने पर)। इससे 5 5/11 और 27 3/11 मिनट मिलते हैं, इसलिए पहली बार 5 5/11 मिनट (3 बजे के बाद) होता है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-133","question":"At what time between 9 and 10 o'clock are the hands 120° apart for the second time?","options":["5 5/11 minutes past 9","28 3/11 minutes past 9","25 3/11 minutes past 9","27 3/11 minutes past 9"],"answer":3,"explanation":"At 9:00 the hour hand is 270° ahead of the minute hand, and the minute hand gains 5.5° per minute. The hands are 120° apart when the gap 270 − 5.5M equals 240 (120° measured the other way round) or 120, giving M = 30/5.5 = 5 5/11 or M = 150/5.5 = 27 3/11. So the second time is 27 3/11 minutes past 9.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"9 और 10 बजे के बीच किस समय सुइयाँ दूसरी बार 120° की दूरी पर होती हैं?","optionsHi":["5 5/11 मिनट (9 बजे के बाद)","28 3/11 मिनट (9 बजे के बाद)","25 3/11 मिनट (9 बजे के बाद)","27 3/11 मिनट (9 बजे के बाद)"],"explanationHi":"9:00 बजे घंटे की सुई मिनट की सुई से 270° आगे होती है, और मिनट की सुई प्रति मिनट 5.5° की बढ़त लेती है। सुइयाँ 120° की दूरी पर तब होती हैं जब अंतर 270 − 5.5M, 240 (दूसरी ओर से मापा गया 120°) या 120 के बराबर हो, जिससे M = 30/5.5 = 5 5/11 या M = 150/5.5 = 27 3/11 मिलता है। अतः दूसरी बार यह 27 3/11 मिनट (9 बजे के बाद) होता है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-134","question":"A clock shows 8:15. What time will its mirror image (mirror placed vertically beside the clock) appear to show?","options":["3:45","3:15","2:45","4:45"],"answer":0,"explanation":"For a mirror image, subtract the time from 11:60 (i.e. 12:00). 11:60 − 8:15 = 3:45.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी में 8:15 बजे हैं। उसके दर्पण प्रतिबिंब (दर्पण घड़ी के बगल में ऊर्ध्वाधर रखा है) में कितने बजे दिखाई देंगे?","optionsHi":["3:45","3:15","2:45","4:45"],"explanationHi":"दर्पण प्रतिबिंब के लिए समय को 11:60 (यानी 12:00) में से घटाएँ। 11:60 − 8:15 = 3:45।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-135","question":"A clock shows 1:37. What time will its mirror image (mirror placed vertically beside the clock) appear to show?","options":["10:53","10:23","9:23","11:23"],"answer":1,"explanation":"For a mirror image, subtract the time from 11:60 (i.e. 12:00). 11:60 − 1:37 = 10:23.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी में 1:37 बजे हैं। उसके दर्पण प्रतिबिंब (दर्पण घड़ी के बगल में ऊर्ध्वाधर रखा है) में कितने बजे दिखाई देंगे?","optionsHi":["10:53","10:23","9:23","11:23"],"explanationHi":"दर्पण प्रतिबिंब के लिए समय को 11:60 (यानी 12:00) में से घटाएँ। 11:60 − 1:37 = 10:23।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-136","question":"A clock shows 12:18. What time will its mirror image (mirror placed vertically beside the clock) appear to show?","options":["12:42","11:12","11:42","10:42"],"answer":2,"explanation":"For a mirror image, subtract the time from 11:60 (i.e. 12:00). 11:60 − 12:18 = 11:42. (Treat 12:18 as 0:18, so the result is 11:42.)","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी में 12:18 बजे हैं। उसके दर्पण प्रतिबिंब (दर्पण घड़ी के बगल में ऊर्ध्वाधर रखा है) में कितने बजे दिखाई देंगे?","optionsHi":["12:42","11:12","11:42","10:42"],"explanationHi":"दर्पण प्रतिबिंब के लिए समय को 11:60 (यानी 12:00) में से घटाएँ। 11:60 − 12:18 = 11:42। (12:18 को 0:18 मानें, इसलिए परिणाम 11:42 है।)","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-137","question":"A clock gains 4 minutes every hour. It is set right at 7 a.m. What time will it show when the correct time is 4 p.m. the same day?","options":["4:32 p.m.","4:40 p.m.","3:24 p.m.","4:36 p.m."],"answer":3,"explanation":"From 7 a.m. to 4 p.m. is 9 hours, so the clock gains 9 × 4 = 36 minutes and shows 4:36 p.m.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी प्रति घंटे 4 मिनट तेज चलती है। इसे सुबह 7 बजे सही मिलाया जाता है। उसी दिन जब सही समय शाम 4 बजे हो, तब यह कितने बजे दिखाएगी?","optionsHi":["अपराह्न 4:32 बजे","अपराह्न 4:40 बजे","अपराह्न 3:24 बजे","अपराह्न 4:36 बजे"],"explanationHi":"सुबह 7 बजे से शाम 4 बजे तक 9 घंटे होते हैं, इसलिए घड़ी 9 × 4 = 36 मिनट तेज हो जाती है और अपराह्न 4:36 बजे दिखाती है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-138","question":"A clock gains 3 minutes every hour. It is set right at 6 a.m. What is the correct time when this clock shows 3:27 p.m. the same day?","options":["3:00 p.m.","2:33 p.m.","3:03 p.m.","3:26 p.m."],"answer":0,"explanation":"The clock shows 63 minutes for every 60 true minutes. It has run 9 h 27 min = 567 shown minutes, which is 567 × 60/63 = 540 true minutes = 9 hours. Correct time = 6 a.m. + 9 h = 3:00 p.m.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी प्रति घंटे 3 मिनट तेज चलती है। इसे सुबह 6 बजे सही मिलाया जाता है। उसी दिन जब यह घड़ी अपराह्न 3:27 बजे दिखाए, तब सही समय क्या होगा?","optionsHi":["अपराह्न 3:00 बजे","अपराह्न 2:33 बजे","अपराह्न 3:03 बजे","अपराह्न 3:26 बजे"],"explanationHi":"घड़ी प्रत्येक 60 सही मिनटों के लिए 63 मिनट दिखाती है। वह 9 घंटे 27 मिनट = 567 दिखाए गए मिनट चली है, जो 567 × 60/63 = 540 सही मिनट = 9 घंटे हैं। सही समय = सुबह 6 बजे + 9 घंटे = अपराह्न 3:00 बजे।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-139","question":"Two clocks are set right at 10 a.m. One gains 2 minutes every hour and the other loses 3 minutes every hour. At what correct time will the first clock be exactly one hour ahead of the second?","options":["6 p.m. the same day","10 p.m. the same day","10 a.m. the next day","8 p.m. the same day"],"answer":1,"explanation":"Every true hour the gap between them grows by 2 + 3 = 5 minutes. A gap of 60 minutes needs 60 ÷ 5 = 12 hours, i.e. 10 p.m. the same day.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"दो घड़ियों को सुबह 10 बजे सही मिलाया जाता है। एक प्रति घंटे 2 मिनट तेज चलती है और दूसरी प्रति घंटे 3 मिनट धीमी। किस सही समय पर पहली घड़ी दूसरी घड़ी से ठीक एक घंटा आगे होगी?","optionsHi":["उसी दिन शाम 6 बजे","उसी दिन रात 10 बजे","अगले दिन सुबह 10 बजे","उसी दिन रात 8 बजे"],"explanationHi":"प्रत्येक सही घंटे में उनके बीच का अंतर 2 + 3 = 5 मिनट बढ़ता है। 60 मिनट के अंतर के लिए 60 ÷ 5 = 12 घंटे चाहिए, यानी उसी दिन रात 10 बजे।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-140","question":"A clock that gains time uniformly is 5 minutes slow at 8 a.m. and 7 minutes fast at 8 p.m. the same day. At what time did it show the correct time?","options":["12 noon","2 p.m.","1 p.m.","1:30 p.m."],"answer":2,"explanation":"In 12 hours it gains 5 + 7 = 12 minutes, i.e. 1 minute per hour. To make up the 5 minutes it was slow takes 5 hours, so it was correct at 8 a.m. + 5 h = 1 p.m.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एकसमान रूप से समय में बढ़त लेने वाली एक घड़ी सुबह 8 बजे 5 मिनट धीमी है और उसी दिन रात 8 बजे 7 मिनट तेज है। इसने सही समय कब दिखाया?","optionsHi":["दोपहर 12 बजे","दोपहर 2 बजे","दोपहर 1 बजे","दोपहर 1:30 बजे"],"explanationHi":"12 घंटे में यह 5 + 7 = 12 मिनट की बढ़त लेती है, यानी प्रति घंटे 1 मिनट। जितने 5 मिनट यह धीमी थी उन्हें पूरा करने में 5 घंटे लगते हैं, इसलिए यह सुबह 8 बजे + 5 घंटे = दोपहर 1 बजे सही थी।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-141","question":"Through what angle does the hour hand of a clock turn from 9:40 a.m. to 4:10 p.m. on the same day?","options":["225°","180°","210°","195°"],"answer":3,"explanation":"The time elapsed is 6 hours 30 minutes = 390 minutes. The hour hand turns 0.5° per minute, so it turns 390 × 0.5 = 195°.","difficulty":"moderate","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"उसी दिन सुबह 9:40 बजे से अपराह्न 4:10 बजे तक घड़ी की घंटे की सुई कितने कोण से घूमती है?","optionsHi":["225°","180°","210°","195°"],"explanationHi":"बीता हुआ समय 6 घंटे 30 मिनट = 390 मिनट है। घंटे की सुई प्रति मिनट 0.5° घूमती है, इसलिए वह 390 × 0.5 = 195° घूमती है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-142","question":"How many times are the hands of a clock at right angles between 3 p.m. and 9 p.m. (excluding both these times)?","options":["12","10","14","11"],"answer":1,"explanation":"The hands are at right angles 22 times in 12 hours, i.e. normally twice an hour, but in the 3 o'clock and 8 o'clock hours one of the two falls exactly at 3:00 or 9:00, which are excluded. So 12 − 2 = 10. 12 counts two per hour blindly, 11 scales 22 by half, and 14 counts seven hours instead of six.","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"अपराह्न 3 बजे से रात 9 बजे के बीच (इन दोनों समयों को छोड़कर) घड़ी की सुइयाँ कितनी बार समकोण पर होती हैं?","optionsHi":["12","10","14","11"],"explanationHi":"सुइयाँ 12 घंटे में 22 बार समकोण पर होती हैं, यानी सामान्यतः प्रति घंटे दो बार, लेकिन 3 बजे और 8 बजे वाले घंटों में दो में से एक ठीक 3:00 या 9:00 पर पड़ता है, जो अपवर्जित हैं। इसलिए 12 − 2 = 10। 12 आँख मूँदकर प्रति घंटे दो बार गिनता है, 11 में 22 को आधा किया गया है, और 14 में छह के बजाय सात घंटे गिने गए हैं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-143","question":"How many times do the hour and minute hands coincide between 1 p.m. and 5 p.m. (excluding both these times)?","options":["5","6","4","3"],"answer":2,"explanation":"The hands coincide once every 65 5/11 minutes: at about 1:05, 2:11, 3:16 and 4:22, and next at 5:27, which is outside the interval. So they coincide 4 times.","difficulty":"moderate","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"अपराह्न 1 बजे से अपराह्न 5 बजे के बीच (इन दोनों समयों को छोड़कर) घंटे और मिनट की सुइयाँ कितनी बार संपाती होती हैं?","optionsHi":["5","6","4","3"],"explanationHi":"सुइयाँ प्रत्येक 65 5/11 मिनट पर एक बार संपाती होती हैं: लगभग 1:05, 2:11, 3:16 और 4:22 पर, और अगली 5:27 पर, जो अंतराल के बाहर है। इसलिए वे 4 बार संपाती होती हैं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-144","question":"By how many degrees does the minute hand of a clock gain on the hour hand in 40 minutes?","options":["220°","200°","240°","180°"],"answer":0,"explanation":"The minute hand moves 6° per minute and the hour hand 0.5° per minute, so the gain is 5.5° per minute. In 40 minutes: 40 × 5.5 = 220°.","difficulty":"easy","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"40 मिनट में घड़ी की मिनट की सुई घंटे की सुई पर कितने अंश की बढ़त लेती है?","optionsHi":["220°","200°","240°","180°"],"explanationHi":"मिनट की सुई प्रति मिनट 6° और घंटे की सुई प्रति मिनट 0.5° चलती है, इसलिए बढ़त प्रति मिनट 5.5° है। 40 मिनट में: 40 × 5.5 = 220°।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-145","question":"Between 5 and 6 o'clock, at how many minutes past 5 will the minute hand be exactly 15° AHEAD of the hour hand?","options":["57 3/11 minutes past 5","51 9/11 minutes past 5","27 minutes past 5","30 minutes past 5"],"answer":3,"explanation":"At 5:00 the minute hand is 150° behind the hour hand. To be 15° ahead it must gain 150 + 15 = 165°. At 5.5° per minute this takes 165 ÷ 5.5 = 30 minutes, so the time is 5:30. (Check: at 5:30 the hour hand is at 165° and the minute hand at 180°.)","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"5 और 6 बजे के बीच, 5 बजे के कितने मिनट बाद मिनट की सुई घंटे की सुई से ठीक 15° आगे होगी?","optionsHi":["57 3/11 मिनट (5 बजे के बाद)","51 9/11 मिनट (5 बजे के बाद)","27 मिनट (5 बजे के बाद)","30 मिनट (5 बजे के बाद)"],"explanationHi":"5:00 बजे मिनट की सुई घंटे की सुई से 150° पीछे होती है। 15° आगे होने के लिए उसे 150 + 15 = 165° की बढ़त लेनी होगी। 5.5° प्रति मिनट की दर से इसमें 165 ÷ 5.5 = 30 मिनट लगते हैं, इसलिए समय 5:30 है। (जाँच: 5:30 पर घंटे की सुई 165° पर और मिनट की सुई 180° पर होती है।)","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-146","question":"How many minutes after 12 noon will the hands of a clock first form an angle of 99°?","options":["18 minutes","18 6/11 minutes","20 minutes","16 minutes"],"answer":0,"explanation":"At 12:00 the hands are together. The minute hand gains 5.5° per minute, so a 99° gap first appears after 99 ÷ 5.5 = 18 minutes.","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"दोपहर 12 बजे के कितने मिनट बाद घड़ी की सुइयाँ पहली बार 99° का कोण बनाएँगी?","optionsHi":["18 मिनट","18 6/11 मिनट","20 मिनट","16 मिनट"],"explanationHi":"12:00 बजे सुइयाँ साथ-साथ होती हैं। मिनट की सुई प्रति मिनट 5.5° की बढ़त लेती है, इसलिए 99° का अंतर पहली बार 99 ÷ 5.5 = 18 मिनट बाद आता है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-147","question":"The mirror image of a wall clock shows 7:50. What is the smaller angle between the hour and minute hands at the actual time?","options":["295°","65°","35°","95°"],"answer":1,"explanation":"Actual time = 11:60 − 7:50 = 4:10. Angle = |30 × 4 − 5.5 × 10| = |120 − 55| = 65°. (A mirror reflection keeps the angle between the hands the same, so the angle at 7:50 is also 65°.)","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक दीवार घड़ी के दर्पण प्रतिबिंब में 7:50 बजे दिख रहे हैं। वास्तविक समय पर घंटे और मिनट की सुइयों के बीच छोटा कोण कितना है?","optionsHi":["295°","65°","35°","95°"],"explanationHi":"वास्तविक समय = 11:60 − 7:50 = 4:10। कोण = |30 × 4 − 5.5 × 10| = |120 − 55| = 65°। (दर्पण प्रतिबिंब सुइयों के बीच का कोण वही रखता है, इसलिए 7:50 पर भी कोण 65° है।)","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-148","question":"A clock takes 6 seconds to strike 4 o'clock (the strikes are evenly spaced). How long will it take to strike 10 o'clock?","options":["16 seconds","15 seconds","18 seconds","20 seconds"],"answer":2,"explanation":"4 strikes have 3 equal gaps in 6 seconds, so each gap is 2 seconds. 10 strikes have 9 gaps: 9 × 2 = 18 seconds.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी 4 बजे बजने में 6 सेकंड लेती है (प्रहार समान अंतराल पर होते हैं)। 10 बजे बजने में उसे कितना समय लगेगा?","optionsHi":["16 सेकंड","15 सेकंड","18 सेकंड","20 सेकंड"],"explanationHi":"4 प्रहारों में 6 सेकंड में 3 समान अंतराल होते हैं, इसलिए प्रत्येक अंतराल 2 सेकंड का है। 10 प्रहारों में 9 अंतराल होते हैं: 9 × 2 = 18 सेकंड।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-149","question":"It is 9 p.m. on a Monday. What day and time will it be 100 hours later?","options":["Friday, 1:00 a.m.","Sunday, 1:00 a.m.","Saturday, 1:00 p.m.","Saturday, 1:00 a.m."],"answer":3,"explanation":"100 hours = 4 days + 4 hours. 4 days after Monday 9 p.m. is Friday 9 p.m.; 4 more hours make it Saturday, 1:00 a.m.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सोमवार रात 9 बजे हैं। 100 घंटे बाद कौन-सा दिन और समय होगा?","optionsHi":["शुक्रवार, रात 1:00 बजे","रविवार, रात 1:00 बजे","शनिवार, दोपहर 1:00 बजे","शनिवार, रात 1:00 बजे"],"explanationHi":"100 घंटे = 4 दिन + 4 घंटे। सोमवार रात 9 बजे के 4 दिन बाद शुक्रवार रात 9 बजे होता है; 4 घंटे और जोड़ने पर शनिवार, रात 1:00 बजे हो जाता है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-150","question":"What is the reflex angle between the hands of a clock at 4:48?","options":["216°","144°","186°","246°"],"answer":0,"explanation":"Smaller angle = |30 × 4 − 5.5 × 48| = |120 − 264| = 144°. The reflex angle is 360° − 144° = 216°.","difficulty":"hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"घड़ी में 4:48 बजे सुइयों के बीच प्रतिवर्ती कोण कितना होता है?","optionsHi":["216°","144°","186°","246°"],"explanationHi":"छोटा कोण = |30 × 4 − 5.5 × 48| = |120 − 264| = 144°। प्रतिवर्ती कोण 360° − 144° = 216° है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-151","question":"A clock is set at 12 noon. Through how many degrees will the hour hand have turned by 5:20 p.m.?","options":["150°","160°","155°","170°"],"answer":1,"explanation":"The hour hand moves 30° per hour, i.e. 0.5° per minute. From 12:00 to 5:20 is 320 minutes: 320 × 0.5 = 160°.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक घड़ी को दोपहर 12 बजे मिलाया गया है। अपराह्न 5:20 बजे तक घंटे की सुई कितने अंश घूम चुकी होगी?","optionsHi":["150°","160°","155°","170°"],"explanationHi":"घंटे की सुई प्रति घंटे 30°, यानी प्रति मिनट 0.5° चलती है। 12:00 से 5:20 तक 320 मिनट होते हैं: 320 × 0.5 = 160°।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-152","question":"At what time between 11 and 12 o'clock are the hands of a clock exactly opposite each other?","options":["5 5/11 minutes past 11","30 minutes past 11","27 3/11 minutes past 11","32 8/11 minutes past 11"],"answer":2,"explanation":"At 11:00 the minute hand is 330° behind, i.e. 30° ahead going the other way. For the hands to be 180° apart the minute hand must close the gap from 330° to 180°, gaining 150°: 150 ÷ 5.5 = 27 3/11 minutes. Time = 27 3/11 minutes past 11.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RRB NTPC","questionHi":"11 और 12 बजे के बीच किस समय घड़ी की सुइयाँ ठीक एक-दूसरे के विपरीत होती हैं?","optionsHi":["5 5/11 मिनट (11 बजे के बाद)","30 मिनट (11 बजे के बाद)","27 3/11 मिनट (11 बजे के बाद)","32 8/11 मिनट (11 बजे के बाद)"],"explanationHi":"11:00 बजे मिनट की सुई 330° पीछे होती है, यानी दूसरी ओर से देखने पर 30° आगे। सुइयों के 180° की दूरी पर होने के लिए मिनट की सुई को अंतर 330° से घटाकर 180° करना होगा, यानी 150° की बढ़त लेनी होगी: 150 ÷ 5.5 = 27 3/11 मिनट। समय = 27 3/11 मिनट (11 बजे के बाद)।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-153","question":"What day of the week will 1 January 2050 be?","options":["Monday","Sunday","Friday","Saturday"],"answer":3,"explanation":"The first 2000 years contain 0 odd days, so 31 December 2000 was a Sunday and 1 January 2001 a Monday. From 2001 to 2049 there are 49 years with 12 leap years (2004–2048), giving 49 + 12 = 61 odd days = 5 mod 7. Monday + 5 = Saturday.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1 जनवरी 2050 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["सोमवार","रविवार","शुक्रवार","शनिवार"],"explanationHi":"पहले 2000 वर्षों में 0 विषम दिन होते हैं, इसलिए 31 दिसंबर 2000 को रविवार था और 1 जनवरी 2001 को सोमवार। 2001 से 2049 तक 49 वर्ष हैं जिनमें 12 लीप वर्ष (2004–2048) हैं, जिससे 49 + 12 = 61 विषम दिन = 7 से भाग देने पर 5। सोमवार + 5 = शनिवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-154","question":"15 March 2026 is a Sunday. What is the sum of all the dates in March 2026 that fall on a Wednesday?","options":["40","54","58","62"],"answer":2,"explanation":"15 March is Sunday, so 18 March is Wednesday, and the Wednesdays are 4, 11, 18, 25. Their sum is 58.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"15 मार्च 2026 को रविवार है। मार्च 2026 की उन सभी तारीखों का योग क्या है जो बुधवार को पड़ती हैं?","optionsHi":["40","54","58","62"],"explanationHi":"15 मार्च को रविवार है, इसलिए 18 मार्च को बुधवार है, और बुधवार 4, 11, 18, 25 तारीख को पड़ते हैं। इनका योग 58 है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-155","question":"28 February 2027 will be a Sunday. What day of the week will 1 March 2028 be?","options":["Wednesday","Thursday","Friday","Tuesday"],"answer":0,"explanation":"From 28 Feb 2027 to 28 Feb 2028 is 365 days (1 odd day): Monday. 2028 is a leap year, so 29 Feb 2028 comes next (Tuesday) and 1 March 2028 is Wednesday.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"28 फरवरी 2027 को रविवार होगा। 1 मार्च 2028 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["बुधवार","गुरुवार","शुक्रवार","मंगलवार"],"explanationHi":"28 फरवरी 2027 से 28 फरवरी 2028 तक 365 दिन (1 विषम दिन) हैं: सोमवार। 2028 लीप वर्ष है, इसलिए 29 फरवरी 2028 अगली है (मंगलवार) और 1 मार्च 2028 को बुधवार है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-156","question":"What is the smaller angle between the hour hand and the minute hand of a clock at 7:38?","options":["359°","18°","19°","1°"],"answer":3,"explanation":"θ = |30 × 7 − 5.5 × 38| = |210 − 209| = 1°. 18° comes from forgetting that the hour hand has crept 19° past the 7, and 359° is the reflex angle, not the smaller one.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"घड़ी में 7:38 बजे घंटे की सुई और मिनट की सुई के बीच छोटा कोण कितना होता है?","optionsHi":["359°","18°","19°","1°"],"explanationHi":"θ = |30 × 7 − 5.5 × 38| = |210 − 209| = 1°। 18° इस बात को भूलने से आता है कि घंटे की सुई 7 से 19° आगे खिसक चुकी है, और 359° प्रतिवर्ती कोण है, छोटा कोण नहीं।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-157","question":"At what time between 5 and 6 o'clock will the hour hand and the minute hand lie symmetrically on opposite sides of the line joining 12 and 6 (that is, make equal angles with the 12 mark, one on each side)?","options":["5:32 4/13","5:43 7/11","5:35","5:27 3/11"],"answer":0,"explanation":"Measured clockwise from 12, the two hands must add up to 360°: (150 + 0.5M) + 6M = 360, so M = 210/6.5 = 32 4/13. 5:35 ignores the hour hand's movement; 5:27 3/11 is when the hands coincide.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"5 और 6 बजे के बीच किस समय घंटे की सुई और मिनट की सुई 12 और 6 को मिलाने वाली रेखा के दोनों ओर सममित रूप से स्थित होंगी (यानी 12 के चिह्न से दोनों समान कोण बनाएँगी, एक-एक ओर)?","optionsHi":["5:32 4/13","5:43 7/11","5:35","5:27 3/11"],"explanationHi":"12 से दक्षिणावर्त मापने पर दोनों सुइयों के कोणों का योग 360° होना चाहिए: (150 + 0.5M) + 6M = 360, इसलिए M = 210/6.5 = 32 4/13। 5:35 में घंटे की सुई की गति की उपेक्षा की गई है; 5:27 3/11 वह समय है जब सुइयाँ संपाती होती हैं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-158","question":"A faulty clock runs at a steady rate, and its hands are found to coincide every 60 minutes of correct time. How much does it gain or lose in 24 hours of correct time?","options":["Loses 130 10/11 minutes","Gains 120 minutes","Loses 120 minutes","Gains 130 10/11 minutes"],"answer":3,"explanation":"A correct clock's hands meet every 720/11 = 65 5/11 clock-minutes. Here that much clock time passes in only 60 true minutes, so the clock is fast: in 1440 true minutes it shows 1440 × (720/11) ÷ 60 = 1570 10/11, a gain of 130 10/11 minutes. 120 comes from dividing by 65 5/11 instead of 60.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक दोषपूर्ण घड़ी एकसमान दर से चलती है और पाया जाता है कि उसकी सुइयाँ सही समय के प्रत्येक 60 मिनट पर संपाती होती हैं। सही समय के 24 घंटों में यह कितना तेज या धीमा चलती है?","optionsHi":["130 10/11 मिनट धीमी","120 मिनट तेज","120 मिनट धीमी","130 10/11 मिनट तेज"],"explanationHi":"सही घड़ी की सुइयाँ प्रत्येक 720/11 = 65 5/11 घड़ी-मिनट पर मिलती हैं। यहाँ उतना घड़ी-समय केवल 60 सही मिनट में बीत जाता है, इसलिए घड़ी तेज चलती है: 1440 सही मिनट में वह 1440 × (720/11) ÷ 60 = 1570 10/11 दिखाती है, यानी 130 10/11 मिनट की बढ़त। 120, 60 के बजाय 65 5/11 से भाग देने पर आता है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-159","question":"Which is the first year after 2027 that will have exactly the same calendar as 2027?","options":["2033","2055","2038","2034"],"answer":2,"explanation":"Add odd days year by year from 2027: eleven years 2027–2037 contain three leap years (2028, 2032, 2036), giving 11 + 3 = 14 ≡ 0 odd days, and 2038 is, like 2027, a non-leap year. The '+6 years' shortcut (2033) only works in particular positions of the leap cycle; 2055 also matches but is not the first.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2027 के बाद वह पहला वर्ष कौन-सा होगा जिसका कैलेंडर ठीक 2027 के समान होगा?","optionsHi":["2033","2055","2038","2034"],"explanationHi":"2027 से वर्ष-दर-वर्ष विषम दिन जोड़ें: 2027–2037 के ग्यारह वर्षों में तीन लीप वर्ष (2028, 2032, 2036) हैं, जिससे 11 + 3 = 14 ≡ 0 विषम दिन होते हैं, और 2038, 2027 की तरह, लीप वर्ष नहीं है। '+6 वर्ष' का शॉर्टकट लीप चक्र की विशेष स्थितियों में ही काम करता है (2033); 2055 भी मेल खाता है, पर पहला नहीं है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-160","question":"1 January 2032 is a Thursday. Which day or days of the week occur 53 times in the year 2032?","options":["Friday and Saturday","Thursday and Friday","Thursday only","Wednesday and Thursday"],"answer":1,"explanation":"2032 is a leap year: 366 = 52 weeks + 2 days, so the first two days of the year, Thursday and Friday, occur 53 times. 'Thursday only' treats 2032 as an ordinary year.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1 जनवरी 2032 को गुरुवार है। वर्ष 2032 में सप्ताह का कौन-सा दिन या कौन-से दिन 53 बार आते हैं?","optionsHi":["शुक्रवार और शनिवार","गुरुवार और शुक्रवार","केवल गुरुवार","बुधवार और गुरुवार"],"explanationHi":"2032 लीप वर्ष है: 366 = 52 सप्ताह + 2 दिन, इसलिए वर्ष के पहले दो दिन, गुरुवार और शुक्रवार, 53 बार आते हैं। 'केवल गुरुवार' 2032 को सामान्य वर्ष मान लेता है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-161","question":"15 August 1947 was a Friday. On which day of the week did 26 January 1950 fall?","options":["Tuesday","Friday","Wednesday","Thursday"],"answer":3,"explanation":"Days from 15 Aug 1947 to 15 Aug 1949 = 366 + 365 (29 Feb 1948 lies in between), and from 15 Aug 1949 to 26 Jan 1950 = 16 + 30 + 31 + 30 + 31 + 26 = 164. Total 895 ≡ 6 (mod 7), and Friday + 6 = Thursday. Missing the leap day gives Wednesday.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"15 अगस्त 1947 को शुक्रवार था। 26 जनवरी 1950 को सप्ताह का कौन-सा दिन था?","optionsHi":["मंगलवार","शुक्रवार","बुधवार","गुरुवार"],"explanationHi":"15 अगस्त 1947 से 15 अगस्त 1949 तक के दिन = 366 + 365 (29 फरवरी 1948 बीच में पड़ती है), और 15 अगस्त 1949 से 26 जनवरी 1950 तक = 16 + 30 + 31 + 30 + 31 + 26 = 164। कुल 895 ≡ 6 (मॉड 7), और शुक्रवार + 6 = गुरुवार। लीप दिन छूट जाने पर बुधवार आता है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-162","question":"In a certain month there are five Fridays, but only four Thursdays and only four Saturdays. How many days does the month have?","options":["30","28","29","31"],"answer":2,"explanation":"In a month of 28 + k days, exactly the first k days of the week occur five times, and they are consecutive. Friday alone occurring five times (its neighbours only four) forces k = 1, so the month has 29 days: a February of a leap year starting on Friday.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी माह में पाँच शुक्रवार हैं, लेकिन केवल चार गुरुवार और केवल चार शनिवार हैं। उस माह में कितने दिन हैं?","optionsHi":["30","28","29","31"],"explanationHi":"28 + k दिनों वाले माह में सप्ताह के ठीक पहले k दिन पाँच बार आते हैं, और वे क्रमागत होते हैं। केवल शुक्रवार का पाँच बार आना (उसके पड़ोसी दिन केवल चार बार) k = 1 को बाध्य करता है, इसलिए माह में 29 दिन हैं: शुक्रवार से शुरू होने वाले लीप वर्ष की फरवरी।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-163","question":"On which day of the week did 2 October 1869 fall?","options":["Sunday","Saturday","Friday","Thursday"],"answer":1,"explanation":"Odd days: 1600 years → 0, the next 200 years → 3, 1801–1868 (68 years, 17 of them leap) → 85 ≡ 1, so 4 by 31 Dec 1868. 1 Jan–2 Oct 1869: 3+0+3+2+3+2+3+3+2+2 = 23 ≡ 2. Total 6 → Saturday.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2 अक्टूबर 1869 को सप्ताह का कौन-सा दिन था?","optionsHi":["रविवार","शनिवार","शुक्रवार","गुरुवार"],"explanationHi":"विषम दिन: 1600 वर्ष → 0, अगले 200 वर्ष → 3, 1801–1868 (68 वर्ष, जिनमें 17 लीप) → 85 ≡ 1, इसलिए 31 दिसंबर 1868 तक 4। 1 जनवरी–2 अक्टूबर 1869: 3+0+3+2+3+2+3+3+2+2 = 23 ≡ 2। कुल 6 → शनिवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-164","question":"A clock strikes the hours (once at 1 o'clock, twice at 2 o'clock, …, twelve times at 12 o'clock) and also strikes once at every half hour. How many strokes does it make in 24 hours?","options":["156","180","168","204"],"answer":1,"explanation":"Hour strokes: 2 × (1 + 2 + … + 12) = 2 × 78 = 156. Half-hour strokes: one in each of the 24 hours = 24. Total 180. 168 counts the half hours for only 12 hours; 156 forgets them.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक घड़ी घंटे बजाती है (1 बजे एक बार, 2 बजे दो बार, …, 12 बजे बारह बार) और हर आधे घंटे पर भी एक बार बजती है। 24 घंटों में यह कितने प्रहार करती है?","optionsHi":["156","180","168","204"],"explanationHi":"घंटे के प्रहार: 2 × (1 + 2 + … + 12) = 2 × 78 = 156। आधे घंटे के प्रहार: 24 घंटों में से प्रत्येक में एक = 24। कुल 180। 168 में आधे घंटे केवल 12 घंटों के गिने गए हैं; 156 में उन्हें भुला दिया गया है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-165","question":"A clock loses 40 minutes every 24 hours at a uniform rate. It is set right at 9 a.m. on Monday. What is the correct time when the clock shows 7 a.m. on Thursday?","options":["9:00 a.m. Thursday","8:56:40 a.m. Thursday","5:03:20 a.m. Thursday","8:20 a.m. Thursday"],"answer":0,"explanation":"The clock shows 1400 minutes for every 1440 true minutes. It has shown 70 hours, so true time elapsed = 70 × 1440/1400 = 72 hours: 9 a.m. Thursday. 8:56:40 applies the loss to clock hours instead of true hours; 5:03:20 inverts the ratio.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक घड़ी एकसमान दर से प्रत्येक 24 घंटे में 40 मिनट धीमी हो जाती है। इसे सोमवार सुबह 9 बजे सही मिलाया जाता है। जब घड़ी गुरुवार सुबह 7 बजे दिखाए, तब सही समय क्या होगा?","optionsHi":["गुरुवार सुबह 9:00 बजे","गुरुवार सुबह 8:56:40 बजे","गुरुवार सुबह 5:03:20 बजे","गुरुवार सुबह 8:20 बजे"],"explanationHi":"घड़ी प्रत्येक 1440 सही मिनट के लिए 1400 मिनट दिखाती है। उसने 70 घंटे दिखाए हैं, इसलिए बीता हुआ सही समय = 70 × 1440/1400 = 72 घंटे: गुरुवार सुबह 9 बजे। 8:56:40 में हानि को सही घंटों के बजाय घड़ी के घंटों पर लगाया गया है; 5:03:20 में अनुपात उलट दिया गया है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-166","question":"How many leap years are there from 1801 to 2100, both years included?","options":["74","72","73","75"],"answer":2,"explanation":"Multiples of 4 from 1804 to 2100 number (2100 − 1804)/4 + 1 = 75. Century years are leap only if divisible by 400, so 1900 and 2100 drop out but 2000 stays: 73. 75 ignores the century rule, 74 drops only one century year, and 72 wrongly drops 2000 too.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1801 से 2100 तक, दोनों वर्ष सहित, कितने लीप वर्ष हैं?","optionsHi":["74","72","73","75"],"explanationHi":"1804 से 2100 तक 4 के गुणजों की संख्या (2100 − 1804)/4 + 1 = 75 है। शताब्दी वर्ष तभी लीप वर्ष होते हैं जब वे 400 से विभाज्य हों, इसलिए 1900 और 2100 बाहर हो जाते हैं पर 2000 रहता है: 73। 75 में शताब्दी नियम की उपेक्षा की गई है, 74 में केवल एक शताब्दी वर्ष हटाया गया है, और 72 में 2000 को भी गलती से हटा दिया गया है।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-167","question":"1 January 2029 is a Monday. Which of the following dates in 2029 is also a Monday?","options":["1 October 2029","1 July 2029","1 April 2029","1 September 2029"],"answer":0,"explanation":"In a non-leap year, January and October start on the same day (Jan–Sep = 273 days ≡ 0 odd days). 1 April and 1 July fall on Sunday, 1 September on Saturday.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1 जनवरी 2029 को सोमवार है। 2029 की निम्नलिखित तारीखों में से कौन-सी तारीख भी सोमवार को है?","optionsHi":["1 अक्टूबर 2029","1 जुलाई 2029","1 अप्रैल 2029","1 सितंबर 2029"],"explanationHi":"लीप वर्ष न होने पर जनवरी और अक्टूबर एक ही दिन से शुरू होते हैं (जनवरी–सितंबर = 273 दिन ≡ 0 विषम दिन)। 1 अप्रैल और 1 जुलाई रविवार को पड़ते हैं, 1 सितंबर शनिवार को।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-168","question":"1 January 2032 is a Thursday. On which date does the last Sunday of February 2032 fall?","options":["29 February","28 February","22 February","23 February"],"answer":0,"explanation":"January has 31 days ≡ 3 odd days, so 1 February 2032 is Sunday. 2032 is a leap year, so 29 February (28 days later) is also a Sunday. 22 February is the answer if the leap day is overlooked.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1 जनवरी 2032 को गुरुवार है। फरवरी 2032 का अंतिम रविवार किस तारीख को पड़ता है?","optionsHi":["29 फरवरी","28 फरवरी","22 फरवरी","23 फरवरी"],"explanationHi":"जनवरी में 31 दिन ≡ 3 विषम दिन होते हैं, इसलिए 1 फरवरी 2032 को रविवार है। 2032 लीप वर्ष है, इसलिए 29 फरवरी (28 दिन बाद) भी रविवार है। यदि लीप दिन की उपेक्षा की जाए तो उत्तर 22 फरवरी आता है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-169","question":"Between 8 and 9 o'clock, at what time will the hands of a clock make an angle of 12° with the minute hand lying between the 8 and the 9 marks?","options":["8:45 9/11","8:42","8:41 5/11","8:43 7/11"],"answer":2,"explanation":"|240 − 5.5M| = 12 gives M = 228/5.5 = 41 5/11 or 252/5.5 = 45 9/11. At 8:45 9/11 the minute hand has already passed the 9 (45-minute mark), so only 8:41 5/11 fits. 8:43 7/11 is when the hands coincide.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"8 और 9 बजे के बीच किस समय घड़ी की सुइयाँ 12° का कोण बनाएँगी, जबकि मिनट की सुई 8 और 9 के चिह्नों के बीच हो?","optionsHi":["8:45 9/11","8:42","8:41 5/11","8:43 7/11"],"explanationHi":"|240 − 5.5M| = 12 से M = 228/5.5 = 41 5/11 या 252/5.5 = 45 9/11 मिलता है। 8:45 9/11 पर मिनट की सुई 9 (45 मिनट के चिह्न) को पार कर चुकी होती है, इसलिए केवल 8:41 5/11 उपयुक्त है। 8:43 7/11 वह समय है जब सुइयाँ संपाती होती हैं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-170","question":"The hands of a clock coincide at 12 noon. At what time will they coincide for the 10th time after that?","options":["11:00 p.m.","10:54 6/11 p.m.","10:50 p.m.","9:49 1/11 p.m."],"answer":1,"explanation":"The hands coincide every 720/11 = 65 5/11 minutes, so the 10th meeting is 7200/11 = 654 6/11 minutes = 10 h 54 6/11 min after noon. Using a round 65 minutes gives 10:50; 9:49 1/11 is the 9th meeting.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"घड़ी की सुइयाँ दोपहर 12 बजे संपाती होती हैं। इसके बाद वे 10वीं बार किस समय संपाती होंगी?","optionsHi":["रात 11:00 बजे","रात 10:54 6/11 बजे","रात 10:50 बजे","रात 9:49 1/11 बजे"],"explanationHi":"सुइयाँ प्रत्येक 720/11 = 65 5/11 मिनट पर संपाती होती हैं, इसलिए 10वाँ मिलन दोपहर के 7200/11 = 654 6/11 मिनट = 10 घंटे 54 6/11 मिनट बाद होता है। गोल 65 मिनट लेने पर 10:50 आता है; 9:49 1/11 9वाँ मिलन है।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-171","question":"Today is Tuesday. What day of the week will it be 3^100 days from today?","options":["Friday","Sunday","Saturday","Wednesday"],"answer":2,"explanation":"Powers of 3 repeat mod 7 with period 6 (3^6 ≡ 1). 100 = 6 × 16 + 4, so 3^100 ≡ 3^4 = 81 ≡ 4. Tuesday + 4 = Saturday.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"आज मंगलवार है। आज से 3^100 दिन बाद सप्ताह का कौन-सा दिन होगा?","optionsHi":["शुक्रवार","रविवार","शनिवार","बुधवार"],"explanationHi":"3 की घातें मॉड 7 में 6 के आवर्त से दोहराती हैं (3^6 ≡ 1)। 100 = 6 × 16 + 4, इसलिए 3^100 ≡ 3^4 = 81 ≡ 4। मंगलवार + 4 = शनिवार।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-172","question":"In a month of 31 days, the first Monday falls on the 3rd. The following month has 30 days. On which day of the week does the last day of the following month fall?","options":["Thursday","Wednesday","Monday","Tuesday"],"answer":1,"explanation":"The 3rd is Monday, so the 1st is Saturday. 31 days later (3 odd days) the next month starts on Tuesday, and its 30th day is 29 days later (1 odd day): Wednesday. Tuesday is the slip of stopping at the first of the month.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"31 दिन के एक माह में पहला सोमवार 3 तारीख को पड़ता है। अगले माह में 30 दिन हैं। अगले माह का अंतिम दिन सप्ताह के किस दिन पड़ता है?","optionsHi":["गुरुवार","बुधवार","सोमवार","मंगलवार"],"explanationHi":"3 तारीख को सोमवार है, इसलिए 1 तारीख को शनिवार है। 31 दिन (3 विषम दिन) बाद अगला माह मंगलवार से शुरू होता है, और उसका 30वाँ दिन 29 दिन बाद (1 विषम दिन) है: बुधवार। मंगलवार माह की पहली तारीख पर रुक जाने की चूक है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-173","question":"A clock that gains uniformly is 10 minutes slow at 12 noon on Monday and 6 minutes fast at 12 noon on Thursday. When did it show the correct time?","options":["3 p.m. on Tuesday","9 a.m. on Wednesday","12 noon on Wednesday","12 midnight between Tuesday and Wednesday"],"answer":1,"explanation":"In 72 hours it gains 10 + 6 = 16 minutes. It is correct once it has gained the first 10 minutes: 72 × 10/16 = 45 hours after Monday noon, i.e. 9 a.m. Wednesday. Using 6/16 gives Tuesday 3 p.m.; the midpoint gives midnight.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एकसमान रूप से समय में बढ़त लेने वाली एक घड़ी सोमवार दोपहर 12 बजे 10 मिनट धीमी है और गुरुवार दोपहर 12 बजे 6 मिनट तेज है। इसने सही समय कब दिखाया?","optionsHi":["मंगलवार अपराह्न 3 बजे","बुधवार सुबह 9 बजे","बुधवार दोपहर 12 बजे","मंगलवार और बुधवार के बीच की रात 12 बजे"],"explanationHi":"72 घंटे में यह 10 + 6 = 16 मिनट की बढ़त लेती है। यह तब सही होती है जब वह पहले 10 मिनट की बढ़त ले ले: 72 × 10/16 = सोमवार दोपहर के 45 घंटे बाद, यानी बुधवार सुबह 9 बजे। 6/16 लेने पर मंगलवार अपराह्न 3 बजे आता है; मध्यबिंदु लेने पर आधी रात आती है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-174","question":"Between 9 and 10 o'clock, at what time will the minute hand be exactly 42° AHEAD of the hour hand?","options":["9:56","9:41 5/11","9:56 8/11","9:49 1/11"],"answer":2,"explanation":"Minute hand ahead means 6M − (270 + 0.5M) = 42, so 5.5M = 312 and M = 56 8/11. 9:41 5/11 is when the minute hand is 42° behind; 9:49 1/11 is when they coincide.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"9 और 10 बजे के बीच किस समय मिनट की सुई घंटे की सुई से ठीक 42° आगे होगी?","optionsHi":["9:56","9:41 5/11","9:56 8/11","9:49 1/11"],"explanationHi":"मिनट की सुई के आगे होने का अर्थ है 6M − (270 + 0.5M) = 42, इसलिए 5.5M = 312 और M = 56 8/11। 9:41 5/11 वह समय है जब मिनट की सुई 42° पीछे होती है; 9:49 1/11 वह समय है जब वे संपाती होती हैं।","subtopic":"clock-hands-positions"},
  {"id":"reason-clock-calendar-175","question":"Republic Day, 26 January 2030, is a Saturday. On which day of the week will Independence Day, 15 August 2030, fall?","options":["Wednesday","Thursday","Friday","Tuesday"],"answer":1,"explanation":"Days after 26 Jan: 5 (rest of Jan) + 28 + 31 + 30 + 31 + 30 + 31 + 15 = 201 ≡ 5 (mod 7). Saturday + 5 = Thursday. Counting 26 January itself as well gives the off-by-one Friday.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"गणतंत्र दिवस, 26 जनवरी 2030, को शनिवार है। स्वतंत्रता दिवस, 15 अगस्त 2030, सप्ताह के किस दिन पड़ेगा?","optionsHi":["बुधवार","गुरुवार","शुक्रवार","मंगलवार"],"explanationHi":"26 जनवरी के बाद के दिन: 5 (जनवरी के शेष) + 28 + 31 + 30 + 31 + 30 + 31 + 15 = 201 ≡ 5 (मॉड 7)। शनिवार + 5 = गुरुवार। 26 जनवरी को भी गिन लेने पर एक की चूक वाला शुक्रवार आता है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-176","question":"Which is the first year after 2028 that will have exactly the same calendar as 2028?","options":["2056","2034","2039","2045"],"answer":0,"explanation":"2028 is a leap year, so the matching year must also be a leap year that starts on the same day. Each leap-to-leap step of 4 years adds 5 odd days; 7 such steps (28 years) are needed to total a multiple of 7, giving 2056. 2034 and 2045 are non-leap years, which can never match a leap-year calendar.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2028 के बाद वह पहला वर्ष कौन-सा होगा जिसका कैलेंडर ठीक 2028 के समान होगा?","optionsHi":["2056","2034","2039","2045"],"explanationHi":"2028 लीप वर्ष है, इसलिए मेल खाने वाला वर्ष भी उसी दिन से शुरू होने वाला लीप वर्ष होना चाहिए। लीप से लीप तक के 4 वर्ष के प्रत्येक चरण में 5 विषम दिन जुड़ते हैं; कुल 7 का गुणज बनाने के लिए ऐसे 7 चरण (28 वर्ष) चाहिए, जिससे 2056 मिलता है। 2034 और 2045 लीप वर्ष नहीं हैं, जो लीप वर्ष के कैलेंडर से कभी मेल नहीं खा सकते।","subtopic":"calendar-repeat-leap"},
  {"id":"reason-clock-calendar-177","question":"The hour hand and the minute hand of a clock coincide at a certain moment. What is the smaller angle between them after the minute hand has turned through a further 330°?","options":["2.5°","30°","302.5°","57.5°"],"answer":3,"explanation":"While the minute hand turns 330°, the hour hand turns 330/12 = 27.5°. The minute hand is then 330 − 27.5 = 302.5° ahead, i.e. 360 − 302.5 = 57.5° on the other side. 30° ignores the hour hand; 302.5° is the reflex angle.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी क्षण घड़ी की घंटे की सुई और मिनट की सुई संपाती हैं। मिनट की सुई के 330° और घूम जाने के बाद उनके बीच छोटा कोण कितना होगा?","optionsHi":["2.5°","30°","302.5°","57.5°"],"explanationHi":"जब मिनट की सुई 330° घूमती है, तब घंटे की सुई 330/12 = 27.5° घूमती है। तब मिनट की सुई 330 − 27.5 = 302.5° आगे होती है, यानी दूसरी ओर 360 − 302.5 = 57.5°। 30° में घंटे की सुई की उपेक्षा की गई है; 302.5° प्रतिवर्ती कोण है।","subtopic":"clock-angles"},
  {"id":"reason-clock-calendar-178","question":"A vertical mirror is placed beside a wall clock. At a certain moment, the time read from the mirror image is exactly 2 hours 40 minutes ahead of the actual time. Which of the following could be the actual time?","options":["3:50","4:20","5:20","4:40"],"answer":3,"explanation":"Mirror time = 12:00 − actual time. So 12:00 − t = t + 2:40, giving 2t = 9:20 (or 21:20), t = 4:40 or 10:40. Check: 4:40 → mirror 7:20, which is 2 h 40 min ahead. 4:20, 3:50 and 5:20 give gaps of 3 h 20 min, 4 h 20 min and 1 h 20 min.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक दीवार घड़ी के बगल में एक ऊर्ध्वाधर दर्पण रखा है। किसी क्षण दर्पण प्रतिबिंब से पढ़ा गया समय वास्तविक समय से ठीक 2 घंटे 40 मिनट आगे है। निम्नलिखित में से कौन-सा वास्तविक समय हो सकता है?","optionsHi":["3:50","4:20","5:20","4:40"],"explanationHi":"दर्पण का समय = 12:00 − वास्तविक समय। इसलिए 12:00 − t = t + 2:40, जिससे 2t = 9:20 (या 21:20), t = 4:40 या 10:40। जाँच: 4:40 → दर्पण 7:20, जो 2 घंटे 40 मिनट आगे है। 4:20, 3:50 और 5:20 से अंतर 3 घंटे 20 मिनट, 4 घंटे 20 मिनट और 1 घंटे 20 मिनट आते हैं।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-179","question":"Gandhi Jayanti, 2 October 2029, falls on a Tuesday. What is the date of the third Saturday of September 2029?","options":["15 September","16 September","8 September","22 September"],"answer":0,"explanation":"2 October is Tuesday, so 29 September (3 days earlier) is Saturday. Saturdays in September 2029: 29, 22, 15, 8, 1, so the third one is the 15th. 22 September is the third Saturday counted from the end.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"गांधी जयंती, 2 अक्टूबर 2029, को मंगलवार है। सितंबर 2029 के तीसरे शनिवार की तारीख क्या है?","optionsHi":["15 सितंबर","16 सितंबर","8 सितंबर","22 सितंबर"],"explanationHi":"2 अक्टूबर को मंगलवार है, इसलिए 29 सितंबर (3 दिन पहले) को शनिवार है। सितंबर 2029 के शनिवार: 29, 22, 15, 8, 1, इसलिए तीसरा 15 तारीख को है। 22 सितंबर अंत से गिनने पर तीसरा शनिवार है।","subtopic":"month-date-puzzles"},
  {"id":"reason-clock-calendar-180","question":"The minute hand of a faulty clock takes 63 minutes of correct time to complete one full round. How much does the clock gain or lose in 24 hours of correct time?","options":["Gains 72 minutes","Gains 68 4/7 minutes","Loses 68 4/7 minutes","Loses 72 minutes"],"answer":2,"explanation":"In 1440 true minutes the clock shows 1440 × 60/63 = 1371 3/7 minutes, so it loses 68 4/7 minutes. 72 comes from 3 × 24, taking the 3-minute lag per clock-hour instead of per 63 true minutes.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक दोषपूर्ण घड़ी की मिनट की सुई एक पूरा चक्कर लगाने में सही समय के 63 मिनट लेती है। सही समय के 24 घंटों में यह घड़ी कितनी तेज या धीमी चलती है?","optionsHi":["72 मिनट तेज","68 4/7 मिनट तेज","68 4/7 मिनट धीमी","72 मिनट धीमी"],"explanationHi":"1440 सही मिनट में घड़ी 1440 × 60/63 = 1371 3/7 मिनट दिखाती है, इसलिए वह 68 4/7 मिनट धीमी चलती है। 72, 3 × 24 से आता है, जिसमें 3 मिनट की देरी को 63 सही मिनट के बजाय प्रति घड़ी-घंटे पर लिया गया है।","subtopic":"faulty-clocks-mirror"},
  {"id":"reason-clock-calendar-181","question":"On which day of the week did 1 January 1901 fall?","options":["Sunday","Monday","Wednesday","Tuesday"],"answer":3,"explanation":"Odd days in 1900 years: 1600 → 0, 300 → 1 (100 years give 5, so 300 give 15 ≡ 1). So 31 Dec 1900 is Monday and 1 Jan 1901 is Tuesday. Monday comes from stopping at 31 December 1900.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1 जनवरी 1901 को सप्ताह का कौन-सा दिन था?","optionsHi":["रविवार","सोमवार","बुधवार","मंगलवार"],"explanationHi":"1900 वर्षों के विषम दिन: 1600 → 0, 300 → 1 (100 वर्षों से 5 मिलते हैं, इसलिए 300 से 15 ≡ 1)। अतः 31 दिसंबर 1900 को सोमवार है और 1 जनवरी 1901 को मंगलवार। सोमवार का उत्तर 31 दिसंबर 1900 पर रुक जाने से आता है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-182","question":"Five days before the day after tomorrow was a Sunday. What day of the week will it be 61 days after yesterday?","options":["Sunday","Friday","Monday","Saturday"],"answer":0,"explanation":"Day after tomorrow = today + 2; five days before it = today − 3 = Sunday, so today is Wednesday and yesterday was Tuesday. 61 ≡ 5 (mod 7), and Tuesday + 5 = Sunday. Counting 61 days from today instead gives Monday.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"परसों से पाँच दिन पहले रविवार था। कल से 61 दिन बाद सप्ताह का कौन-सा दिन होगा?","optionsHi":["रविवार","शुक्रवार","सोमवार","शनिवार"],"explanationHi":"परसों = आज + 2; उससे पाँच दिन पहले = आज − 3 = रविवार, इसलिए आज बुधवार है और बीता हुआ कल मंगलवार था। 61 ≡ 5 (मॉड 7), और मंगलवार + 5 = रविवार। इसके बजाय आज से 61 दिन गिनने पर सोमवार आता है।","subtopic":"day-of-week"},
  {"id":"reason-clock-calendar-183","question":"What is the angle between the hour hand and the minute hand of a clock at 7:17:15? (Give the smaller angle.)","options":["115.13°","106.5°","116.5°","244.88°"],"answer":0,"explanation":"Minute hand: 6° × (17 + 15/60) = 103.5°. Hour hand: 30° × 7 + 0.5° × (17 + 15/60) = 218.63°, since it also creeps during the minutes and seconds. The difference is 115.13°, so the smaller angle is 115.13°.","difficulty":"hard","questionHi":"7:17:15 बजे घड़ी की घंटे की सुई और मिनट की सुई के बीच का कोण कितना होगा? (छोटा कोण लीजिए।)","optionsHi":["115.13°","106.5°","116.5°","244.88°"],"explanationHi":"मिनट की सुई: 6° × (17 + 15/60) = 103.5°। घंटे की सुई: 30° × 7 + 0.5° × (17 + 15/60) = 218.63°, क्योंकि यह मिनटों और सेकंडों में भी खिसकती है। अंतर 115.13° है, इसलिए छोटा कोण 115.13° है।","subtopic":"clock-angles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-184","question":"What is the angle between the hour hand and the minute hand of a clock at 7:40:30? (Give the smaller angle.)","options":["10°","33°","12.75°","347.25°"],"answer":2,"explanation":"Minute hand: 6° × (40 + 30/60) = 243°. Hour hand: 30° × 7 + 0.5° × (40 + 30/60) = 230.25°, since it also creeps during the minutes and seconds. The difference is 12.75°, so the smaller angle is 12.75°.","difficulty":"hard","questionHi":"7:40:30 बजे घड़ी की घंटे की सुई और मिनट की सुई के बीच का कोण कितना होगा? (छोटा कोण लीजिए।)","optionsHi":["10°","33°","12.75°","347.25°"],"explanationHi":"मिनट की सुई: 6° × (40 + 30/60) = 243°। घंटे की सुई: 30° × 7 + 0.5° × (40 + 30/60) = 230.25°, क्योंकि यह मिनटों और सेकंडों में भी खिसकती है। अंतर 12.75° है, इसलिए छोटा कोण 12.75° है।","subtopic":"clock-angles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-185","question":"At 5:35 the hands of a clock enclose two angles on the dial. What is the larger (reflex) angle?","options":["317.5°","300°","42.5°","60°"],"answer":0,"explanation":"Hour hand at 30° × 5 + 0.5° × 35 = 167.5°, minute hand at 6° × 35 = 210°. The smaller angle is 42.5°, so the reflex angle is 360° − 42.5° = 317.5°.","difficulty":"hard","questionHi":"5:35 बजे घड़ी की सुइयाँ डायल पर दो कोण बनाती हैं। बड़ा (प्रवृद्ध) कोण कितना है?","optionsHi":["317.5°","300°","42.5°","60°"],"explanationHi":"घंटे की सुई 30° × 5 + 0.5° × 35 = 167.5° पर है, मिनट की सुई 6° × 35 = 210° पर। छोटा कोण 42.5° है, इसलिए प्रवृद्ध कोण 360° − 42.5° = 317.5° है।","subtopic":"clock-angles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-186","question":"By how many degrees does the (smaller) angle between the hands at 8:59 exceed the (smaller) angle between the hands at 9:45?","options":["114°","253°","107°","62°"],"answer":3,"explanation":"At 9:45: |30 × 9 − 5.5 × 45| gives 22.5° (smaller angle). At 8:59: 84.5°. The difference is 62°; ignoring the hour hand's drift gives wrong values.","difficulty":"hard","questionHi":"8:59 बजे सुइयों के बीच के (छोटे) कोण का मान 9:45 बजे के (छोटे) कोण से कितने डिग्री अधिक है?","optionsHi":["114°","253°","107°","62°"],"explanationHi":"9:45 बजे: |30 × 9 − 5.5 × 45| से छोटा कोण 22.5° मिलता है। 8:59 बजे: 84.5°। अंतर 62° है; घंटे की सुई का खिसकना छोड़ देने पर गलत मान मिलते हैं।","subtopic":"clock-angles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-187","question":"By how many degrees does the (smaller) angle between the hands at 5:45 exceed the (smaller) angle between the hands at 11:12?","options":["166.5°","1.5°","18°","193.5°"],"answer":1,"explanation":"At 5:45: |30 × 5 − 5.5 × 45| gives 97.5° (smaller angle). At 11:12: 96°. The difference is 1.5°; ignoring the hour hand's drift gives wrong values.","difficulty":"hard","questionHi":"5:45 बजे सुइयों के बीच के (छोटे) कोण का मान 11:12 बजे के (छोटे) कोण से कितने डिग्री अधिक है?","optionsHi":["166.5°","1.5°","18°","193.5°"],"explanationHi":"5:45 बजे: |30 × 5 − 5.5 × 45| से छोटा कोण 97.5° मिलता है। 11:12 बजे: 96°। अंतर 1.5° है; घंटे की सुई का खिसकना छोड़ देने पर गलत मान मिलते हैं।","subtopic":"clock-angles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-188","question":"Between 8:00 and 10:10 on the same day, through how many degrees does the minute hand gain over the hour hand?","options":["355°","65°","780°","715°"],"answer":3,"explanation":"Elapsed time is 130 minutes. The minute hand moves 6° per minute and the hour hand 0.5° per minute, so it gains 5.5° per minute: 5.5 × 130 = 715°. Using only 6° (minute hand alone) or 0.5° gives the traps.","difficulty":"moderate","questionHi":"उसी दिन 8:00 से 10:10 के बीच मिनट की सुई घंटे की सुई से कितने डिग्री आगे बढ़ जाती है (अर्थात उसका लाभ कितना होता है)?","optionsHi":["355°","65°","780°","715°"],"explanationHi":"बीता समय 130 मिनट है। मिनट की सुई प्रति मिनट 6° और घंटे की सुई 0.5° चलती है, इसलिए प्रति मिनट 5.5° का लाभ होता है: 5.5 × 130 = 715°। केवल 6° या केवल 0.5° लेने पर गलत विकल्प मिलते हैं।","subtopic":"clock-angles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-189","question":"Between 2:10 and 4:05 on the same day, through how many degrees does the minute hand gain over the hour hand?","options":["690°","272.5°","632.5°","57.5°"],"answer":2,"explanation":"Elapsed time is 115 minutes. The minute hand moves 6° per minute and the hour hand 0.5° per minute, so it gains 5.5° per minute: 5.5 × 115 = 632.5°. Using only 6° (minute hand alone) or 0.5° gives the traps.","difficulty":"moderate","questionHi":"उसी दिन 2:10 से 4:05 के बीच मिनट की सुई घंटे की सुई से कितने डिग्री आगे बढ़ जाती है (अर्थात उसका लाभ कितना होता है)?","optionsHi":["690°","272.5°","632.5°","57.5°"],"explanationHi":"बीता समय 115 मिनट है। मिनट की सुई प्रति मिनट 6° और घंटे की सुई 0.5° चलती है, इसलिए प्रति मिनट 5.5° का लाभ होता है: 5.5 × 115 = 632.5°। केवल 6° या केवल 0.5° लेने पर गलत विकल्प मिलते हैं।","subtopic":"clock-angles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-190","question":"At what time between 5 and 6 o'clock are the hands of a clock 120° apart for the first time?","options":["49 1/11 minutes past 5","5 5/11 minutes past 5","6 5/11 minutes past 5","2 5/11 minutes past 5"],"answer":1,"explanation":"At 5 o'clock the hour hand is 150° from 12 and the minute hand gains 5.5° per minute. Set (30 × 5 − 5.5m) = ±120 (mod 360) and keep 0 ≤ m < 60: m = 5 5/11; the two valid values are 5 5/11 and 49 1/11.","difficulty":"very-hard","questionHi":"5 और 6 बजे के बीच घड़ी की सुइयाँ पहली बार कब 120° की दूरी पर होंगी?","optionsHi":["5 बजकर 49 1/11 मिनट","5 बजकर 5 5/11 मिनट","5 बजकर 6 5/11 मिनट","5 बजकर 2 5/11 मिनट"],"explanationHi":"5 बजे घंटे की सुई 12 से 150° पर होती है और मिनट की सुई प्रति मिनट 5.5° का लाभ लेती है। (30 × 5 − 5.5m) = ±120 (mod 360) रखें और 0 ≤ m < 60 लें: m = 5 5/11; दोनों वैध मान 5 5/11 और 49 1/11 हैं।","subtopic":"clock-hands-positions","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-191","question":"At what time between 6 and 7 o'clock are the hands of a clock 75° apart for the second time?","options":["43 4/11 minutes past 6","46 4/11 minutes past 6","47 4/11 minutes past 6","19 1/11 minutes past 6"],"answer":1,"explanation":"At 6 o'clock the hour hand is 180° from 12 and the minute hand gains 5.5° per minute. Set (30 × 6 − 5.5m) = ±75 (mod 360) and keep 0 ≤ m < 60: m = 46 4/11; the two valid values are 19 1/11 and 46 4/11.","difficulty":"very-hard","questionHi":"6 और 7 बजे के बीच घड़ी की सुइयाँ दूसरी बार कब 75° की दूरी पर होंगी?","optionsHi":["6 बजकर 43 4/11 मिनट","6 बजकर 46 4/11 मिनट","6 बजकर 47 4/11 मिनट","6 बजकर 19 1/11 मिनट"],"explanationHi":"6 बजे घंटे की सुई 12 से 180° पर होती है और मिनट की सुई प्रति मिनट 5.5° का लाभ लेती है। (30 × 6 − 5.5m) = ±75 (mod 360) रखें और 0 ≤ m < 60 लें: m = 46 4/11; दोनों वैध मान 19 1/11 और 46 4/11 हैं।","subtopic":"clock-hands-positions","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-192","question":"At what time between 4 and 5 o'clock are the hands of a clock in opposite directions?","options":["54 6/11 minutes past 4","56 6/11 minutes past 4","55 6/11 minutes past 4","51 6/11 minutes past 4"],"answer":0,"explanation":"At 4 o'clock the hour hand is 120° from 12 and the minute hand gains 5.5° per minute. Set (30 × 4 − 5.5m) = ±180 (mod 360) and keep 0 ≤ m < 60: m = 54 6/11.","difficulty":"moderate","questionHi":"4 और 5 बजे के बीच घड़ी की सुइयाँ किस समय विपरीत दिशाओं में होंगी?","optionsHi":["4 बजकर 54 6/11 मिनट","4 बजकर 56 6/11 मिनट","4 बजकर 55 6/11 मिनट","4 बजकर 51 6/11 मिनट"],"explanationHi":"4 बजे घंटे की सुई 12 से 120° पर होती है और मिनट की सुई प्रति मिनट 5.5° का लाभ लेती है। (30 × 4 − 5.5m) = ±180 (mod 360) रखें और 0 ≤ m < 60 लें: m = 54 6/11।","subtopic":"clock-hands-positions","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-193","question":"How many times in a full day (24 hours) are the hands of a clock perpendicular to each other?","options":["44","42","46","22"],"answer":0,"explanation":"In 12 hours the minute hand laps the hour hand 11 times, and each lap passes through every relative position twice (θ and 360° − θ): 22 times in 12 hours, so 44 in 24 hours.","difficulty":"hard","questionHi":"एक पूरे दिन (24 घंटे) में घड़ी की सुइयाँ कितनी बार एक-दूसरे के लंबवत होती हैं?","optionsHi":["44","42","46","22"],"explanationHi":"12 घंटे में मिनट की सुई घंटे की सुई को 11 बार पार करती है, और प्रत्येक चक्र में प्रत्येक सापेक्ष स्थिति दो बार (θ और 360° − θ) आती है: 12 घंटे में 22 बार, अतः 24 घंटे में 44 बार।","subtopic":"clock-hands-positions","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-194","question":"How many times in a full day (24 hours) are the hands of a clock 150° apart?","options":["46","44","42","22"],"answer":1,"explanation":"In 12 hours the minute hand laps the hour hand 11 times, and each lap passes through every relative position twice (θ and 360° − θ): 22 times in 12 hours, so 44 in 24 hours.","difficulty":"hard","questionHi":"एक पूरे दिन (24 घंटे) में घड़ी की सुइयाँ कितनी बार 150° की दूरी पर होती हैं?","optionsHi":["46","44","42","22"],"explanationHi":"12 घंटे में मिनट की सुई घंटे की सुई को 11 बार पार करती है, और प्रत्येक चक्र में प्रत्येक सापेक्ष स्थिति दो बार (θ और 360° − θ) आती है: 12 घंटे में 22 बार, अतः 24 घंटे में 44 बार।","subtopic":"clock-hands-positions","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-195","question":"Starting exactly at 6:20 (and counting up to and including 12:00) on a 12-hour dial, how many times are the hands of a clock at right angles?","options":["10","12","11","9"],"answer":0,"explanation":"The relative angle grows 5.5° per minute, so a 90° event (θ or 360° − θ) recurs every 720/11 minutes. Listing exact times from 12:00 and keeping those in the window [6:20, 12:00] gives 10.","difficulty":"very-hard","questionHi":"12 घंटे वाले डायल पर ठीक 6:20 बजे से 12:00 बजे तक (दोनों समय सम्मिलित) घड़ी की सुइयाँ कितनी बार समकोण पर होती हैं?","optionsHi":["10","12","11","9"],"explanationHi":"सापेक्ष कोण प्रति मिनट 5.5° बढ़ता है, इसलिए 90° की स्थिति (θ या 360° − θ) हर 720/11 मिनट में दोहराई जाती है। 12:00 से सटीक समय निकालकर [6:20, 12:00] के भीतर वाले गिनने पर 10 मिलते हैं।","subtopic":"clock-hands-positions","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-196","question":"At what time between 2 and 3 o'clock is the minute hand exactly 20 minute-spaces ahead of the hour hand?","options":["54 6/11 minutes past 2","33 8/11 minutes past 2","32 8/11 minutes past 2","30 8/11 minutes past 2"],"answer":2,"explanation":"20 minute-spaces = 120°. The minute hand must be 120° ahead, so 5.5m − 30 × 2 = 120, giving m = 32 8/11. The value with the minute hand 120° BEHIND is the trap option.","difficulty":"very-hard","questionHi":"2 और 3 बजे के बीच किस समय मिनट की सुई घंटे की सुई से ठीक 20 मिनट-खाने आगे होगी?","optionsHi":["2 बजकर 54 6/11 मिनट","2 बजकर 33 8/11 मिनट","2 बजकर 32 8/11 मिनट","2 बजकर 30 8/11 मिनट"],"explanationHi":"20 मिनट-खाने = 120°। मिनट की सुई को 120° आगे होना है, इसलिए 5.5m − 30 × 2 = 120, जिससे m = 32 8/11। मिनट की सुई के 120° पीछे वाला मान जाल वाला विकल्प है।","subtopic":"clock-hands-positions","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-197","question":"The image of a clock in a plane mirror shows 2:29. What is the actual time?","options":["9:29","10:31","9:31","9:36"],"answer":2,"explanation":"For a mirror image, actual time = 11:60 − 2:29 = 9:31. (Subtract from 11:60, borrowing an hour, rather than from 12:00; the latter is the common slip.)","difficulty":"moderate","questionHi":"समतल दर्पण में घड़ी का प्रतिबिंब 2:29 दिखा रहा है। वास्तविक समय क्या है?","optionsHi":["9:29","10:31","9:31","9:36"],"explanationHi":"दर्पण के प्रतिबिंब में वास्तविक समय = 11:60 − 2:29 = 9:31। (घंटा उधार लेकर 11:60 में से घटाएँ, 12:00 में से नहीं; यही सामान्य भूल है।)","subtopic":"faulty-clocks-mirror","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-198","question":"The image of a clock in a plane mirror shows 11:46. What is the actual time?","options":["1:14","12:46","12:14","12:19"],"answer":2,"explanation":"For a mirror image, actual time = 11:60 − 11:46 = 12:14. (Subtract from 11:60, borrowing an hour, rather than from 12:00; the latter is the common slip.)","difficulty":"hard","questionHi":"समतल दर्पण में घड़ी का प्रतिबिंब 11:46 दिखा रहा है। वास्तविक समय क्या है?","optionsHi":["1:14","12:46","12:14","12:19"],"explanationHi":"दर्पण के प्रतिबिंब में वास्तविक समय = 11:60 − 11:46 = 12:14। (घंटा उधार लेकर 11:60 में से घटाएँ, 12:00 में से नहीं; यही सामान्य भूल है।)","subtopic":"faulty-clocks-mirror","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-199","question":"The mirror image of a clock shows 9:40. After how long will the actual clock first show 12:00?","options":["10 h 40 min","9 h 40 min","9 h 10 min","2 h 20 min"],"answer":1,"explanation":"Actual time = 11:60 − 9:40 = 2:20. From 2:20 to the next 12:00 is 9 h 40 min. Counting from the shown time 9:40 instead gives a wrong waiting time.","difficulty":"hard","questionHi":"घड़ी का दर्पण में प्रतिबिंब 9:40 दिखा रहा है। वास्तविक घड़ी कितनी देर बाद पहली बार 12:00 दिखाएगी?","optionsHi":["10 घंटे 40 मिनट","9 घंटे 40 मिनट","9 घंटे 10 मिनट","2 घंटे 20 मिनट"],"explanationHi":"वास्तविक समय = 11:60 − 9:40 = 2:20। 2:20 से अगले 12:00 तक 9 घंटे 40 मिनट होते हैं। दिखाए गए समय 9:40 से गिनने पर प्रतीक्षा समय गलत आता है।","subtopic":"faulty-clocks-mirror","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-200","question":"A clock gains 4 minutes every hour of true time. It is set right at 9:00 AM on Monday. What is the true time when the faulty clock shows 9:00 AM on Thursday?","options":["Thursday, 1:48 PM","Thursday, 4:12 AM","Thursday, 4:30 AM","Thursday, 5:00 AM"],"answer":2,"explanation":"In 60 true minutes the faulty clock shows 64. It has shown 4320 minutes, so true elapsed = 4320 × 60 / 64 = 4050 minutes (67 h 30 min). Add this to the start: Thursday, 4:30 AM.","difficulty":"hard","questionHi":"एक घड़ी वास्तविक समय के प्रत्येक घंटे में 4 मिनट तेज़ चलती है। इसे सोमवार को सुबह 9:00 बजे सही मिलाया गया। जब खराब घड़ी गुरुवार को सुबह 9:00 बजे दिखाए, तब वास्तविक समय क्या होगा?","optionsHi":["गुरुवार, दोपहर 1:48","गुरुवार, सुबह 4:12","गुरुवार, सुबह 4:30","गुरुवार, सुबह 5:00"],"explanationHi":"वास्तविक 60 मिनट में खराब घड़ी 64 मिनट दिखाती है। उसने 4320 मिनट दिखाए हैं, इसलिए वास्तविक बीता समय = 4320 × 60 / 64 = 4050 मिनट (67 घंटे 30 मिनट)। इसे आरंभ में जोड़ने पर गुरुवार, सुबह 4:30।","subtopic":"faulty-clocks-mirror","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-201","question":"A clock gains 4 minutes every hour of true time. It is set right at 8:00 AM on Tuesday. What is the true time when the faulty clock shows 4:00 AM on Wednesday?","options":["Wednesday, 2:45 AM","Wednesday, 5:20 AM","Wednesday, 2:40 AM","Wednesday, 3:15 AM"],"answer":0,"explanation":"In 60 true minutes the faulty clock shows 64. It has shown 1200 minutes, so true elapsed = 1200 × 60 / 64 = 1125 minutes (18 h 45 min). Add this to the start: Wednesday, 2:45 AM.","difficulty":"hard","questionHi":"एक घड़ी वास्तविक समय के प्रत्येक घंटे में 4 मिनट तेज़ चलती है। इसे मंगलवार को सुबह 8:00 बजे सही मिलाया गया। जब खराब घड़ी बुधवार को सुबह 4:00 बजे दिखाए, तब वास्तविक समय क्या होगा?","optionsHi":["बुधवार, सुबह 2:45","बुधवार, सुबह 5:20","बुधवार, सुबह 2:40","बुधवार, सुबह 3:15"],"explanationHi":"वास्तविक 60 मिनट में खराब घड़ी 64 मिनट दिखाती है। उसने 1200 मिनट दिखाए हैं, इसलिए वास्तविक बीता समय = 1200 × 60 / 64 = 1125 मिनट (18 घंटे 45 मिनट)। इसे आरंभ में जोड़ने पर बुधवार, सुबह 2:45।","subtopic":"faulty-clocks-mirror","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-202","question":"A clock loses 10 minutes every hour of true time. It is set right at 6:00 AM on Tuesday. What is the true time when the faulty clock shows 6:00 PM on Thursday?","options":["Friday, 6:30 AM","Friday, 6:00 AM","Friday, 4:00 AM","Thursday, 8:00 AM"],"answer":1,"explanation":"In 60 true minutes the faulty clock shows 50. It has shown 3600 minutes, so true elapsed = 3600 × 60 / 50 = 4320 minutes (72 h 0 min). Add this to the start: Friday, 6:00 AM.","difficulty":"very-hard","questionHi":"एक घड़ी वास्तविक समय के प्रत्येक घंटे में 10 मिनट धीमी चलती है। इसे मंगलवार को सुबह 6:00 बजे सही मिलाया गया। जब खराब घड़ी गुरुवार को शाम 6:00 बजे दिखाए, तब वास्तविक समय क्या होगा?","optionsHi":["शुक्रवार, सुबह 6:30","शुक्रवार, सुबह 6:00","शुक्रवार, सुबह 4:00","गुरुवार, सुबह 8:00"],"explanationHi":"वास्तविक 60 मिनट में खराब घड़ी 50 मिनट दिखाती है। उसने 3600 मिनट दिखाए हैं, इसलिए वास्तविक बीता समय = 3600 × 60 / 50 = 4320 मिनट (72 घंटे 0 मिनट)। इसे आरंभ में जोड़ने पर शुक्रवार, सुबह 6:00।","subtopic":"faulty-clocks-mirror","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-203","question":"A wall clock strikes as many times as the hour shows (once at 1 o'clock, twice at 2 o'clock, and so on), with equal gaps between strikes. It takes 9 seconds to strike 4 o'clock (from the first strike to the last). How many seconds does it take to strike 7 o'clock?","options":["15.75 seconds","21 seconds","24 seconds","18 seconds"],"answer":3,"explanation":"4 strikes have 3 gaps, so each gap is 9 / 3 = 3 s. 7 strikes have 6 gaps: 6 × 3 = 18 s. Dividing by the number of strikes instead of the gaps is the trap.","difficulty":"hard","questionHi":"एक दीवार घड़ी जितने बजे होते हैं उतनी बार घंटा बजाती है (1 बजे एक बार, 2 बजे दो बार, इत्यादि), और घंटों के बीच का अंतराल बराबर रहता है। 4 बजे के घंटे बजने में (पहले घंटे से अंतिम घंटे तक) 9 सेकंड लगते हैं। 7 बजे के घंटे बजने में कितने सेकंड लगेंगे?","optionsHi":["15.75 seconds","21 seconds","24 seconds","18 seconds"],"explanationHi":"4 घंटों में 3 अंतराल होते हैं, इसलिए प्रत्येक अंतराल 9 / 3 = 3 सेकंड का है। 7 घंटों में 6 अंतराल: 6 × 3 = 18 सेकंड। घंटों की संख्या से भाग देना जाल है।","subtopic":"faulty-clocks-mirror","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-204","question":"If 7 August 1956 was a Tuesday, which day of the week is 26 January 1974?","options":["Sunday","Friday","Saturday","Wednesday"],"answer":2,"explanation":"Count the days between the two dates: 6381. Since 6381 = 7 × 911 + 4, the day moves ahead by 4. Tuesday + 4 = Saturday.","difficulty":"hard","questionHi":"यदि 7 अगस्त 1956 को मंगलवार था, तो 26 जनवरी 1974 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["रविवार","शुक्रवार","शनिवार","बुधवार"],"explanationHi":"दोनों तिथियों के बीच के दिन गिनें: 6381। क्योंकि 6381 = 7 × 911 + 4, इसलिए दिन 4 आगे खिसकता है। मंगलवार + 4 = शनिवार।","subtopic":"day-of-week","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-205","question":"If 17 June 1966 was a Friday, which day of the week is 4 May 2030?","options":["Saturday","Friday","Sunday","Monday"],"answer":0,"explanation":"Count the days between the two dates: 23332. Since 23332 = 7 × 3333 + 1, the day moves ahead by 1. Friday + 1 = Saturday.","difficulty":"hard","questionHi":"यदि 17 जून 1966 को शुक्रवार था, तो 4 मई 2030 को सप्ताह का कौन-सा दिन होगा?","optionsHi":["शनिवार","शुक्रवार","रविवार","सोमवार"],"explanationHi":"दोनों तिथियों के बीच के दिन गिनें: 23332। क्योंकि 23332 = 7 × 3333 + 1, इसलिए दिन 1 आगे खिसकता है। शुक्रवार + 1 = शनिवार।","subtopic":"day-of-week","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-206","question":"Given that 1 January 2001 was a Monday, on which day of the week did 17 April 1972 fall?","options":["Tuesday","Wednesday","Sunday","Monday"],"answer":3,"explanation":"The gap from 1 January 2001 is 10486 days (counting every leap day, and remembering that century years like 1900 and 2100 are not leap years). 10486 mod 7 = 0, so moving back gives Monday.","difficulty":"hard","questionHi":"यह दिया है कि 1 जनवरी 2001 को सोमवार था। 17 अप्रैल 1972 को सप्ताह का कौन-सा दिन था/होगा?","optionsHi":["मंगलवार","बुधवार","रविवार","सोमवार"],"explanationHi":"1 जनवरी 2001 से अंतर 10486 दिन है (प्रत्येक लीप दिन गिनते हुए, और यह ध्यान रखते हुए कि 1900 तथा 2100 जैसे शताब्दी वर्ष लीप वर्ष नहीं हैं)। 10486 mod 7 = 0, इसलिए पीछे जाने पर सोमवार मिलता है।","subtopic":"day-of-week","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-207","question":"How many Thursdays are there from 21 June 1993 to 20 August 1993, both dates included?","options":["8","9","10","11"],"answer":1,"explanation":"Both ends included, the span has 61 days = 8 weeks + 5 extra day(s). Every full week gives one Thursday; the first 5 day(s) starting from Monday include a Thursday. Total 9.","difficulty":"hard","questionHi":"21 जून 1993 से 20 अगस्त 1993 तक (दोनों तिथियाँ सम्मिलित) कितने गुरुवार पड़ते हैं?","optionsHi":["8","9","10","11"],"explanationHi":"दोनों सिरे जोड़ने पर अवधि 61 दिन = 8 सप्ताह + 5 अतिरिक्त दिन है। प्रत्येक पूरा सप्ताह एक गुरुवार देता है; सोमवार से आरंभ होने वाले पहले 5 दिनों में गुरुवार आता है। कुल 9।","subtopic":"day-of-week","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-208","question":"How many odd days are there in the 65 years from 1 January 1851 to 31 December 1915?","options":["3","2","5","4"],"answer":0,"explanation":"Total days = 23740 (365 × 65 plus 15 leap days, remembering century years not divisible by 400 are not leap). 23740 = 7 × 3391 + 3, so there are 3 odd days.","difficulty":"very-hard","questionHi":"1 जनवरी 1851 से 31 दिसंबर 1915 तक के 65 वर्षों में कितने विषम दिन होते हैं?","optionsHi":["3","2","5","4"],"explanationHi":"कुल दिन = 23740 (365 × 65 और 15 लीप दिन, यह ध्यान रखते हुए कि 400 से विभाज्य न होने वाले शताब्दी वर्ष लीप नहीं होते)। 23740 = 7 × 3391 + 3, इसलिए 3 विषम दिन हैं।","subtopic":"day-of-week","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-209","question":"If the second Friday of January 2069 falls on a certain date, and 1 January 2069 was a Tuesday, on which date does it fall?","options":["18","4","11","12"],"answer":2,"explanation":"The first Friday is on date 4, and each later one is 7 days after, so the second is date 11.","difficulty":"moderate","questionHi":"यदि जनवरी 2069 का दूसरा शुक्रवार किसी तारीख को पड़ता है और 1 जनवरी 2069 को मंगलवार था, तो वह किस तारीख को पड़ता है?","optionsHi":["18","4","11","12"],"explanationHi":"पहला शुक्रवार 4 तारीख को है, और बाद वाले हर 7 दिन बाद आते हैं, इसलिए दूसरा शुक्रवार 11 तारीख को है।","subtopic":"day-of-week","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-210","question":"The calendar of the year 1978 will next be exactly the same (every date on the same weekday) in which year?","options":["1983","1989","1985","1984"],"answer":1,"explanation":"1978 is an ordinary year (365 days = 1 odd day); add odd days year by year until the total is a multiple of 7 with the leap-year pattern matching. This first happens in 1989.","difficulty":"hard","questionHi":"वर्ष 1978 का कैलेंडर अगली बार किस वर्ष में बिल्कुल वैसा ही होगा (प्रत्येक तारीख उसी वार को)?","optionsHi":["1983","1989","1985","1984"],"explanationHi":"1978 सामान्य वर्ष है (365 दिन = 1 विषम दिन); वर्ष-दर-वर्ष विषम दिन जोड़ते जाएँ जब तक योग 7 का गुणज न हो जाए और लीप-वर्ष का क्रम भी मेल खाए। ऐसा पहली बार 1989 में होता है।","subtopic":"calendar-repeat-leap","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-211","question":"The calendar of the year 1973 will next be exactly the same (every date on the same weekday) in which year?","options":["1978","1979","1980","1984"],"answer":1,"explanation":"1973 is an ordinary year (365 days = 1 odd day); add odd days year by year until the total is a multiple of 7 with the leap-year pattern matching. This first happens in 1979.","difficulty":"hard","questionHi":"वर्ष 1973 का कैलेंडर अगली बार किस वर्ष में बिल्कुल वैसा ही होगा (प्रत्येक तारीख उसी वार को)?","optionsHi":["1978","1979","1980","1984"],"explanationHi":"1973 सामान्य वर्ष है (365 दिन = 1 विषम दिन); वर्ष-दर-वर्ष विषम दिन जोड़ते जाएँ जब तक योग 7 का गुणज न हो जाए और लीप-वर्ष का क्रम भी मेल खाए। ऐसा पहली बार 1979 में होता है।","subtopic":"calendar-repeat-leap","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-212","question":"In the year 2062, on how many occasions does the 13th of a month fall on a Sunday?","options":["0","3","2","1"],"answer":3,"explanation":"Find the weekday of the 13th for each month by adding the month lengths modulo 7 (31 → +3, 30 → +2, February → +0 or +1). In 2062 the weekdays of the 13ths in order are Fri, Mon, Mon, Thu, Sat, Tue, Thu, Sun, Wed, Fri, Mon, Wed, and Sunday occurs 1 time.","difficulty":"hard","questionHi":"वर्ष 2062 में कितनी बार किसी महीने की 13 तारीख रविवार को पड़ती है?","optionsHi":["0","3","2","1"],"explanationHi":"प्रत्येक महीने की 13 तारीख का वार महीनों की लंबाई mod 7 जोड़कर निकालें (31 → +3, 30 → +2, फ़रवरी → +0 या +1)। 2062 में 13 तारीखों के वार क्रम से शुक्रवार, सोमवार, सोमवार, गुरुवार, शनिवार, मंगलवार, गुरुवार, रविवार, बुधवार, शुक्रवार, सोमवार, बुधवार हैं, और रविवार 1 बार आता है।","subtopic":"calendar-repeat-leap","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-213","question":"How many leap years are there from the year 1965 to the year 2117, both included?","options":["39","38","37","36"],"answer":2,"explanation":"Multiples of 4 in the range: 38. Remove the century years that are not multiples of 400 (2100). That leaves 37 leap years.","difficulty":"hard","questionHi":"वर्ष 1965 से वर्ष 2117 तक (दोनों सम्मिलित) कितने लीप वर्ष हैं?","optionsHi":["39","38","37","36"],"explanationHi":"सीमा में 4 के गुणज: 38। उन शताब्दी वर्षों को हटाएँ जो 400 के गुणज नहीं हैं (2100)। शेष 37 लीप वर्ष हैं।","subtopic":"calendar-repeat-leap","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-214","question":"The dates from 1 March to 31 December of the leap year 1932 fall on the same weekdays as the same dates of which later year? (Give the first such year.)","options":["1936","1943","1937","1938"],"answer":3,"explanation":"Only the weekday of 1 March matters, so February's length is irrelevant. Moving from one 1 March to the next adds 1 odd day, or 2 if the new year's February has 29 days. Starting at 1 March 1932 and adding these until the total is a multiple of 7, the weekday first returns in 1938.","difficulty":"very-hard","questionHi":"लीप वर्ष 1932 में 1 मार्च से 31 दिसंबर तक की तारीखें किस बाद के वर्ष की उन्हीं तारीखों के वारों से मेल खाती हैं? (ऐसा पहला वर्ष बताइए।)","optionsHi":["1936","1943","1937","1938"],"explanationHi":"केवल 1 मार्च का वार मायने रखता है, इसलिए फ़रवरी की लंबाई अप्रासंगिक है। 1 मार्च 1932 से चलकर एक 1 मार्च से अगले 1 मार्च तक 1 विषम दिन जुड़ता है, या 2 यदि नए वर्ष की फ़रवरी 29 दिन की हो। इन्हें तब तक जोड़ें जब तक योग 7 का गुणज न हो जाए, तो वही वार पहली बार 1938 में लौटता है।","subtopic":"calendar-repeat-leap","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-215","question":"A leap year begins on a Monday. Which two days of the week occur 53 times in that year?","options":["Monday","Tuesday and Wednesday","Sunday and Monday","Monday and Tuesday"],"answer":3,"explanation":"366 days = 52 weeks + 2 days. The two extra days are the first two days of the year: Monday and Tuesday.","difficulty":"hard","questionHi":"एक लीप वर्ष सोमवार से आरंभ होता है। उस वर्ष में सप्ताह के कौन-से दो दिन 53 बार आते हैं?","optionsHi":["सोमवार","मंगलवार और बुधवार","रविवार और सोमवार","सोमवार और मंगलवार"],"explanationHi":"366 दिन = 52 सप्ताह + 2 दिन। दो अतिरिक्त दिन वर्ष के पहले दो दिन हैं: सोमवार और मंगलवार।","subtopic":"calendar-repeat-leap","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-216","question":"In a month of 31 days, the sum of the dates of all the Saturdays is 62. On which day of the week does the 30th of that month fall?","options":["Wednesday","Thursday","Tuesday","Friday"],"answer":0,"explanation":"If there are 4 such days with first date a, the sum is 4a + 7 × 6 = 62, so a = 5. Hence Saturdays fall on 5, 12, 19, 26, so the 30th is Wednesday.","difficulty":"very-hard","questionHi":"31 दिनों वाले एक महीने में सभी शनिवार की तारीखों का योग 62 है। उस महीने की 30 तारीख को सप्ताह का कौन-सा दिन पड़ता है?","optionsHi":["बुधवार","गुरुवार","मंगलवार","शुक्रवार"],"explanationHi":"यदि ऐसे 4 दिन हैं और पहली तारीख a है, तो योग 4a + 7 × 6 = 62, अतः a = 5। इसलिए शनिवार की तारीखें 5, 12, 19, 26 हैं, और 30 तारीख को बुधवार है।","subtopic":"month-date-puzzles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-217","question":"In a month of 30 days, the sum of the dates of all the Tuesdays is 62. On which day of the week does the 20th of that month fall?","options":["Wednesday","Thursday","Tuesday","Friday"],"answer":0,"explanation":"If there are 4 such days with first date a, the sum is 4a + 7 × 6 = 62, so a = 5. Hence Tuesdays fall on 5, 12, 19, 26, so the 20th is Wednesday.","difficulty":"very-hard","questionHi":"30 दिनों वाले एक महीने में सभी मंगलवार की तारीखों का योग 62 है। उस महीने की 20 तारीख को सप्ताह का कौन-सा दिन पड़ता है?","optionsHi":["बुधवार","गुरुवार","मंगलवार","शुक्रवार"],"explanationHi":"यदि ऐसे 4 दिन हैं और पहली तारीख a है, तो योग 4a + 7 × 6 = 62, अतः a = 5। इसलिए मंगलवार की तारीखें 5, 12, 19, 26 हैं, और 20 तारीख को बुधवार है।","subtopic":"month-date-puzzles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-218","question":"A month of 31 days has five Thursdays and five Tuesdays. On which day of the week does that month begin?","options":["Tuesday","Thursday","Wednesday","Monday"],"answer":0,"explanation":"A 31-day month has 3 weekday(s) that occur 5 times, namely the first 3 days of the month. Both Thursday and Tuesday must be among them, which fixes the 1st as Tuesday (the five-times days are Tuesday, Wednesday, Thursday).","difficulty":"hard","questionHi":"31 दिनों वाले एक महीने में पाँच गुरुवार और पाँच मंगलवार हैं। वह महीना सप्ताह के किस दिन से आरंभ होता है?","optionsHi":["मंगलवार","गुरुवार","बुधवार","सोमवार"],"explanationHi":"31 दिनों वाले महीने में 3 वार 5 बार आते हैं, अर्थात महीने के पहले 3 दिनों वाले वार। गुरुवार और मंगलवार दोनों उनमें होने चाहिए, जिससे पहली तारीख मंगलवार तय होती है (पाँच बार आने वाले वार मंगलवार, बुधवार, गुरुवार हैं)।","subtopic":"month-date-puzzles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-219","question":"In a month of 30 days there are five Fridays, and exactly 2 of them fall on odd dates. What day of the week is the 10th of that month?","options":["Monday","Sunday","Friday","Saturday"],"answer":3,"explanation":"Five Fridays means dates a, a + 7, a + 14, a + 21, a + 28, with parity alternating. Exactly 2 odd dates forces a = 2 (dates 2, 9, 16, 23, 30), so the 1st is Thursday and the 10th is Saturday.","difficulty":"very-hard","questionHi":"30 दिनों वाले एक महीने में पाँच शुक्रवार हैं और उनमें से ठीक 2 विषम तारीखों पर पड़ते हैं। उस महीने की 10 तारीख को सप्ताह का कौन-सा दिन है?","optionsHi":["सोमवार","रविवार","शुक्रवार","शनिवार"],"explanationHi":"पाँच शुक्रवार का अर्थ है तारीखें a, a + 7, a + 14, a + 21, a + 28, जिनकी समता बारी-बारी बदलती है। ठीक 2 विषम तारीखें होने से a = 2 (तारीखें 2, 9, 16, 23, 30), इसलिए 1 तारीख को गुरुवार है और 10 तारीख को शनिवार।","subtopic":"month-date-puzzles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-220","question":"In a month of 30 days, the second Sunday falls on the 10th. On which day of the week does the month end?","options":["Sunday","Monday","Friday","Saturday"],"answer":3,"explanation":"The first Sunday is on 3, so the 1st is Friday. The last date 30 is 29 days later, and 29 mod 7 = 1, giving Saturday.","difficulty":"moderate","questionHi":"30 दिनों वाले एक महीने में दूसरा रविवार 10 तारीख को पड़ता है। महीने का अंतिम दिन सप्ताह के किस वार को पड़ेगा?","optionsHi":["रविवार","सोमवार","शुक्रवार","शनिवार"],"explanationHi":"पहला रविवार 3 तारीख को है, इसलिए 1 तारीख को शुक्रवार है। अंतिम तारीख 30 उसके 29 दिन बाद है और 29 mod 7 = 1, जिससे शनिवार मिलता है।","subtopic":"month-date-puzzles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-221","question":"In a month of 29 days, the third Friday falls on the 16th. On which day of the week does the month end?","options":["Wednesday","Saturday","Thursday","Friday"],"answer":2,"explanation":"The first Friday is on 2, so the 1st is Thursday. The last date 29 is 28 days later, and 28 mod 7 = 0, giving Thursday.","difficulty":"moderate","questionHi":"29 दिनों वाले एक महीने में तीसरा शुक्रवार 16 तारीख को पड़ता है। महीने का अंतिम दिन सप्ताह के किस वार को पड़ेगा?","optionsHi":["बुधवार","शनिवार","गुरुवार","शुक्रवार"],"explanationHi":"पहला शुक्रवार 2 तारीख को है, इसलिए 1 तारीख को गुरुवार है। अंतिम तारीख 29 उसके 28 दिन बाद है और 28 mod 7 = 0, जिससे गुरुवार मिलता है।","subtopic":"month-date-puzzles","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-222","question":"A cube of side 4 cm is coloured as follows (left, right, back, bottom faces: blue; front face: unpainted; top face: red). It is cut into 1 cm cubes. How many small cubes have at least one blue face and no red face?","options":["38","44","36","34"],"answer":2,"explanation":"Split the 4³ small cubes into corners (8), edge cubes (12 edges × 2) and face cubes (6 faces × 4). Qualifying corners: 4; edges whose two faces qualify: 8 × 2 = 16; faces: 4 × 4 = 16. Total 36.","difficulty":"very-hard","questionHi":"4 सेमी भुजा वाले एक घन को इस प्रकार रंगा गया है (बायाँ, दायाँ, पीछे वाला, निचला फलक: नीला; सामने वाला फलक: बिना रंग का; ऊपरी फलक: लाल)। इसे 1 सेमी वाले छोटे घनों में काटा जाता है। कितने छोटे घनों के कम से कम एक नीला फलक है और कोई लाल फलक नहीं है?","optionsHi":["38","44","36","34"],"explanationHi":"4³ छोटे घनों को कोनों (8), कोर वाले घनों (12 कोर × 2) और फलक वाले घनों (6 फलक × 4) में बाँटें। शर्त पूरी करने वाले कोने: 4; वे कोरें जिनके दोनों फलक शर्त पूरी करते हैं: 8 × 2 = 16; फलक: 4 × 4 = 16। कुल 36।","subtopic":"cubes-dice","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-223","question":"A cube of side 5 cm is coloured as follows (left, right, top faces: red; front face: blue; back, bottom faces: unpainted). It is cut into 1 cm cubes. How many small cubes have exactly two red faces and no blue face?","options":["16","5","11","8"],"answer":3,"explanation":"Split the 5³ small cubes into corners (8), edge cubes (12 edges × 3) and face cubes (6 faces × 9). Qualifying corners: 2; edges whose two faces qualify: 2 × 3 = 6; faces: 0 × 9 = 0. Total 8.","difficulty":"very-hard","questionHi":"5 सेमी भुजा वाले एक घन को इस प्रकार रंगा गया है (बायाँ, दायाँ, ऊपरी फलक: लाल; सामने वाला फलक: नीला; पीछे वाला, निचला फलक: बिना रंग का)। इसे 1 सेमी वाले छोटे घनों में काटा जाता है। कितने छोटे घनों के ठीक दो लाल फलक हैं और कोई नीला फलक नहीं है?","optionsHi":["16","5","11","8"],"explanationHi":"5³ छोटे घनों को कोनों (8), कोर वाले घनों (12 कोर × 3) और फलक वाले घनों (6 फलक × 9) में बाँटें। शर्त पूरी करने वाले कोने: 2; वे कोरें जिनके दोनों फलक शर्त पूरी करते हैं: 2 × 3 = 6; फलक: 0 × 9 = 0। कुल 8।","subtopic":"cubes-dice","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-224","question":"A cube of side 6 cm is coloured as follows (left, bottom, top faces: red; right, front, back faces: blue). It is cut into 1 cm cubes. How many small cubes have three painted faces (of any colours)?","options":["12","4","16","8"],"answer":3,"explanation":"Split the 6³ small cubes into corners (8), edge cubes (12 edges × 4) and face cubes (6 faces × 16). Qualifying corners: 8; edges whose two faces qualify: 0 × 4 = 0; faces: 0 × 16 = 0. Total 8.","difficulty":"very-hard","questionHi":"6 सेमी भुजा वाले एक घन को इस प्रकार रंगा गया है (बायाँ, निचला, ऊपरी फलक: लाल; दायाँ, सामने वाला, पीछे वाला फलक: नीला)। इसे 1 सेमी वाले छोटे घनों में काटा जाता है। कितने छोटे घनों के तीन रंगे फलक हैं (किसी भी रंग के)?","optionsHi":["12","4","16","8"],"explanationHi":"6³ छोटे घनों को कोनों (8), कोर वाले घनों (12 कोर × 4) और फलक वाले घनों (6 फलक × 16) में बाँटें। शर्त पूरी करने वाले कोने: 8; वे कोरें जिनके दोनों फलक शर्त पूरी करते हैं: 0 × 4 = 0; फलक: 0 × 16 = 0। कुल 8।","subtopic":"cubes-dice","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-225","question":"A cube with six different symbols on its faces is shown in 2 positions. In each position three visible faces are listed in anticlockwise order around the corner nearest to you: (%, #, *) ; (@, $, *). Which symbol lies on the face opposite to *?","options":["&","%","@","#"],"answer":0,"explanation":"Faces seen together in one view are adjacent, never opposite. * is seen next to %, #, @, $, which leaves only & as the face that can be opposite it.","difficulty":"very-hard","questionHi":"छह अलग-अलग चिह्नों वाला एक घन 2 स्थितियों में दिखाया गया है। प्रत्येक स्थिति में आपके सबसे निकट के कोने के चारों ओर वामावर्त क्रम में तीन दिखने वाले फलक दिए गए हैं: (%, #, *) ; (@, $, *)। * के सम्मुख फलक पर कौन-सा चिह्न है?","optionsHi":["&","%","@","#"],"explanationHi":"किसी एक स्थिति में साथ दिखने वाले फलक आसन्न होते हैं, सम्मुख नहीं। * के साथ %, #, @, $ दिखे हैं, इसलिए उसके सम्मुख केवल & बच जाता है।","subtopic":"cubes-dice","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-226","question":"A cube with six different symbols on its faces is shown in 2 positions. In each position three visible faces are listed in anticlockwise order around the corner nearest to you: (Q, U, T) ; (S, U, R). Which symbol lies on the face opposite to R?","options":["Q","T","U","S"],"answer":1,"explanation":"Adjacency alone leaves Q or T as possible opposites of R; the anticlockwise order of the faces in the views decides between them. Checking every placement of the symbols that fits all the views gives T.","difficulty":"very-hard","questionHi":"छह अलग-अलग चिह्नों वाला एक घन 2 स्थितियों में दिखाया गया है। प्रत्येक स्थिति में आपके सबसे निकट के कोने के चारों ओर वामावर्त क्रम में तीन दिखने वाले फलक दिए गए हैं: (Q, U, T) ; (S, U, R)। R के सम्मुख फलक पर कौन-सा चिह्न है?","optionsHi":["Q","T","U","S"],"explanationHi":"केवल आसन्नता से R के सम्मुख के लिए Q या T बचते हैं; स्थितियों में फलकों का वामावर्त क्रम इनमें से एक चुनता है। सभी स्थितियों से मेल खाने वाले चिह्न-विन्यासों की जाँच करने पर T मिलता है।","subtopic":"cubes-dice","source":"SSC CGL · IBPS PO Mains · SBI PO"},
  {"id":"reason-clock-calendar-227","question":"A standard-looking die (opposite faces always add to 7) rests with 5 on top, 6 facing you and 3 on its right. It is rolled backward, then rolled forward (towards the front), then rolled to the right, then rolled to the left, then rolled forward (towards the front), each time by one quarter turn without slipping. Which number is now on the top face?","options":["4","1","5","6"],"answer":1,"explanation":"Track (top/front/right) after each move: start 5/6/3, then 6/2/3, 5/6/3, 4/6/5, 5/6/3, 1/5/3. Opposite faces sum to 7, so the top face is 1.","difficulty":"very-hard","questionHi":"एक पासा (सम्मुख फलकों का योग सदैव 7) इस प्रकार रखा है कि ऊपर 5, आपकी ओर 6 और दाईं ओर 3 है। इसे पीछे की ओर लुढ़काया, फिर आगे (सामने की ओर) लुढ़काया, फिर दाईं ओर लुढ़काया, फिर बाईं ओर लुढ़काया, फिर आगे (सामने की ओर) लुढ़काया, प्रत्येक बार एक चौथाई चक्कर बिना फिसले। अब ऊपरी फलक पर कौन-सी संख्या है?","optionsHi":["4","1","5","6"],"explanationHi":"प्रत्येक चाल के बाद (ऊपर/सामने/दाएँ) देखें: आरंभ 5/6/3, फिर 6/2/3, 5/6/3, 4/6/5, 5/6/3, 1/5/3। सम्मुख फलकों का योग 7 है, इसलिए ऊपरी फलक पर 1 है।","subtopic":"cubes-dice","source":"SSC CGL · IBPS PO Mains · SBI PO"},
];

